// 欧洲K-9完整课程数据库
// 参照英国Key Stage体系、德国和法国教学大纲
// European K-9 Complete Curriculum Database
// Aligned with UK Key Stage system, German and French curricula

const curriculumData = {

  // ============================================================
  // 幼儿园 (Age 3-6, EYFS/Key Stage 0)
  // ============================================================
  kindergarten: {

    math: [
      { topic: '数数1到5', zh: '学习从1数到5是数学启蒙的第一步。通过点数手指、积木或水果等实物，让孩子理解每个数字代表"多少"。一边指着物品一边大声说出数字，帮助孩子建立一一对应的概念。例如，拿3个苹果，逐个点数"1、2、3"，让孩子感受数字与数量的联系。', en: 'Learning to count from 1 to 5 is the first step in mathematical development. By pointing at and counting real objects like fingers, blocks, or fruit, children understand that each number represents "how many." Pointing at items while saying numbers aloud helps build one-to-one correspondence. For example, take 3 apples and count "1, 2, 3" one by one, helping children connect numbers with quantities.', age: '3-4' },
      { topic: '数数1到10', zh: '在掌握1到5的基础上，扩展到1到10的数数。使用数数歌、数数绘本和十格阵(Ten Frame)等工具，帮助孩子建立对10以内数字的直观认识。练习从任意数字开始数，而不仅仅从1开始，这有助于培养数感。', en: 'Building on counting 1 to 5, extend counting to 1 to 10. Use counting songs, picture books, and tools like ten frames to help children develop intuitive understanding of numbers within 10. Practice counting on from any number, not just starting from 1, which helps develop number sense.', age: '3-5' },
      { topic: '数数1到20', zh: '进一步扩展数数范围到20。重点理解11到20的构成规律——"十和几"的概念。使用数轴、百数表的前两行和实物分组（如一捆10根吸管加几根散的），帮助孩子理解两位数的含义。', en: 'Further extend counting range to 20. Focus on understanding the pattern of numbers 11 to 20 — the concept of "ten and some more." Use number lines, the first two rows of a hundred chart, and grouping objects (like a bundle of 10 straws plus a few loose ones) to help children understand the meaning of two-digit numbers.', age: '4-6' },
      { topic: '认识数字0', zh: '理解0的含义——0表示"没有"或"空"。通过具体情境引入：盘子里原来有3块饼干，全吃完了，盘子里还有几块？答案是0。0也是一个重要的数字，它占有一个位置，在数轴上也有自己的位置。', en: 'Understand the meaning of 0 — zero means "none" or "empty." Introduce through concrete situations: there were 3 cookies on a plate, all were eaten, how many are left? The answer is 0. Zero is an important number that occupies a position and has its own place on the number line.', age: '4-5' },
      { topic: '比较多少', zh: '学习比较两组物品的多少。通过一一配对的方法，将两组物品逐个对应排列，多出来的那组就是"多"，不够配对的那组就是"少"。如果刚好一一配对，就是"一样多"。使用"比……多""比……少""和……一样多"等语言描述比较结果。', en: 'Learn to compare which group has more or fewer items. Using one-to-one matching, pair items from two groups one by one. The group with leftover items is "more," the group that runs out first is "fewer." If items match perfectly, the groups are "the same." Use language like "more than," "fewer than," and "the same as" to describe comparisons.', age: '3-5' },
      { topic: '比较大小', zh: '学习比较数字的大小。理解数字在数轴上的位置越往右越大，越往左越小。使用"大于""小于""等于"来描述两个数字的关系。通过实物比较（如两堆糖果哪堆多）和数字比较两种方式来练习。', en: 'Learn to compare the size of numbers. Understand that on a number line, positions further to the right represent larger numbers, and positions further to the left represent smaller numbers. Use "greater than," "less than," and "equal to" to describe the relationship between two numbers. Practice through both object comparison and number comparison.', age: '4-6' },
      { topic: '认识圆形', zh: '认识圆形的基本特征：圆是弯弯的线围成的，没有角，没有直的边。在日常生活中找圆形：太阳、车轮、硬币、盘子等都是圆形。用手指沿着圆形的轮廓描画，感受圆形的曲线特征。尝试用圆规或沿着圆形物体描画来画出圆形。', en: 'Recognize the basic features of a circle: it is formed by a curved line, has no corners, and has no straight edges. Find circles in daily life: the sun, wheels, coins, and plates are all circular. Trace the outline of a circle with your finger to feel its curved characteristics. Try drawing circles using a compass or by tracing around circular objects.', age: '3-5' },
      { topic: '认识正方形和长方形', zh: '认识正方形：有4条一样长的边和4个直角。认识长方形：也有4个直角，但只有对边一样长。在生活中寻找正方形和长方形：窗户、书本封面、手帕等。用小棒摆出正方形和长方形，比较它们的相同点和不同点。', en: 'Recognize squares: 4 equal sides and 4 right angles. Recognize rectangles: also 4 right angles, but only opposite sides are equal. Find squares and rectangles in daily life: windows, book covers, and handkerchiefs. Use sticks to form squares and rectangles, comparing their similarities and differences.', age: '3-5' },
      { topic: '认识三角形', zh: '认识三角形：由3条边围成，有3个角。三角形可以有不同形状——有的瘦长，有的矮胖，但只要3条边3个角就是三角形。用纸剪出不同形状的三角形，用小棒摆三角形，在生活中找三角形：三角尺、屋顶、三角旗等。', en: 'Recognize triangles: formed by 3 sides with 3 corners. Triangles can have different shapes — some are tall and thin, some are short and wide, but as long as there are 3 sides and 3 corners, it is a triangle. Cut different triangles from paper, form triangles with sticks, and find triangles in daily life: set squares, roofs, and pennants.', age: '3-5' },
      { topic: '认识颜色', zh: '学习认识基本颜色：红色、蓝色、黄色、绿色、橙色、紫色、黑色、白色和粉色。通过分类游戏将相同颜色的物品放在一起，在环境中寻找特定颜色的物品。了解红黄蓝是三原色，混合两种颜色可以产生新颜色（如红+黄=橙）。', en: 'Learn to recognize basic colors: red, blue, yellow, green, orange, purple, black, white, and pink. Sort items of the same color together through classification games, and find items of specific colors in the environment. Understand that red, yellow, and blue are primary colors, and mixing two colors can create new colors (e.g., red + yellow = orange).', age: '3-4' },
      { topic: '简单规律', zh: '学习发现和延续简单规律。从最基础的AB规律开始：红蓝红蓝、大小大小、圆方圆方。逐渐过渡到ABB、AAB、ABC等更复杂的规律。使用积木、珠子、贴纸等材料创造规律，培养逻辑思维和预测能力。', en: 'Learn to identify and continue simple patterns. Start with basic AB patterns: red-blue-red-blue, big-small-big-small, circle-square-circle-square. Gradually progress to more complex patterns like ABB, AAB, and ABC. Use blocks, beads, and stickers to create patterns, developing logical thinking and prediction skills.', age: '4-6' },
      { topic: '空间概念：上下', zh: '理解"上面"和"下面"的空间概念。通过实际操作：把玩具放在桌子上面和下面，观察小鸟在树上面飞、小猫在树下面睡觉。使用语言描述位置："书在盒子上面""球在椅子下面"。能根据指令将物品放在指定位置。', en: 'Understand the spatial concepts of "above" and "below." Through hands-on activities: place toys above and below a table, observe birds flying above a tree and cats sleeping below a tree. Use language to describe positions: "The book is above the box," "The ball is below the chair." Follow instructions to place items in specified positions.', age: '3-5' },
      { topic: '空间概念：前后左右', zh: '理解"前面""后面""左边""右边"的方向概念。以自身为参照：我的前面是门，后面是窗，左边是书架，右边是桌子。注意左右的相对性——面对面的两个人，他们的左右方向是相反的。通过方向游戏和舞蹈动作练习方向感。', en: 'Understand the directional concepts of "in front," "behind," "left," and "right." Use oneself as reference: in front of me is the door, behind me is the window, to my left is the bookshelf, to my right is the desk. Note the relativity of left and right — two people facing each other have opposite left and right directions. Practice direction sense through directional games and dance movements.', age: '4-6' },
      { topic: '简单加法概念', zh: '初步理解加法——"合起来"的概念。通过实物操作：2只小鸟又飞来1只，合起来是3只。用"又来了""又添了""合在一起"等语言描述加法情境。重点理解加法的含义，而非记忆算式。使用手指、积木或画图来表示加法过程。', en: 'Initially understand addition — the concept of "combining together." Through hands-on activities: 2 birds fly in and 1 more comes, making 3 altogether. Use language like "more came," "added," and "altogether" to describe addition situations. Focus on understanding the meaning of addition rather than memorizing equations. Use fingers, blocks, or drawings to represent the addition process.', age: '4-6' },
      { topic: '简单减法概念', zh: '初步理解减法——"拿走"的概念。通过实物操作：5块饼干吃掉2块，还剩3块。用"拿走了""飞走了""吃掉了""还剩"等语言描述减法情境。重点理解减法的含义——从总数中去掉一部分。使用实物操作和画图来表示减法过程。', en: 'Initially understand subtraction — the concept of "taking away." Through hands-on activities: 5 cookies, eat 2, 3 are left. Use language like "took away," "flew away," "ate," and "left" to describe subtraction situations. Focus on understanding the meaning of subtraction — removing a part from the total. Use physical objects and drawings to represent the subtraction process.', age: '4-6' },
      { topic: '认识1和许多', zh: '理解"1"和"许多"的区别。1个苹果和许多苹果，1只小猫和许多小猫。通过分类活动，从"许多"中分出"1"个，再把"1"个放回"许多"中。这是数量概念的基础，帮助孩子理解个体与群体的关系。', en: 'Understand the difference between "one" and "many." One apple and many apples, one cat and many cats. Through sorting activities, separate "one" from "many," then put "one" back into "many." This is the foundation of quantity concepts, helping children understand the relationship between individuals and groups.', age: '3-4' },
      { topic: '按特征分类', zh: '学习按颜色、形状、大小等特征对物品进行分类。例如，把红色积木放一堆，蓝色积木放另一堆；或者把圆形放一起，方形放一起。分类是数学思维的基础，帮助孩子发现事物的共同特征，培养观察力和分析能力。', en: 'Learn to classify items by color, shape, size, and other features. For example, put red blocks in one pile and blue blocks in another; or put circles together and squares together. Classification is the foundation of mathematical thinking, helping children discover common features of objects and developing observation and analytical skills.', age: '3-5' },
      { topic: '认识序数', zh: '理解序数的含义：第1、第2、第3……表示排列的顺序。通过排队游戏：谁排在第1个？谁排在第3个？注意序数和基数的区别——"3个"表示数量，"第3个"表示位置。使用动物赛跑、排队买票等情境来练习序数。', en: 'Understand the meaning of ordinal numbers: first, second, third — indicating position in a sequence. Through lining-up games: Who is first? Who is third? Note the difference between cardinal and ordinal numbers — "3" indicates quantity, "third" indicates position. Practice ordinal numbers through scenarios like animal races and queuing to buy tickets.', age: '4-6' },
      { topic: '认识时间：白天和黑夜', zh: '初步认识时间的概念，区分白天和黑夜。白天太阳出来了，天空亮亮的，我们去幼儿园；夜晚月亮和星星出来了，天空暗暗的，我们睡觉。了解一天有白天和黑夜，建立初步的时间观念。通过图片排序活动，将一天的活动按时间顺序排列。', en: 'Initially understand the concept of time, distinguishing day and night. During the day, the sun is out, the sky is bright, and we go to kindergarten; at night, the moon and stars appear, the sky is dark, and we sleep. Understand that a day has daytime and nighttime, building initial time awareness. Arrange daily activities in chronological order through picture sequencing activities.', age: '3-5' },
      { topic: '测量：长和短', zh: '通过直接比较，认识"长"和"短"的概念。将两支铅笔一端对齐，看哪支更长。使用"比……长""比……短""一样长"来描述比较结果。初步了解可以用一个物品作为标准来测量另一个物品，例如用回形针量铅笔的长度。', en: 'Through direct comparison, understand the concepts of "long" and "short." Align two pencils at one end and see which is longer. Use "longer than," "shorter than," and "the same length" to describe comparison results. Initially understand that one object can be used as a standard to measure another, such as using paper clips to measure the length of a pencil.', age: '4-6' },
      { topic: '认识硬币', zh: '认识常见硬币：1欧分、2欧分、5欧分、10欧分、20欧分、50欧分、1欧元、2欧元。了解不同硬币有不同的价值和大小。通过模拟购物游戏，体验用硬币交换物品的过程，初步建立货币概念。', en: 'Recognize common coins: 1 cent, 2 cents, 5 cents, 10 cents, 20 cents, 50 cents, 1 euro, and 2 euros. Understand that different coins have different values and sizes. Through pretend shopping games, experience the process of exchanging coins for items, initially building the concept of money.', age: '5-6' },
      { topic: '数的分解与组成', zh: '学习将一个数分成两部分，例如5可以分成1和4、2和3、3和2、4和1。这是加减法的基础。使用双色片、分合板等教具，让孩子动手操作，发现数的分解规律。理解一个数可以有多种分法，但分成的两部分合起来总是原来的数。', en: 'Learn to decompose a number into two parts, for example, 5 can be split into 1 and 4, 2 and 3, 3 and 2, 4 and 1. This is the foundation of addition and subtraction. Use two-color counters and partition boards for hands-on exploration, discovering patterns in number decomposition. Understand that a number can be split in multiple ways, but the two parts always combine back to the original number.', age: '5-6' },
      { topic: '认识半和整体', zh: '初步理解"一半"的概念：把一个东西从中间分成相同的两部分，每一部分就是一半。例如，把一个苹果切成两半，每半都是苹果的一半；把一张纸对折，每半张都是整张纸的一半。两个一半合起来就是一个整体。这是分数概念的启蒙。', en: 'Initially understand the concept of "half": dividing something into two equal parts from the middle, each part is one half. For example, cut an apple into two halves, each half is half of the apple; fold a piece of paper in half, each half is half of the whole paper. Two halves make one whole. This is the beginning of fraction concepts.', age: '5-6' }
    ],

    language: [
      { topic: '字母认知A-F', zh: '认识英文字母A到F的大写和小写形式。A像一座尖尖的山，B像两个叠起来的球，C像弯弯的月亮，D像半个圆，E像一把梳子，F像一面旗子。通过字母歌、字母卡片和触摸字母模型来加深记忆。练习用手指在空中写字母。', en: 'Recognize uppercase and lowercase letters A to F. A looks like a pointed mountain, B like two stacked balls, C like a crescent moon, D like half a circle, E like a comb, and F like a flag. Deepen memory through alphabet songs, letter cards, and touching letter models. Practice writing letters in the air with your finger.', age: '3-5' },
      { topic: '字母认知G-L', zh: '认识字母G到L。G像C多了一横，H像两根柱子连着一条横线，I像一根竖线，J像I下面弯了一个钩，K像一根竖线两边伸出斜线，L像一根竖线底部伸出横线。用黏土捏出字母形状，加深对字母形态的记忆。', en: 'Recognize letters G to L. G looks like C with an extra line, H like two pillars connected by a crossbar, I like a vertical line, J like I with a hook at the bottom, K like a vertical line with diagonal lines on both sides, L like a vertical line with a horizontal line at the bottom. Shape letters with clay to deepen memory of letter forms.', age: '3-5' },
      { topic: '字母认知M-R', zh: '认识字母M到R。M像两座山连在一起，N像一座山缺了一半，O像一个圆圆的蛋，P像一面旗子插在杆上，Q像一个O加一条斜线，R像P多了一条斜腿。在沙盘或面粉中用手指写字母，体验书写的触感。', en: 'Recognize letters M to R. M looks like two mountains joined together, N like half a mountain, O like a round egg, P like a flag on a pole, Q like an O with a diagonal line, R like P with an extra diagonal leg. Write letters with your finger in a sand tray or flour to experience the tactile sensation of writing.', age: '3-5' },
      { topic: '字母认知S-Z', zh: '认识字母S到Z。S像一条弯弯的蛇，T像一根竖线顶着一条横线，U像一个杯子，V像一个倒过来的山尖，W像两个V连在一起，X像两条交叉的线，Y像一个分叉的树枝，Z像一条之字形的路。通过字母拼图和字母描红来巩固学习。', en: 'Recognize letters S to Z. S looks like a curvy snake, T like a vertical line topped with a horizontal line, U like a cup, V like an upside-down mountain peak, W like two Vs joined together, X like two crossing lines, Y like a forked branch, Z like a zigzag road. Consolidate learning through letter puzzles and letter tracing.', age: '3-5' },
      { topic: '字母发音初步', zh: '了解每个字母有自己的发音。A发/æ/如apple，B发/b/如ball，C发/k/如cat。通过自然拼读(Phonics)的入门练习，将字母与声音联系起来。听字母发音，找出对应的字母卡片；看字母卡片，发出正确的声音。这是阅读的基础技能。', en: 'Understand that each letter has its own sound. A says /æ/ as in apple, B says /b/ as in ball, C says /k/ as in cat. Through introductory Phonics practice, connect letters with sounds. Listen to letter sounds and find the corresponding letter cards; look at letter cards and produce the correct sounds. This is a foundational skill for reading.', age: '4-6' },
      { topic: '认识自己的名字', zh: '学会认读和书写自己的名字。先认识名字中的每个字母，然后按顺序排列。练习用大写字母写名字的第一个字母，其余用小写。能在自己的作品上写上名字，这是自我认同和书写能力的重要里程碑。每天练习写名字，逐渐提高书写的工整度。', en: 'Learn to read and write your own name. First recognize each letter in your name, then arrange them in order. Practice writing the first letter of your name in uppercase and the rest in lowercase. Being able to write your name on your work is an important milestone in self-identity and writing ability. Practice writing your name daily, gradually improving neatness.', age: '3-5' },
      { topic: '听故事', zh: '培养听故事的习惯和能力。通过聆听绘本故事，学习理解故事的基本元素：人物、地点、发生了什么事。听完后能回答简单的问题：故事里有谁？他们做了什么？你喜欢故事的哪一部分？听故事培养注意力和想象力，也是语言输入的重要途径。', en: 'Develop the habit and ability to listen to stories. Through listening to picture book stories, learn to understand basic story elements: characters, setting, and what happened. After listening, be able to answer simple questions: Who is in the story? What did they do? Which part of the story did you like? Listening to stories develops attention and imagination, and is an important pathway for language input.', age: '3-6' },
      { topic: '说简单句子', zh: '学习用完整的简单句子表达自己。从最基本的主谓结构开始："我要喝水。""猫咪在睡觉。"逐渐扩展到包含更多成分的句子："我想要那个红色的球。"鼓励孩子描述正在做的事情、看到的东西和自己的感受。通过角色扮演和对话练习来提高口语表达能力。', en: 'Learn to express yourself in complete simple sentences. Start with basic subject-verb structure: "I want water." "The cat is sleeping." Gradually expand to sentences with more elements: "I want that red ball." Encourage children to describe what they are doing, what they see, and how they feel. Improve oral expression through role-play and conversation practice.', age: '3-5' },
      { topic: '常见词Sight Words', zh: '认识最常见的高频词：the, a, is, it, in, on, at, and, to, I, you, he, she, we, can, go, no, yes, me, my等。这些词出现频率极高，但很多不符合拼读规则，需要整体记忆。通过闪卡、游戏和反复阅读来掌握这些词，为独立阅读打下基础。', en: 'Recognize the most common high-frequency words: the, a, is, it, in, on, at, and, to, I, you, he, she, we, can, go, no, yes, me, my, etc. These words appear very frequently but many do not follow phonics rules and need to be memorized as whole words. Master these words through flashcards, games, and repeated reading, laying the foundation for independent reading.', age: '4-6' },
      { topic: '押韵词', zh: '认识押韵词——结尾发音相同的词。cat和hat押韵，dog和frog押韵，sun和fun押韵。通过押韵儿歌和游戏，培养对语音的敏感度。能听出两个词是否押韵，能想出与给定词押韵的新词。这是语音意识的重要组成部分，对后续拼读学习至关重要。', en: 'Recognize rhyming words — words with the same ending sound. Cat and hat rhyme, dog and frog rhyme, sun and fun rhyme. Develop phonological awareness through rhyming songs and games. Be able to hear whether two words rhyme and think of new words that rhyme with a given word. This is an important part of phonological awareness, crucial for subsequent phonics learning.', age: '4-6' },
      { topic: '简单单词拼读CVC', zh: '学习拼读CVC（辅音-元音-辅音）单词，如cat, dog, pen, hat, sit, hot, cup等。将每个字母的发音连起来读：c-a-t → cat。这是自然拼读的核心技能。通过拼读练习，孩子能自己读出简单的单词，体验阅读的成就感。逐渐提高拼读速度和准确度。', en: 'Learn to blend CVC (consonant-vowel-consonant) words, such as cat, dog, pen, hat, sit, hot, cup, etc. Sound out each letter and blend them together: c-a-t → cat. This is the core skill of phonics. Through blending practice, children can read simple words on their own, experiencing the satisfaction of reading. Gradually improve blending speed and accuracy.', age: '4-6' },
      { topic: '词汇积累：动物', zh: '学习常见动物的名称：cat猫、dog狗、fish鱼、bird鸟、rabbit兔子、duck鸭子、cow牛、pig猪、sheep羊、horse马、elephant大象、lion狮子等。通过动物图片卡、动物模型和动物叫声来学习。能用句子描述动物："The cat is soft." "The elephant is big."', en: 'Learn names of common animals: cat, dog, fish, bird, rabbit, duck, cow, pig, sheep, horse, elephant, lion, etc. Learn through animal picture cards, animal models, and animal sounds. Be able to describe animals in sentences: "The cat is soft." "The elephant is big."', age: '3-5' },
      { topic: '词汇积累：颜色和形状', zh: '学习用英语说出颜色和形状：red红色、blue蓝色、yellow黄色、green绿色、circle圆形、square正方形、triangle三角形。能组合描述："a red circle""a blue square"。在环境中寻找特定颜色和形状的物品，并用英语描述。', en: 'Learn to say colors and shapes in English: red, blue, yellow, green, circle, square, triangle. Be able to combine descriptions: "a red circle," "a blue square." Find items of specific colors and shapes in the environment and describe them in English.', age: '3-5' },
      { topic: '词汇积累：家庭成员', zh: '学习家庭成员的英语名称：mummy/mom妈妈、daddy/dad爸爸、brother兄弟、sister姐妹、grandma奶奶/外婆、grandpa爷爷/外公、baby宝宝。能用句子介绍家庭："This is my mummy." "I have a brother."画家庭画并用英语标注每位家庭成员。', en: 'Learn English names for family members: mummy/mom, daddy/dad, brother, sister, grandma, grandpa, baby. Be able to introduce family in sentences: "This is my mummy." "I have a brother." Draw a family picture and label each family member in English.', age: '3-5' },
      { topic: '词汇积累：身体部位', zh: '学习身体部位的英语名称：head头、eye眼睛、ear耳朵、nose鼻子、mouth嘴巴、hand手、foot脚、arm手臂、leg腿、tummy肚子。配合动作歌曲如"Head, Shoulders, Knees and Toes"来学习。能听指令指出相应身体部位。', en: 'Learn English names for body parts: head, eye, ear, nose, mouth, hand, foot, arm, leg, tummy. Learn with action songs like "Head, Shoulders, Knees and Toes." Be able to point to the corresponding body part when given instructions.', age: '3-5' },
      { topic: '词汇积累：食物', zh: '学习常见食物的英语名称：apple苹果、banana香蕉、bread面包、milk牛奶、water水、cake蛋糕、egg鸡蛋、rice米饭、juice果汁、cookie饼干。能用句子表达喜好："I like apples." "I want milk, please."通过假装餐厅游戏练习食物词汇。', en: 'Learn English names for common foods: apple, banana, bread, milk, water, cake, egg, rice, juice, cookie. Be able to express preferences in sentences: "I like apples." "I want milk, please." Practice food vocabulary through pretend restaurant games.', age: '3-5' },
      { topic: '词汇积累：数字', zh: '学习用英语说数字1到20：one, two, three, four, five, six, seven, eight, nine, ten, eleven, twelve, thirteen, fourteen, fifteen, sixteen, seventeen, eighteen, nineteen, twenty。通过数数歌和数数游戏来练习。能听英语数字并拿出对应数量的物品。', en: 'Learn to say numbers 1 to 20 in English: one, two, three, four, five, six, seven, eight, nine, ten, eleven, twelve, thirteen, fourteen, fifteen, sixteen, seventeen, eighteen, nineteen, twenty. Practice through counting songs and counting games. Be able to hear an English number and produce the corresponding quantity of items.', age: '3-6' },
      { topic: '简单问答', zh: '学习基本的英语问答：What is your name? — My name is... How old are you? — I am... years old. How are you? — I am fine, thank you. What is this? — It is a... 通过与同伴和老师反复练习，培养用英语进行简单交流的信心和能力。', en: 'Learn basic English Q&A: What is your name? — My name is... How old are you? — I am... years old. How are you? — I am fine, thank you. What is this? — It is a... Through repeated practice with peers and teachers, develop confidence and ability in simple English communication.', age: '4-6' },
      { topic: '简单指令理解', zh: '理解并执行常见的课堂英语指令：Sit down. Stand up. Listen. Look. Come here. Stop. Be quiet. Raise your hand. Open your book. Close your book. Line up. 通过TPR（全身反应法）活动，将语言与动作结合，帮助理解和记忆。', en: 'Understand and follow common classroom English instructions: Sit down. Stand up. Listen. Look. Come here. Stop. Be quiet. Raise your hand. Open your book. Close your book. Line up. Through TPR (Total Physical Response) activities, combine language with actions to aid understanding and memory.', age: '3-5' },
      { topic: '儿歌和韵律', zh: '学习经典英语儿歌：Twinkle Twinkle Little Star, Baa Baa Black Sheep, Humpty Dumpty, Jack and Jill, London Bridge等。通过唱歌学习语音节奏、押韵和词汇。儿歌中的重复结构有助于记忆，旋律使学习更加有趣。配合手势和动作表演儿歌。', en: 'Learn classic English nursery rhymes: Twinkle Twinkle Little Star, Baa Baa Black Sheep, Humpty Dumpty, Jack and Jill, London Bridge, etc. Learn speech rhythm, rhyming, and vocabulary through singing. The repetitive structure of nursery rhymes aids memory, and melodies make learning more fun. Perform nursery rhymes with gestures and actions.', age: '3-5' },
      { topic: '绘本阅读入门', zh: '开始接触英文绘本阅读。从最简单的绘本开始，每页只有一两个单词或简单句子。学习阅读的基本概念：文字从左到右、从上到下阅读；翻页的方向；图片帮助理解故事。在老师或家长的陪伴下，逐页阅读，讨论图片和故事内容。', en: 'Begin reading English picture books. Start with the simplest books, with only one or two words or simple sentences per page. Learn basic concepts of reading: text is read from left to right and top to bottom; the direction of turning pages; pictures help understand the story. Read page by page with a teacher or parent, discussing pictures and story content.', age: '4-6' }
    ],

    science: [
      { topic: '认识常见动物', zh: '认识身边的常见动物：猫、狗、鸟、鱼、兔子、蜗牛、蝴蝶、蚂蚁等。了解它们的基本特征——有几条腿、有没有翅膀、身体表面是毛还是鳞片。观察动物的生活方式：它们住在哪里、吃什么、怎么移动。培养对动物的好奇心和爱护意识。', en: 'Recognize common animals around us: cats, dogs, birds, fish, rabbits, snails, butterflies, ants, etc. Understand their basic features — how many legs they have, whether they have wings, whether their body surface is fur or scales. Observe how animals live: where they live, what they eat, how they move. Develop curiosity about and care for animals.', age: '3-5' },
      { topic: '认识常见植物', zh: '认识常见的植物：大树、小草、花、蔬菜等。了解植物的基本结构——根、茎、叶、花、果实。观察植物的生长：种子发芽、长出叶子、开花结果。亲手种下一颗种子（如豆子），每天观察和记录它的变化，体验植物生长的奇妙过程。', en: 'Recognize common plants: trees, grass, flowers, vegetables, etc. Understand the basic structure of plants — roots, stems, leaves, flowers, and fruits. Observe plant growth: seeds sprouting, leaves growing, flowering and fruiting. Plant a seed (such as a bean) yourself, observe and record its changes daily, experiencing the wonderful process of plant growth.', age: '3-5' },
      { topic: '天气和季节', zh: '认识四种天气：晴天、阴天、雨天、雪天。了解四季：春天暖和、花朵开放；夏天炎热、阳光强烈；秋天凉爽、树叶变色；冬天寒冷、可能下雪。每天观察并记录天气，制作简单的天气日历。讨论不同天气和季节穿什么衣服、做什么活动。', en: 'Recognize four types of weather: sunny, cloudy, rainy, and snowy. Understand the four seasons: spring is warm with flowers blooming; summer is hot with strong sunshine; autumn is cool with leaves changing color; winter is cold with possible snow. Observe and record the weather daily, making a simple weather calendar. Discuss what clothes to wear and what activities to do in different weather and seasons.', age: '3-6' },
      { topic: '身体部位', zh: '认识人体的主要外部部位：头、眼睛、耳朵、鼻子、嘴巴、脖子、肩膀、手臂、手、手指、胸、肚子、腿、脚、脚趾。了解每个部位的基本功能：眼睛用来看、耳朵用来听、鼻子用来闻、嘴巴用来吃和说。通过歌曲和游戏来学习和记忆身体部位。', en: 'Recognize the main external body parts: head, eyes, ears, nose, mouth, neck, shoulders, arms, hands, fingers, chest, tummy, legs, feet, toes. Understand the basic function of each part: eyes for seeing, ears for hearing, nose for smelling, mouth for eating and speaking. Learn and remember body parts through songs and games.', age: '3-5' },
      { topic: '五种感官', zh: '认识五种感官及其功能：眼睛——视觉（看颜色、形状、大小）；耳朵——听觉（听声音的高低、强弱）；鼻子——嗅觉（闻香味、臭味）；舌头——味觉（尝甜、酸、苦、咸）；皮肤——触觉（感受冷热、软硬、粗糙光滑）。通过感官探索活动，体验每种感官的独特作用。', en: 'Recognize the five senses and their functions: eyes — sight; ears — hearing; nose — smell; tongue — taste; skin — touch. Experience the unique role of each sense through sensory exploration activities. Understand that our senses help us understand and interact with the world around us.', age: '3-6' },
      { topic: '光和暗', zh: '探索光和暗的现象。认识自然光源（太阳）和人造光源（灯、蜡烛、手电筒）。了解没有光就会变暗，影子是光被物体挡住后形成的。用手电筒和玩具做影子实验，观察改变光源距离和角度时影子的变化。了解我们需要光才能看见东西。', en: 'Explore phenomena of light and dark. Recognize natural light sources (the sun) and artificial light sources (lamps, candles, flashlights). Understand that without light it becomes dark, and shadows are formed when light is blocked by objects. Do shadow experiments with flashlights and toys, observing how shadows change when the distance and angle of the light source change.', age: '4-6' },
      { topic: '水的探索', zh: '探索水的特性：水没有颜色、没有味道、没有气味，可以流动。水可以变成冰（冷冻时），冰可以变回水（加热时），水还可以变成水蒸气（加热时）。观察水在不同容器中的形状——水没有固定形状，随容器而变。了解水对生命的重要性。', en: 'Explore the properties of water: water has no color, no taste, no smell, and can flow. Water can become ice (when frozen), ice can become water again (when heated), and water can become steam (when heated). Observe the shape of water in different containers — water has no fixed shape and takes the shape of its container.', age: '4-6' },
      { topic: '磁铁的奥秘', zh: '探索磁铁的特性：磁铁能吸引铁制品，但不能吸引木头、塑料、纸张等。磁铁有两个极——北极和南极，同极相斥、异极相吸。用磁铁测试各种物品，发现哪些能被吸引、哪些不能。玩磁铁钓鱼游戏，感受磁力的有趣。', en: 'Explore the properties of magnets: magnets can attract iron objects but not wood, plastic, or paper. Magnets have two poles — north and south; like poles repel, opposite poles attract. Test various objects with magnets to discover which can be attracted and which cannot. Play magnetic fishing games to experience the fun of magnetic force.', age: '4-6' },
      { topic: '浮和沉', zh: '探索物品在水中的浮沉现象。把各种物品放入水中观察：木块、塑料球浮在水面上，石头、金属勺沉到水底。发现一般轻的、有空气的物品容易浮，重的、实心的物品容易沉。但不是绝对的——大船虽然很重却能浮，因为船里面有大量空气。', en: 'Explore floating and sinking phenomena. Put various objects in water and observe: wooden blocks and plastic balls float, stones and metal spoons sink. Discover that generally light objects with air inside tend to float, while heavy, solid objects tend to sink. But this is not absolute — large ships are very heavy yet float because they contain a lot of air.', age: '4-6' },
      { topic: '动物的家', zh: '了解不同动物生活在不同的地方——它们的家各不相同。鸟住在树上的巢里，兔子住在地下的洞里，鱼住在水里，蜗牛住在壳里，蜜蜂住在蜂巢里。讨论为什么不同的动物需要不同的家：保护自己、养育后代、躲避天气。', en: 'Understand that different animals live in different places — their homes are all different. Birds live in nests in trees, rabbits live in underground burrows, fish live in water, snails live in shells, bees live in hives. Discuss why different animals need different homes: to protect themselves, raise young, and shelter from weather.', age: '3-5' },
      { topic: '种子和生长', zh: '了解植物从种子开始生长。观察不同种子的形状和大小：豆子种子圆圆的、向日葵种子尖尖的。亲手种植种子，观察发芽的过程：先长出根，再长出茎和叶。了解植物生长需要阳光、水和土壤。制作种子生长观察日记，记录每天的变化。', en: 'Understand that plants grow from seeds. Observe different seed shapes and sizes. Plant seeds yourself and observe the sprouting process: roots grow first, then stems and leaves. Understand that plants need sunlight, water, and soil to grow. Create a seed growth observation diary, recording changes each day.', age: '4-6' },
      { topic: '白天和黑夜', zh: '了解白天和黑夜形成的原因：地球在不停地旋转，面向太阳的一面是白天，背对太阳的一面是黑夜。白天太阳在天空中，给我们光和热；夜晚太阳在地平线以下，月亮和星星出现在天空中。白天我们活动，夜晚我们休息。', en: 'Understand why day and night occur: the Earth is constantly rotating, the side facing the sun has daytime, and the side facing away has nighttime. During the day, the sun gives us light and heat; at night, the moon and stars appear in the sky. We are active during the day and rest at night.', age: '4-6' },
      { topic: '食物从哪里来', zh: '了解食物的来源：牛奶来自奶牛，鸡蛋来自母鸡，面包是用小麦做的，苹果长在苹果树上，胡萝卜长在泥土里。有些食物可以直接从农场获得，有些需要加工才能做成。了解农民和食品工人为我们生产食物的辛苦，培养珍惜食物的意识。', en: 'Understand where food comes from: milk comes from cows, eggs come from hens, bread is made from wheat, apples grow on apple trees, carrots grow in the soil. Some foods can be obtained directly from farms, while others need processing. Understand the hard work of farmers and food workers who produce food for us.', age: '3-6' },
      { topic: '推和拉', zh: '认识推和拉是两种基本的力。推是向外用力使物体移动，拉是向自己方向用力使物体移动。推购物车、推门、推积木；拉绳子、拉抽屉、拉玩具车。发现推和拉可以使物体移动、停止或改变方向。有些东西容易推拉（轻的），有些不容易（重的）。', en: 'Recognize that pushing and pulling are two basic forces. Pushing is applying outward force to move an object, pulling is applying force toward yourself to move an object. Discover that pushing and pulling can make objects move, stop, or change direction. Some things are easy to push and pull (light ones), some are not (heavy ones).', age: '4-6' },
      { topic: '声音的探索', zh: '探索声音的世界：敲击、弹拨、吹气、摇晃都能产生声音。声音有大小（强弱）和高低之分。用力敲鼓声音大，轻轻敲声音小；敲大钟声音低，敲小铃铛声音高。用手捂住耳朵，发现声音变弱了，说明耳朵帮助我们听到声音。', en: 'Explore the world of sound: hitting, plucking, blowing, and shaking can all produce sounds. Sounds can be loud or soft and high or low. Hitting a drum hard makes a loud sound, hitting gently makes a soft sound; striking a large bell makes a low sound, a small bell makes a high sound.', age: '4-6' },
      { topic: '健康饮食', zh: '了解健康饮食的基本概念：每天需要吃不同种类的食物来保持健康。水果和蔬菜给我们维生素，牛奶和奶酪给我们钙质，肉和豆类给我们蛋白质，米饭和面包给我们能量。太多甜食和零食对身体不好。尝试吃各种颜色的水果和蔬菜，让餐盘变得丰富多彩。', en: 'Understand the basic concept of healthy eating: we need to eat different types of food every day to stay healthy. Fruits and vegetables give us vitamins, milk and cheese give us calcium, meat and beans give us protein, rice and bread give us energy. Too many sweets and snacks are not good for the body.', age: '3-6' },
      { topic: '保持清洁', zh: '学习保持个人卫生的重要性：饭前便后要洗手，每天刷牙两次，定期洗澡，勤换衣服。了解细菌很小很小，肉眼看不见，但会让人生病。洗手可以洗掉手上的细菌，保护我们不被感染。学习正确的洗手方法：用肥皂搓出泡沫，每个手指缝都要洗到。', en: 'Learn the importance of personal hygiene: wash hands before eating and after using the toilet, brush teeth twice a day, bathe regularly, and change clothes often. Understand that germs are very tiny and invisible to the eye but can make us sick. Washing hands removes germs and protects us from infection.', age: '3-6' },
      { topic: '材料探索', zh: '认识不同的材料：木头、金属、塑料、布、纸、玻璃、橡胶。每种材料有不同的特性——木头硬而暖、金属冷而亮、塑料轻而软、布柔软、纸容易撕、玻璃透明但易碎、橡胶有弹性。在环境中寻找不同材料制成的物品，讨论为什么某种物品要用某种材料制作。', en: 'Recognize different materials: wood, metal, plastic, fabric, paper, glass, rubber. Each material has different properties — wood is hard and warm, metal is cold and shiny, plastic is light and soft, fabric is soft, paper tears easily, glass is transparent but breakable, rubber is elastic. Find objects made of different materials in the environment.', age: '4-6' },
      { topic: '四季的变化', zh: '深入了解四季的变化对自然和人类生活的影响。春天：白天变长、天气变暖、花朵开放、小动物出生。夏天：白天最长、天气最热、水果成熟。秋天：白天变短、天气变凉、树叶变色掉落、收获果实。冬天：白天最短、天气最冷、有些动物冬眠。', en: 'Deepen understanding of how seasonal changes affect nature and human life. Spring: days get longer, weather warms, flowers bloom, baby animals are born. Summer: longest days, hottest weather, fruits ripen. Autumn: days get shorter, weather cools, leaves change color and fall. Winter: shortest days, coldest weather, some animals hibernate.', age: '3-6' },
      { topic: '小生命的变化', zh: '观察生命的变化过程。蝴蝶的生命周期：卵→毛毛虫→蛹→蝴蝶。青蛙的生命周期：卵→蝌蚪→长腿的蝌蚪→青蛙。了解动物宝宝和成年动物长得不一样，它们会经历变化和成长。人类也是从小宝宝慢慢长大成人的。', en: 'Observe the process of life changes. Butterfly life cycle: egg → caterpillar → chrysalis → butterfly. Frog life cycle: egg → tadpole → tadpole with legs → frog. Understand that baby animals look different from adult animals, and they go through changes and growth.', age: '4-6' }
    ],

    art: [
      { topic: '涂鸦和自由绘画', zh: '鼓励孩子自由涂鸦，这是艺术表达的第一步。提供蜡笔、彩色铅笔和马克笔，让孩子在纸上自由画线条和形状。不要纠正或指导画什么，让孩子享受绘画的快乐。涂鸦发展手眼协调能力，也是情感表达的方式。', en: 'Encourage children to scribble freely, which is the first step in artistic expression. Provide crayons, colored pencils, and markers for children to freely draw lines and shapes on paper. Let children enjoy the pleasure of drawing. Scribbling develops hand-eye coordination and is a form of emotional expression.', age: '3-4' },
      { topic: '手指画', zh: '用手指蘸取颜料在纸上创作。手指画是一种直接用身体感受色彩的方式，不需要画笔的技巧。可以用手指点、拖、旋转来创造不同的效果。体验不同颜色混合后的变化，感受色彩的魅力。穿上围裙，铺好报纸，尽情享受手指画的乐趣。', en: 'Create art by dipping fingers in paint on paper. Finger painting is a way to experience color directly through the body, requiring no brush skills. Use fingers to dot, drag, and swirl to create different effects. Experience how different colors change when mixed, feeling the charm of color.', age: '3-5' },
      { topic: '认识颜色', zh: '学习认识和使用基本颜色：红、蓝、黄、绿、橙、紫、黑、白、棕、粉。了解红黄蓝是三原色，它们不能由其他颜色混合而成。但混合三原色可以产生新颜色：红+黄=橙，黄+蓝=绿，红+蓝=紫。通过调色实验，发现色彩混合的奇妙。', en: 'Learn to recognize and use basic colors: red, blue, yellow, green, orange, purple, black, white, brown, and pink. Understand that red, yellow, and blue are primary colors. Mixing primary colors can create new colors: red + yellow = orange, yellow + blue = green, red + blue = purple.', age: '3-5' },
      { topic: '撕纸和拼贴', zh: '学习撕纸和拼贴技术。用手撕出不同形状的纸片，然后粘贴在底纸上组成画面。撕纸的边缘有自然的毛边效果，与剪刀剪出的整齐边缘不同。可以用彩纸、杂志图片、包装纸等材料。拼贴培养创造力和构图能力，也是环保艺术的体现。', en: 'Learn tearing and collage techniques. Tear paper into different shapes with your hands, then paste them onto base paper to create a picture. Use colored paper, magazine pictures, wrapping paper, and other materials. Collage develops creativity and composition skills, and is a form of eco-friendly art.', age: '3-5' },
      { topic: '橡皮泥造型', zh: '用橡皮泥(Play-Doh)或黏土创作立体作品。学习基本的泥塑技法：揉圆球、搓长条、压扁、捏尖、卷曲。用这些基本形状组合成各种物品：小动物、食物、花朵等。橡皮泥锻炼手指力量和精细动作，培养空间想象力和创造力。', en: 'Create three-dimensional works with Play-Doh or clay. Learn basic clay techniques: rolling balls, making long snakes, flattening, pinching points, and curling. Combine these basic shapes into various objects: animals, food, flowers, etc. Play-Doh exercises finger strength and fine motor skills.', age: '3-5' },
      { topic: '印章画', zh: '使用各种印章工具创作图案。可以用蔬菜印章（芹菜根印出玫瑰花纹、胡萝卜印出圆形）、海绵印章、手指印章等。蘸取颜料后按压在纸上，留下有趣的形状和图案。尝试用不同大小的印章、不同颜色组合，创造独特的印章画作品。', en: 'Create patterns using various stamping tools. Use vegetable stamps (celery root prints rose patterns, carrot prints circles), sponge stamps, finger stamps, etc. Dip in paint and press onto paper, leaving interesting shapes and patterns.', age: '3-5' },
      { topic: '画人物', zh: '学习画简单的人物。从火柴人开始：一个圆圈做头，直线做身体和四肢。逐渐添加细节：眼睛、嘴巴、头发、衣服。注意人物的基本比例——头不要太大或太小。画自己和家人，给人物加上表情，表达不同的情绪：开心、难过、惊讶。', en: 'Learn to draw simple people. Start with stick figures: a circle for the head, straight lines for the body and limbs. Gradually add details: eyes, mouth, hair, clothes. Draw yourself and family members, adding expressions to show different emotions.', age: '4-6' },
      { topic: '画房子和风景', zh: '学习画简单的房子和风景。房子有三角形的屋顶、方形的墙壁、长方形的门和方形的窗户。添加烟囱、花园、栅栏等细节。在房子周围画上太阳、云朵、树木、花朵，组成一幅完整的风景画。尝试画不同季节的风景。', en: 'Learn to draw simple houses and landscapes. A house has a triangular roof, square walls, a rectangular door, and square windows. Add details like a chimney, garden, and fence. Draw the sun, clouds, trees, and flowers around the house to create a complete landscape.', age: '4-6' },
      { topic: '折纸入门', zh: '学习简单的折纸。从最基础的对折开始：将纸对折成三角形或长方形。然后学习折纸飞机、纸船、纸帽子等简单作品。折纸需要精确的手指动作和步骤记忆，锻炼手眼协调和空间思维。跟着老师一步一步折，遇到困难时耐心尝试。', en: 'Learn simple origami. Start with the most basic folds: fold paper in half to make a triangle or rectangle. Then learn to fold paper airplanes, paper boats, paper hats, and other simple projects. Origami requires precise finger movements and step memorization.', age: '4-6' },
      { topic: '自然材料艺术', zh: '使用自然材料创作艺术作品。收集秋天的落叶做树叶画和树叶印画；用小石头画石头画；用树枝和松果做立体造型；用花瓣做花瓣拼贴。自然材料有独特的颜色、纹理和形状，能激发创造力。在户外散步时收集材料，在教室里创作。', en: 'Create artwork using natural materials. Collect autumn leaves for leaf paintings and leaf prints; paint on small stones for rock art; use twigs and pinecones for 3D sculptures; use flower petals for petal collages. Natural materials have unique colors, textures, and shapes that inspire creativity.', age: '4-6' },
      { topic: '线条画', zh: '探索各种线条的表现力：直线、曲线、波浪线、螺旋线、锯齿线、虚线。用不同的线条画出不同的感觉——直线感觉整齐、曲线感觉柔和、锯齿线感觉尖锐。尝试只用线条画一幅画，发现线条本身就能表达丰富的内容和情感。', en: 'Explore the expressive power of various lines: straight lines, curves, wavy lines, spirals, zigzags, and dashed lines. Draw different feelings with different lines — straight lines feel orderly, curves feel gentle, zigzags feel sharp. Try drawing a picture using only lines.', age: '4-6' },
      { topic: '对称画', zh: '学习对称的概念和创作方法。将纸对折，在一半上涂上颜料，趁颜料未干时将纸对折压印，打开后两边就是对称的图案。这种方法叫做"蝴蝶画"，因为打开后像蝴蝶的翅膀。对称画效果神奇，每次打开都有惊喜。', en: 'Learn the concept and creation method of symmetry. Fold paper in half, paint on one side, and while the paint is wet, fold and press to print, creating a symmetrical pattern when opened. This method is called "butterfly painting" because the result looks like butterfly wings.', age: '4-6' },
      { topic: '废旧材料手工', zh: '使用废旧材料创作手工作品，培养环保意识和创造力。用纸盒做房子或汽车，用卫生纸筒做望远镜或笔筒，用瓶盖做毛毛虫，用塑料瓶做花瓶。收集各种废旧材料，思考它们可以变成什么。剪裁、粘贴、涂色，将废旧物品变成有趣的艺术品。', en: 'Create handmade crafts using recycled materials, developing environmental awareness and creativity. Make houses or cars from boxes, telescopes or pen holders from toilet paper tubes, caterpillars from bottle caps, and vases from plastic bottles.', age: '4-6' },
      { topic: '画动物', zh: '学习画简单的动物。用基本形状组合画动物：圆形做头，椭圆形做身体，三角形做耳朵。画小猫：圆头、三角耳朵、长尾巴；画小鱼：椭圆身体、三角尾巴；画小鸟：圆头、椭圆身体、三角嘴巴。给动物涂上颜色，添加眼睛和表情。', en: 'Learn to draw simple animals. Combine basic shapes to draw animals: circles for heads, ovals for bodies, triangles for ears. Draw a cat: round head, triangular ears, long tail; draw a fish: oval body, triangular tail; draw a bird: round head, oval body, triangular beak.', age: '4-6' },
      { topic: '水彩画入门', zh: '初步接触水彩画。学习水彩画的基本用法：先用笔蘸水，再蘸颜料，然后在纸上画。水彩的特点是颜色透明、可以叠加。尝试湿画法——先在纸上刷水，再点入颜料，看颜色在水中扩散的美丽效果。画简单的水彩画：彩虹、花朵、天空。', en: 'Introduction to watercolor painting. Learn basic watercolor techniques: dip the brush in water first, then in paint, then paint on paper. Watercolor features transparent colors that can be layered. Try wet-on-wet technique — brush water on paper first, then drop in paint, watching the beautiful effect of colors spreading in water.', age: '5-6' },
      { topic: '版画入门', zh: '尝试简单的版画制作。在泡沫板上用铅笔刻出图案，涂上颜料，然后将纸压在上面印出图案。版画的特别之处是可以重复印制多张相同的作品。设计简单的图案：星星、花朵、小动物。每次印制都充满期待，揭开纸张看到成品的那一刻特别有成就感。', en: 'Try simple printmaking. Carve a design on a foam sheet with a pencil, apply paint, then press paper on top to print the design. The special feature of printmaking is that multiple identical copies can be made. Design simple patterns: stars, flowers, and small animals.', age: '5-6' },
      { topic: '观察画', zh: '学习观察并画出看到的东西。选择一个简单的物品（如一个苹果、一朵花、一个杯子），仔细观察它的形状、颜色和细节，然后尽量真实地画下来。观察画训练眼睛的观察力和手的表现力。不需要画得完美，重要的是认真观察和尝试。', en: 'Learn to observe and draw what you see. Choose a simple object (such as an apple, a flower, or a cup), carefully observe its shape, color, and details, then try to draw it as realistically as possible. Observational drawing trains the eyes observation skills and the hands expressive ability.', age: '5-6' },
      { topic: '情感画', zh: '用绘画表达情感和心情。开心的时候画什么颜色？难过的时候画什么？生气的时候呢？尝试用颜色和线条表达不同的情绪：明亮的暖色表达快乐，暗淡的冷色表达忧伤，强烈的红色和尖锐的线条表达愤怒。画画是表达内心感受的一种方式。', en: 'Express emotions and feelings through painting. Try expressing different emotions with colors and lines: bright warm colors for happiness, dark cool colors for sadness, strong reds and sharp lines for anger. Painting is a way to express inner feelings.', age: '4-6' },
      { topic: '合作画', zh: '和同伴一起创作大型合作画。在大张纸上，几个孩子一起画一个主题：海底世界、恐龙乐园、城市风景等。学习分工合作、互相尊重彼此的创作空间、协商画面内容。合作画培养团队合作精神和社交能力，也是展示集体创造力的方式。', en: 'Create large collaborative paintings with peers. On a large sheet of paper, several children paint together on a theme: underwater world, dinosaur park, city landscape, etc. Learn to divide work, respect each others creative space, and negotiate picture content.', age: '4-6' },
      { topic: '面具制作', zh: '制作有趣的面具。用纸盘做基础，剪出眼睛的位置，用颜料、彩纸、毛线、羽毛等装饰。制作动物面具：猫耳朵、兔子长耳朵、狮子鬃毛。也可以制作情绪面具：笑脸面具、惊讶面具。戴上面具进行角色扮演，增加戏剧性和趣味性。', en: 'Make fun masks. Use paper plates as a base, cut out eye holes, and decorate with paint, colored paper, yarn, feathers, etc. Make animal masks: cat ears, long rabbit ears, lion mane. Also make emotion masks: smiley face mask, surprised mask. Wear masks for role-play.', age: '4-6' },
      { topic: '艺术欣赏', zh: '学习欣赏名画和不同风格的艺术作品。看梵高的《星空》，感受旋转的线条和明亮的色彩；看莫奈的《睡莲》，感受柔和的光影变化；看蒙德里安的格子画，感受简洁的线条和色块。讨论你喜欢哪幅画、为什么喜欢。艺术没有对错，每个人都可以有自己的感受。', en: 'Learn to appreciate famous paintings and different styles of art. Look at Van Goghs "Starry Night," feeling the swirling lines and bright colors; look at Monets "Water Lilies," feeling the soft changes of light and shadow; look at Mondrians grid paintings, feeling the simple lines and color blocks. There is no right or wrong in art.', age: '4-6' }
    ],

    music: [
      { topic: '唱歌入门', zh: '学习用自然的声音唱歌。不需要大声喊叫，用舒适的音量，清楚地唱出歌词。从简单的儿歌开始：《小星星》《两只老虎》《伦敦桥》等。跟着老师的节奏和旋律一起唱，逐渐学会独立唱完一首歌。唱歌时注意听自己的声音和同伴的声音，保持和谐。', en: 'Learn to sing with a natural voice. No need to shout; use a comfortable volume and sing lyrics clearly. Start with simple nursery rhymes. Sing along with the teachers rhythm and melody, gradually learning to sing a complete song independently. While singing, listen to your own voice and your peers voices to maintain harmony.', age: '3-5' },
      { topic: '节奏拍手', zh: '学习感受和表现节奏。跟着音乐拍手，感受稳定的节拍。从简单的四拍子开始：拍-拍-拍-拍。逐渐尝试不同的节奏模式：拍-拍-拍拍-拍（长短交替）。用拍手、跺脚、拍腿等身体打击乐来表现节奏。节奏是音乐的基础，培养节奏感对音乐学习至关重要。', en: 'Learn to feel and express rhythm. Clap along with music, feeling the steady beat. Start with simple 4-beat patterns. Express rhythm through body percussion like clapping, stomping, and patting. Rhythm is the foundation of music; developing rhythm sense is crucial for music learning.', age: '3-5' },
      { topic: '认识打击乐器', zh: '认识常见的打击乐器：手鼓、三角铁、铃鼓、木鱼、沙锤、响板。每种乐器有不同的声音——手鼓声音低沉，三角铁声音清脆，沙锤声音沙沙响。学习正确的演奏方法：怎样握持、怎样敲击、怎样停止。用打击乐器为歌曲伴奏，体验合奏的乐趣。', en: 'Recognize common percussion instruments: hand drum, triangle, tambourine, wood block, maracas, and castanets. Each instrument has a different sound. Learn proper playing techniques: how to hold, how to strike, how to stop. Accompany songs with percussion instruments, experiencing the joy of ensemble playing.', age: '3-5' },
      { topic: '快和慢', zh: '通过音乐感受快和慢的概念。听快速的音乐——感觉兴奋、想跑想跳；听慢速的音乐——感觉平静、想慢慢走。跟着不同速度的音乐做动作：快音乐时快走或小跑，慢音乐时慢走或摇摆。用打击乐器尝试演奏快和慢的节奏，体验速度对音乐表现力的影响。', en: 'Experience the concepts of fast and slow through music. Listen to fast music — feeling excited; listen to slow music — feeling calm. Move to music at different speeds. Try playing fast and slow rhythms with percussion instruments, experiencing how speed affects musical expression.', age: '3-5' },
      { topic: '强和弱', zh: '通过音乐感受强和弱的概念。大声敲鼓是强，轻轻敲是弱；用力弹琴是强，轻轻弹是弱。听音乐中的强弱变化：摇篮曲很轻柔，进行曲很有力。用身体动作表现强弱：强的时候做大动作，弱的时候做小动作。强弱变化让音乐更有表现力和感染力。', en: 'Experience the concepts of loud and soft through music. Listen to dynamic changes in music: lullabies are very gentle, marches are very powerful. Express loud and soft with body movements: big movements when loud, small movements when soft. Dynamic changes make music more expressive and moving.', age: '3-5' },
      { topic: '高和低', zh: '通过音乐感受音高的概念。小鸟唱歌声音高，大熊说话声音低。用声音模仿不同动物：吱吱的小老鼠（高音）、嗡嗡的大黄牛（低音）。在键盘或木琴上从低到高弹奏，听音高逐渐上升；从高到低弹奏，听音高逐渐下降。音高是旋律的基础。', en: 'Experience the concept of pitch through music. Birds sing with high voices, bears speak with low voices. Imitate different animals with your voice. Play from low to high on a keyboard or xylophone, hearing pitch gradually rise. Pitch is the foundation of melody.', age: '4-6' },
      { topic: '音乐律动', zh: '跟着音乐做律动。听不同风格的音乐，用身体自由地表现：轻柔的音乐像微风一样慢慢摇摆，欢快的音乐像小兔子一样蹦蹦跳跳，雄壮的音乐像大象一样有力地走。音乐律动培养身体协调性和音乐感受力，让身体成为表达音乐的工具。', en: 'Move to music. Listen to different styles of music and express freely with your body. Musical movement develops body coordination and musical sensitivity, making the body a tool for expressing music.', age: '3-5' },
      { topic: '音乐故事', zh: '通过音乐讲述故事。听带有故事性的音乐作品，如《彼得与狼》——每种乐器代表一个角色：小鸟是长笛、鸭子是双簧管、狼是圆号。听音乐猜猜是什么角色出场了。也尝试自己用乐器或声音为故事配乐。', en: 'Tell stories through music. Listen to narrative musical works like "Peter and the Wolf" — each instrument represents a character. Listen to the music and guess which character appears. Also try creating sound effects for stories yourself.', age: '4-6' },
      { topic: '圆圈歌和游戏歌', zh: '学习圆圈歌和游戏歌，在游戏中唱歌。围成圆圈边唱边做动作：《伦敦桥》手拉手穿过桥洞，《Ring-a-Ring o Roses》转圈然后倒下。这些歌曲结合了音乐、运动和社交，是幼儿最自然的音乐体验方式。', en: 'Learn circle songs and game songs, singing while playing. Form a circle and sing with actions. These songs combine music, movement, and social interaction, providing the most natural musical experience for young children.', age: '3-5' },
      { topic: '自制乐器', zh: '制作简单的自制乐器。用空瓶子和豆子做沙锤——摇晃时沙沙响；用橡皮筋和纸盒做吉他——拨动时嗡嗡响；用锅和木勺做鼓——敲击时咚咚响。自制乐器让孩子了解发声的原理，体验创造的乐趣。用自制乐器组成乐队，一起演奏简单的节奏。', en: 'Make simple homemade instruments. Use empty bottles and beans to make maracas; use rubber bands and boxes to make guitars; use pots and wooden spoons to make drums. Homemade instruments help children understand how sounds are produced and experience the joy of creation.', age: '4-6' },
      { topic: '摇篮曲和安静音乐', zh: '学习摇篮曲和安静音乐。摇篮曲节奏缓慢、旋律柔和，像妈妈轻轻摇晃宝宝入睡。听经典摇篮曲如《勃拉姆斯摇篮曲》《莫扎特摇篮曲》。在安静时间播放轻柔的音乐，帮助孩子放松和休息。了解音乐可以影响人的情绪。', en: 'Learn lullabies and quiet music. Lullabies have slow rhythms and gentle melodies, like a mother gently rocking her baby to sleep. Listen to classic lullabies. Play soft music during quiet time to help children relax and rest. Understand that music can affect emotions.', age: '3-5' },
      { topic: '进行曲和活力音乐', zh: '感受进行曲和活力音乐的力量。进行曲节奏整齐、有力，让人想踏步前进。听经典进行曲如《星条旗永不落》《土耳其进行曲》。跟着进行曲踏步、挥旗、做体操。活力音乐让人充满能量，想跳舞想运动。', en: 'Feel the power of marches and energetic music. Marches have neat, strong rhythms that make you want to march forward. Listen to classic marches. March, wave flags, and do exercises to march music. Energetic music fills you with energy.', age: '4-6' },
      { topic: '模仿和回声', zh: '玩音乐回声游戏。老师唱一个短句，学生像回声一样重复。逐渐增加难度：更长的乐句、更复杂的节奏。回声游戏训练听觉记忆和音准，也是学习演唱的重要方法。也可以用打击乐器玩回声：老师敲一个节奏，学生重复。', en: 'Play musical echo games. The teacher sings a short phrase, and students repeat it like an echo. Gradually increase difficulty. Echo games train auditory memory and pitch accuracy, and are an important method for learning to sing.', age: '3-6' },
      { topic: '音乐中的动物', zh: '通过音乐认识动物。听圣桑的《动物狂欢节》——大象的音乐沉重缓慢，天鹅的音乐优雅流畅，公鸡的音乐响亮清脆。每种动物都有独特的音乐形象。尝试用声音和动作模仿不同的动物，感受音乐如何描绘动物的特征。', en: 'Learn about animals through music. Listen to Saint-Saens "Carnival of the Animals" — the elephants music is heavy and slow, the swans music is elegant and flowing, the roosters music is loud and crisp. Try imitating different animals with sounds and movements.', age: '4-6' },
      { topic: '简单音乐符号', zh: '认识最简单的音乐符号。音符：一个圆圈（全音符）唱4拍，加一根竖线（二分音符）唱2拍，实心加竖线（四分音符）唱1拍。休止符：音乐中的"安静"。认识五线谱：5条线4个间，音符放在不同的位置表示不同的音高。', en: 'Recognize the simplest musical symbols. Notes: an open circle (whole note) lasts 4 beats, add a stem (half note) lasts 2 beats, filled in with stem (quarter note) lasts 1 beat. Rests: "silence" in music. Recognize the staff: 5 lines and 4 spaces.', age: '5-6' },
      { topic: '合唱入门', zh: '学习和其他人一起唱歌——合唱。合唱需要听别人的声音，和大家保持一样的速度和音量。从简单的齐唱开始：所有人唱同样的旋律。注意看指挥的手势：开始、停止、渐强、渐弱。合唱培养团队合作精神和集体荣誉感。', en: 'Learn to sing with others — choral singing. Choral singing requires listening to others voices and maintaining the same tempo and volume. Start with simple unison singing. Watch the conductors gestures. Choral singing develops teamwork spirit and collective pride.', age: '5-6' },
      { topic: '世界音乐', zh: '聆听来自世界各地的音乐。非洲鼓乐节奏热烈奔放，中国古筝曲悠扬婉转，爱尔兰笛声轻快活泼，印度西塔尔琴神秘悠远。不同文化有不同的音乐风格和乐器。通过世界音乐，了解文化的多样性，培养开放的心态和对不同文化的尊重。', en: 'Listen to music from around the world. African drumming is passionate, Chinese guzheng music is melodious, Irish flute music is lively, Indian sitar music is mysterious. Different cultures have different musical styles and instruments. Through world music, understand cultural diversity.', age: '4-6' },
      { topic: '音乐与情感', zh: '探索音乐如何表达情感。欢快的音乐让人想笑想跳，悲伤的音乐让人想哭想安静，恐怖的音乐让人紧张害怕。音乐家用不同的旋律、节奏、音色和强弱来表达不同的情感。听一段音乐，说说它让你感觉怎样、想象到了什么。音乐是情感的语言。', en: 'Explore how music expresses emotions. Happy music makes you want to laugh and jump, sad music makes you want to cry and be quiet, scary music makes you feel tense and afraid. Listen to a piece of music and describe how it makes you feel. Music is the language of emotion.', age: '4-6' },
      { topic: '节奏创作', zh: '尝试创作自己的节奏。用拍手、跺脚或打击乐器，创造一个4拍子的节奏模式。把自己的节奏教给同伴，学习同伴的节奏。几个人的节奏合在一起，就变成了丰富的节奏合奏。创作是音乐最有趣的部分。', en: 'Try creating your own rhythms. Use clapping, stomping, or percussion instruments to create a 4-beat rhythm pattern. Teach your rhythm to peers and learn their rhythms. When several peoples rhythms combine, they become a rich rhythmic ensemble. Creating is the most fun part of music.', age: '5-6' },
      { topic: '音乐欣赏：古典名曲', zh: '聆听适合幼儿的古典音乐名曲。贝多芬的《欢乐颂》旋律简单欢快，柴可夫斯基的《胡桃夹子》充满童话色彩，维瓦尔第的《四季》描绘大自然的变化。听音乐时闭上眼睛，想象音乐描绘的画面。不需要"听懂"什么，只需感受音乐的美。', en: 'Listen to classical music masterpieces suitable for young children. Beethovens "Ode to Joy" has a simple and cheerful melody, Tchaikovskys "Nutcracker" is full of fairy-tale colors, Vivaldis "Four Seasons" depicts changes in nature. Close your eyes while listening and imagine the pictures the music paints.', age: '4-6' },
      { topic: '歌曲表演', zh: '学习完整地表演一首歌曲。选择一首喜欢的歌，练习唱准旋律、记住歌词、加入适当的动作。表演时注意：面朝观众、面带微笑、声音洪亮。可以在班级音乐会或家长会上表演。表演培养自信心和表达能力，也是展示学习成果的方式。', en: 'Learn to perform a complete song. Choose a favorite song, practice singing the melody accurately, memorizing lyrics, and adding appropriate actions. When performing, remember: face the audience, smile, and sing clearly. Performing builds confidence and expression skills.', age: '5-6' }
    ],

    motor: [
      { topic: '跑步', zh: '学习正确的跑步姿势：身体微微前倾，手臂自然摆动，前脚掌着地。从慢跑开始，逐渐加快速度。练习直线跑、曲线跑和绕障碍跑。跑步增强心肺功能和腿部力量，是最基本的运动能力。注意跑步时呼吸均匀。', en: 'Learn proper running posture: lean slightly forward, swing arms naturally, land on the balls of your feet. Practice running in straight lines, curves, and around obstacles. Running enhances cardiovascular fitness and leg strength, and is the most fundamental athletic ability.', age: '3-5' },
      { topic: '跳跃', zh: '学习各种跳跃动作。原地双脚跳：像小兔子一样跳起来；立定跳远：双脚用力向前跳；单脚跳：像小鸟一样一只脚跳；跨步跳：大步向前跳。跳跃锻炼腿部力量和身体协调性。练习从低处跳下，注意落地时屈膝缓冲。', en: 'Learn various jumping movements. Jump in place with both feet; standing long jump; hop on one foot; stride jump. Jumping develops leg strength and body coordination. Practice jumping down from low heights, bending knees on landing to cushion.', age: '3-5' },
      { topic: '投掷', zh: '学习投掷的基本动作。从简单的下手抛球开始，逐渐学习上手投掷：手臂举过头顶，向前方用力投出。投掷时注意：侧身站立，投掷手在后，另一手指向目标，转体挥臂投出。用软球练习，目标从大到小逐渐增加难度。', en: 'Learn basic throwing movements. Start with simple underhand tossing, gradually learn overhand throwing. When throwing: stand sideways, throwing arm behind, other hand pointing at the target, rotate body and swing arm to throw. Practice with soft balls, gradually increasing difficulty.', age: '3-6' },
      { topic: '接球', zh: '学习接球的基本技巧。从接大球开始：双手伸出，手指自然张开，像一个大碗一样接住球。球接触手的瞬间，双手向身体方向收拢缓冲。从近距离慢速抛球开始，逐渐增加距离和速度。接球锻炼手眼协调和反应能力。', en: 'Learn basic catching skills. Start with catching large balls: extend both hands, fingers naturally spread, catching the ball like a big bowl. Start with close-range slow throws, gradually increasing distance and speed. Catching exercises hand-eye coordination and reaction time.', age: '3-6' },
      { topic: '平衡', zh: '练习各种平衡动作。单脚站立：抬起一只脚，保持身体稳定不摇晃；走平衡木：在窄窄的木板上行走，手臂张开保持平衡；脚尖走：踮起脚尖沿直线行走。平衡能力是所有运动的基础，良好的平衡感可以预防跌倒和受伤。', en: 'Practice various balancing movements. Stand on one foot; walk on a balance beam; tiptoe walk. Balance is the foundation of all movement; good balance prevents falls and injuries.', age: '3-6' },
      { topic: '攀爬', zh: '学习安全地攀爬。在攀爬架上练习：双手抓紧横杆，双脚踩稳，一步一步向上攀爬。攀爬时始终有三点接触。从低矮的攀爬架开始，逐渐挑战更高的。攀爬锻炼全身力量、协调性和勇气。下攀爬架时也要小心，不能跳下。', en: 'Learn to climb safely. Practice on climbing frames: grip the bars firmly, step steadily, climbing up step by step. Always maintain three points of contact. Climbing develops full-body strength, coordination, and courage.', age: '3-6' },
      { topic: '钻和爬', zh: '练习钻和爬的动作。钻：身体弯腰低头，从拱门或隧道中通过；爬：手膝着地，协调地向前爬行。设置障碍隧道和拱门，让孩子钻爬通过。钻爬锻炼身体柔韧性和空间感知。尝试不同方式的爬行：手膝爬、匍匐爬、熊爬。', en: 'Practice crawling and going through movements. Set up obstacle tunnels and arches for children to crawl through. Crawling develops body flexibility and spatial awareness. Try different crawling methods: hands and knees crawling, commando crawling, and bear crawling.', age: '3-5' },
      { topic: '拍球', zh: '学习拍球的技巧。用手掌和手指向下按压球，让球弹起后再拍。拍球时手腕要灵活，力度要适中。从原地拍球开始，逐渐尝试边走边拍。拍球锻炼手眼协调和节奏感。先用大球练习，熟练后换小球。', en: 'Learn bouncing ball skills. Press the ball downward with the palm and fingers, letting it bounce back up before bouncing again. Start with bouncing in place, gradually try bouncing while walking. Bouncing develops hand-eye coordination and rhythm sense.', age: '4-6' },
      { topic: '踢球', zh: '学习踢球的基本动作。用脚内侧踢球最准确：支撑脚站在球旁边，踢球脚向后摆，然后用脚内侧击球的中部。用脚背踢球力量最大。从踢静止球开始，逐渐尝试踢滚动的球。踢球锻炼腿部力量和协调性。', en: 'Learn basic kicking movements. Kicking with the inside of the foot is most accurate. Kicking with the instep is most powerful. Start with kicking stationary balls, gradually try kicking rolling balls. Kicking develops leg strength and coordination.', age: '4-6' },
      { topic: '简单游戏：红绿灯', zh: '玩"红绿灯"游戏。一个人当"交通灯"背对大家，其他人从起点向"交通灯"前进。当"交通灯"喊"红灯！"并转身时，所有人必须立刻停下不动。被看到还在动的人回到起点。先到达"交通灯"的人获胜。这个游戏锻炼反应速度和自控能力。', en: 'Play "Red Light, Green Light" game. One person is the "traffic light" facing away, while others move from the starting line toward the traffic light. When the traffic light calls "Red light!" and turns around, everyone must stop immediately. This game exercises reaction speed and self-control.', age: '3-6' },
      { topic: '简单游戏：老鹰捉小鸡', zh: '玩"老鹰捉小鸡"游戏。一个人当老鹰，一个人当母鸡，其他人当小鸡排成一队跟在母鸡后面。老鹰要捉小鸡，母鸡张开双臂保护小鸡，小鸡跟着母鸡左右躲闪。这个游戏锻炼奔跑、躲闪和团队合作能力。', en: 'Play "Eagle Catches Chicks" game. One person is the eagle, one is the mother hen, and others are chicks lined up behind the hen. This game develops running, dodging, and teamwork skills.', age: '3-6' },
      { topic: '简单游戏：丢手帕', zh: '玩"丢手帕"游戏。大家围成圆圈坐下，一个人拿着手帕在圈外跑，悄悄地把手帕丢在某人身后。如果坐着的人发现手帕，就捡起来追赶丢手帕的人。这个游戏锻炼观察力和奔跑能力。', en: 'Play "Drop the Handkerchief" game. Everyone sits in a circle, one person runs outside the circle with a handkerchief, quietly dropping it behind someone. This game develops observation and running skills.', age: '4-6' },
      { topic: '模仿动物运动', zh: '模仿各种动物的运动方式。像小兔子一样蹦蹦跳跳，像小鸭子一样摇摇摆摆走路，像小螃蟹一样横着走，像小青蛙一样蹲跳，像小蛇一样在地上爬行，像小鸟一样挥动手臂飞翔。模仿动物运动既有趣又锻炼身体。', en: 'Imitate various animal movements. Hop like a bunny, waddle like a duck, walk sideways like a crab, squat and jump like a frog, crawl on the ground like a snake, and flap arms like a bird flying. Animal movement imitation is both fun and physically beneficial.', age: '3-5' },
      { topic: '精细动作：串珠', zh: '练习串珠子，发展精细动作能力。将珠子一个一个穿到绳子上，可以按颜色或形状的规律来串。串珠需要手眼协调、手指灵活性和耐心。从大珠子粗绳子开始，逐渐使用更小的珠子和更细的绳子。', en: 'Practice stringing beads to develop fine motor skills. Thread beads onto a string one by one, following color or shape patterns. Beading requires hand-eye coordination, finger dexterity, and patience. Start with large beads and thick strings, gradually using smaller beads and thinner strings.', age: '3-5' },
      { topic: '精细动作：使用剪刀', zh: '学习安全使用儿童剪刀。正确握剪：大拇指放在上面的洞里，其他手指放在下面的洞里。练习剪纸：先沿直线剪，再沿曲线剪，最后剪出简单形状。使用剪刀时注意安全：剪刀尖朝前递给别人，不用时合上放好。', en: 'Learn to use childrens scissors safely. Proper grip: thumb in the top hole, other fingers in the bottom hole. Practice cutting paper: first cut along straight lines, then curves, and finally simple shapes. Safety rules: pass scissors handle-first to others, close and put away when not in use.', age: '4-6' },
      { topic: '精细动作：扣扣子和系鞋带', zh: '练习日常生活技能，发展精细动作。扣扣子：将扣子对准扣眼，从一面推到另一面。系鞋带：先打一个基础结，再打蝴蝶结。这些技能需要手指的灵活配合和反复练习。从大扣子开始，逐渐练习小扣子。', en: 'Practice daily living skills to develop fine motor abilities. Buttoning: align the button with the buttonhole and push through. Tying shoelaces: first make a basic knot, then tie a bow. These skills require flexible finger coordination and repeated practice.', age: '4-6' },
      { topic: '舞蹈基础', zh: '学习简单的舞蹈动作。跟着音乐做基本舞步：踏步、侧步、转圈、摇摆。学习简单的舞蹈组合。舞蹈培养节奏感、身体协调性和表现力。从模仿老师的动作开始，逐渐能记住和独立完成简单的舞蹈。', en: 'Learn simple dance movements. Follow music with basic dance steps: stepping, side steps, turning, and swaying. Dance develops rhythm sense, body coordination, and expressiveness. Start by imitating the teachers movements, gradually being able to remember and independently complete simple dances.', age: '4-6' },
      { topic: '体操基础', zh: '学习简单的体操动作。前滚翻：蹲下抱头，向前翻滚；桥：仰卧，双手撑地，身体拱起。体操锻炼柔韧性、力量和身体控制能力。在软垫上练习，老师做好保护。从最简单的动作开始，循序渐进。', en: 'Learn simple gymnastic movements. Forward roll: squat, tuck head, roll forward; bridge: lie on back, push up with hands, arch body. Gymnastics develops flexibility, strength, and body control. Practice on soft mats with teacher supervision.', age: '5-6' },
      { topic: '合作游戏：传球', zh: '玩传球游戏，培养合作精神。围成圆圈，按顺序传球：从头上传、从胯下传、左右交替传。也可以玩"音乐传球"——音乐响时传球，音乐停时球在谁手里谁表演节目。传球游戏锻炼反应速度和团队合作。', en: 'Play passing games to develop cooperation. Form a circle and pass the ball in order: overhead pass, under-leg pass, alternating left and right. Also play "musical pass." Passing games develop reaction speed and teamwork.', age: '3-6' },
      { topic: '障碍赛跑', zh: '设置障碍赛跑路线，综合锻炼各种运动能力。路线包括：钻过隧道、跨过低栏、绕过标志桶、走过平衡木、跳过小坑。计时比赛看谁最快完成，也可以不计时只关注完成质量。障碍赛跑锻炼综合运动能力、空间判断和解决问题的能力。', en: 'Set up obstacle courses for comprehensive physical development. The course includes: crawling through tunnels, stepping over low hurdles, weaving around cones, walking on balance beams, and jumping over small gaps. Obstacle courses develop comprehensive motor skills, spatial judgment, and problem-solving abilities.', age: '4-6' },
      { topic: '放松和拉伸', zh: '学习运动后的放松和拉伸。运动后需要让身体慢慢恢复平静：慢走几圈、深呼吸、轻轻抖动手臂和腿。做简单的拉伸：伸手够脚尖、手臂交叉拉伸、转腰。放松和拉伸帮助肌肉恢复，预防酸痛和受伤。养成运动后放松的好习惯，终身受益。', en: 'Learn post-exercise relaxation and stretching. After exercise, let the body gradually return to calm: walk slowly, breathe deeply, gently shake arms and legs. Do simple stretches. Relaxation and stretching help muscles recover, preventing soreness and injury. Develop the good habit of cooling down after exercise.', age: '3-6' }
    ]
  },

  // ============================================================
  // Key Stage 1 (Age 5-7, Grade 1-2)
  // 英国Key Stage 1 / 德国Grundschule 1-2年级 / 法国CP-CE1
  // ============================================================
  ks1: {

    math: [
      { topic: '20以内加法', zh: '掌握20以内的加法运算。学习加法的交换律：3+5=5+3=8。使用数轴、十格阵和实物来辅助计算。重点掌握凑十法：8+5=8+2+3=10+3=13，将一个加数拆分使另一个加数凑成10。通过反复练习达到熟练口算，目标是3秒内正确回答20以内加法。', en: 'Master addition within 20. Learn the commutative property: 3+5=5+3=8. Use number lines, ten frames, and objects to aid calculation. Focus on the make-ten strategy: 8+5=8+2+3=10+3=13. Through repeated practice, achieve fluent mental calculation, targeting correct answers within 3 seconds.', age: '5-6' },
      { topic: '20以内减法', zh: '掌握20以内的减法运算。理解减法是加法的逆运算：如果8+5=13，那么13-5=8。学习退位减法：13-5，先算13-3=10，再算10-2=8。使用数轴从大数往回跳来理解减法过程。通过加减法的关系来检验答案。', en: 'Master subtraction within 20. Understand subtraction as the inverse of addition. Learn regrouping subtraction: 13-5, first calculate 13-3=10, then 10-2=8. Use number lines to jump backward. Verify answers through the addition-subtraction relationship.', age: '5-6' },
      { topic: '2的乘法表', zh: '学习2的乘法表：2×1=2, 2×2=4, 2×3=6...2×12=24。理解乘法是重复加法：2×5就是5个2相加。2的乘法表的结果都是偶数，个位数字是0、2、4、6、8交替出现。通过数数2、4、6、8...来记忆2的乘法表。', en: 'Learn the 2 times table: 2×1=2, 2×2=4, 2×3=6...2×12=24. Understand multiplication as repeated addition. The results are all even numbers, with units digits alternating 0, 2, 4, 6, 8. Memorize by counting 2, 4, 6, 8...', age: '5-7' },
      { topic: '5的乘法表', zh: '学习5的乘法表：5×1=5, 5×2=10, 5×3=15...5×12=60。5的乘法表的结果个位数字总是0或5交替出现。理解5×3和3×5的结果相同（乘法交换律）。联系数硬币（5分硬币）的实际情境来记忆。', en: 'Learn the 5 times table: 5×1=5, 5×2=10, 5×3=15...5×12=60. The results always have units digits alternating between 0 and 5. Understand the commutative property: 5×3=3×5. Connect to real situations like counting 5-cent coins.', age: '5-7' },
      { topic: '10的乘法表', zh: '学习10的乘法表：10×1=10, 10×2=20...10×12=120。10的乘法表最容易记忆——只要在数字后面加一个0。理解10×4就是4个10相加。10的乘法表在日常生活中经常使用。', en: 'Learn the 10 times table: 10×1=10, 10×2=20...10×12=120. The 10 times table is easiest to memorize — just add a zero after the number. Understand that 10×4 is 4 tens added together.', age: '5-7' },
      { topic: '认识时间：整点和半点', zh: '学习认识钟表上的时间。认识时针（短针）和分针（长针）。整点：分针指向12，时针指向几就是几点。半点：分针指向6，时针在两个数字之间，取较小的数字就是几点半。在教具钟上拨出指定时间，练习读时间。', en: 'Learn to tell time on a clock. Recognize the hour hand (short) and minute hand (long). On the hour: minute hand points to 12. Half past: minute hand points to 6. Practice setting and reading times on a teaching clock.', age: '5-7' },
      { topic: '认识时间：一刻钟', zh: '学习认识一刻钟。分针指向3就是一刻（15分钟），分针指向9就是三刻（45分钟）。了解1小时=60分钟，1刻=15分钟，半小时=30分钟。计算简单的时间间隔。', en: 'Learn to tell quarter hours. When the minute hand points to 3, it is quarter past (15 minutes); when it points to 9, it is quarter to (45 minutes). Understand 1 hour = 60 minutes, 1 quarter = 15 minutes, half hour = 30 minutes. Calculate simple time intervals.', age: '6-7' },
      { topic: '认识硬币和简单计算', zh: '认识欧洲硬币：1c, 2c, 5c, 10c, 20c, 50c, €1, €2。学习用不同硬币组合出指定金额。进行简单的购物计算和找零。例如：买3欧元的书，给10欧元，找7欧元。', en: 'Recognize European coins: 1c, 2c, 5c, 10c, 20c, 50c, €1, €2. Learn to combine different coins to make a given amount. Do simple shopping calculations and calculate change. For example: buy a book for €3 with a €10 note, change is €7.', age: '5-7' },
      { topic: '2D图形的认识', zh: '深入学习2D图形。认识并命名：三角形、正方形、长方形、圆形、五边形、六边形。描述图形的特征：三角形有3条边和3个角；正方形有4条等长的边和4个直角。用图形拼出新的图形：两个三角形可以拼成一个长方形。', en: 'Deepen understanding of 2D shapes. Recognize and name: triangle, square, rectangle, circle, pentagon, hexagon. Describe shape properties. Compose new shapes: two triangles can make a rectangle. Identify 2D shapes in the environment.', age: '5-7' },
      { topic: '简单统计图表', zh: '学习收集数据并制作简单统计图表。用实物图和方块图来展示数据。例如：班上同学最喜欢的水果——苹果5人、香蕉3人、橙子4人。制作方块图，一格代表一个人。能从图表中读取信息。', en: 'Learn to collect data and create simple statistical charts. Use pictograms and block graphs to display data. For example: classmates favorite fruits — apples 5, bananas 3, oranges 4. Make a block graph where one block represents one person. Read information from charts.', age: '6-7' },
      { topic: '测量长度', zh: '学习测量长度的基本概念。使用非标准单位测量，然后引入标准单位：厘米(cm)。学习使用尺子测量——从0刻度开始，读出另一端对齐的刻度。估计物品的长度：一支铅笔大约15厘米。', en: 'Learn basic concepts of measuring length. Measure with non-standard units, then introduce standard units: centimeters (cm). Learn to use a ruler — start from the 0 mark and read the aligned measurement. Estimate object lengths: a pencil is about 15cm.', age: '6-7' },
      { topic: '测量重量', zh: '学习测量重量的基本概念。使用简单的天平比较两个物品的重量。引入标准单位：克(g)和千克(kg)。了解1千克=1000克。认识常见物品的大约重量：一个苹果约150克，一袋糖约1千克。', en: 'Learn basic concepts of measuring weight. Use simple balance scales to compare weights. Introduce standard units: grams (g) and kilograms (kg). Understand 1 kilogram = 1000 grams. Know approximate weights of common objects.', age: '6-7' },
      { topic: '分数初步：二分之一', zh: '理解二分之一(1/2)的概念。把一个整体平均分成2份，每份就是它的1/2。关键概念是"平均分"——两份必须一样大。理解1/2 + 1/2 = 1，两个一半合起来是一个整体。', en: 'Understand the concept of one-half (1/2). Divide a whole into 2 equal parts, each part is 1/2. The key concept is "equal sharing." Understand 1/2 + 1/2 = 1, two halves make one whole.', age: '6-7' },
      { topic: '分数初步：四分之一', zh: '理解四分之一(1/4)的概念。把一个整体平均分成4份，每份就是它的1/4。理解1/4是1/2的一半。1/4 + 1/4 + 1/4 + 1/4 = 1，四个四分之一合起来是一个整体。', en: 'Understand the concept of one-quarter (1/4). Divide a whole into 4 equal parts, each part is 1/4. Understand 1/4 is half of 1/2. 1/4 + 1/4 + 1/4 + 1/4 = 1, four quarters make one whole.', age: '6-7' },
      { topic: '100以内数的认识', zh: '认识100以内的数。理解两位数的组成：23由2个十和3个一组成。使用百数表观察数字的排列规律。比较两位数的大小：先比十位，十位大的数大；十位相同再比个位。', en: 'Recognize numbers within 100. Understand the composition of two-digit numbers: 23 consists of 2 tens and 3 ones. Use a hundred chart to observe number patterns. Compare two-digit numbers: compare tens digits first.', age: '5-7' },
      { topic: '100以内加减法', zh: '学习100以内的加减法。加法：先加整十数，再加个位数。减法：先减整十数，再减个位数。使用竖式计算：相同数位对齐，从个位算起，满十进一，不够减借一当十。', en: 'Learn addition and subtraction within 100. Addition: add tens first, then ones. Subtraction: subtract tens first, then ones. Use column method: align same place values, calculate from ones, carry over when reaching ten, borrow when needed.', age: '6-7' },
      { topic: '简单的乘法概念', zh: '理解乘法的含义——求几个相同加数的和的简便运算。3×4表示4个3相加，也可以表示3个4相加。使用阵列图(Array)来理解乘法。理解乘法交换律：3×4=4×3。', en: 'Understand the meaning of multiplication — a shortcut for adding equal groups. 3×4 means 4 groups of 3 or 3 groups of 4. Use arrays to understand multiplication. Understand the commutative property: 3×4=4×3.', age: '5-7' },
      { topic: '简单的除法概念', zh: '理解除法的含义——平均分配或分组。12÷3=4可以表示：把12个苹果平均分给3个人，每人得4个；也可以表示：12个苹果，每3个一组，可以分成4组。理解除法是乘法的逆运算。', en: 'Understand the meaning of division — sharing equally or grouping. 12÷3=4 can mean: share 12 apples equally among 3 people, each gets 4; or: 12 apples, groups of 3, make 4 groups. Understand division as the inverse of multiplication.', age: '6-7' },
      { topic: '3和4的乘法表', zh: '学习3的乘法表：3, 6, 9, 12, 15, 18, 21, 24, 27, 30, 33, 36。学习4的乘法表：4, 8, 12, 16, 20, 24, 28, 32, 36, 40, 44, 48。发现规律：3的乘法表的结果各位数字之和是3的倍数；4的乘法表的结果都是偶数。', en: 'Learn the 3 times table: 3, 6, 9, 12, 15, 18, 21, 24, 27, 30, 33, 36. Learn the 4 times table: 4, 8, 12, 16, 20, 24, 28, 32, 36, 40, 44, 48. Discover patterns: 3 times table results have digit sums that are multiples of 3; 4 times table results are all even.', age: '6-7' },
      { topic: '位置和方向', zh: '学习描述位置和方向。使用"左""右""前""后""上""下""之间""旁边"来描述物品的位置。学习简单的方位：东、南、西、北。太阳从东方升起，从西方落下。使用简单的方位词描述路线。', en: 'Learn to describe position and direction. Use "left," "right," "in front," "behind," "above," "below," "between," and "next to." Learn basic compass directions: east, south, west, north. The sun rises in the east and sets in the west.', age: '5-7' },
      { topic: '简单的应用题', zh: '学习解答简单的数学应用题。加法应用题：花园里有5朵红花和3朵黄花，一共有几朵花？减法应用题：小明有8颗糖，吃了3颗，还剩几颗？关键是理解题意，判断用加法还是减法。画图帮助理解。', en: 'Learn to solve simple math word problems. Addition: There are 5 red flowers and 3 yellow flowers, how many altogether? Subtraction: Tom has 8 candies, eats 3, how many are left? The key is understanding the problem and deciding whether to add or subtract.', age: '6-7' },
      { topic: '数字规律', zh: '学习发现和描述数字规律。递增规律：2, 4, 6, 8, 10...（每次加2）；递减规律：20, 18, 16, 14...（每次减2）。更复杂的规律：1, 2, 4, 7, 11...（每次加的数递增1）。能延续给定的规律，也能自己创造规律。', en: 'Learn to identify and describe number patterns. Increasing: 2, 4, 6, 8, 10... (add 2 each time); Decreasing: 20, 18, 16, 14... (subtract 2 each time). More complex: 1, 2, 4, 7, 11... Continue given patterns and create your own.', age: '6-7' },
      { topic: '容量和体积', zh: '学习容量和体积的初步概念。比较两个容器哪个装得多。引入标准单位：升(L)和毫升(ml)。了解1升=1000毫升。认识常见容器的容量：一盒牛奶约1升，一个汤勺约15毫升。', en: 'Learn introductory concepts of capacity and volume. Compare which container holds more. Introduce standard units: liters (L) and milliliters (ml). Understand 1 liter = 1000 milliliters. Know capacities of common containers.', age: '6-7' },
      { topic: '奇数和偶数', zh: '认识奇数和偶数。偶数：能被2整除的数（2, 4, 6, 8, 10...），可以平均分成两份。奇数：不能被2整除的数（1, 3, 5, 7, 9...），平均分成两份会多出一个。偶数的个位是0、2、4、6、8；奇数的个位是1、3、5、7、9。', en: 'Recognize odd and even numbers. Even numbers: divisible by 2 (2, 4, 6, 8, 10...), can be shared equally into two groups. Odd numbers: not divisible by 2 (1, 3, 5, 7, 9...). Even numbers end in 0, 2, 4, 6, 8; odd numbers end in 1, 3, 5, 7, 9.', age: '5-7' }
    ],

    english: [
      { topic: '自然拼读：短元音', zh: '系统学习5个短元音的发音：a如cat, e如bed, i如sit, o如hot, u如cup。练习拼读CVC单词：c-a-t→cat, p-e-n→pen。能听写简单的CVC单词。通过大量拼读练习建立字母与发音的自动联系。', en: 'Systematically learn the 5 short vowel sounds: a as in cat, e as in bed, i as in sit, o as in hot, u as in cup. Practice blending CVC words. Spell simple CVC words from dictation. Build automatic letter-sound correspondence through extensive practice.', age: '5-6' },
      { topic: '自然拼读：辅音组合', zh: '学习常见的辅音组合：bl, cl, fl, gl, pl, sl, br, cr, dr, fr, gr, pr, tr, sc, sk, sm, sn, sp, st, sw。练习拼读含有辅音组合的单词：bl-a-ck→black, st-o-p→stop。辅音组合在英语单词中非常常见，掌握它们大大提高阅读速度。', en: 'Learn common consonant blends: bl, cl, fl, gl, pl, sl, br, cr, dr, fr, gr, pr, tr, sc, sk, sm, sn, sp, st, sw. Practice blending words with consonant blends. Consonant blends are very common in English; mastering them greatly improves reading speed.', age: '5-7' },
      { topic: '自然拼读：长元音', zh: '学习长元音的拼写模式。魔法E(CVCe)：a-e如cake, i-e如bike, o-e如home, u-e如cube。元音组合：ai如rain, ay如day, ee如tree, ea如sea, igh如night, oa如boat。长元音使孩子能读出更多更复杂的单词。', en: 'Learn long vowel spelling patterns. Magic E (CVCe): a-e as in cake, i-e as in bike, o-e as in home, u-e as in cube. Vowel teams: ai as in rain, ay as in day, ee as in tree, ea as in sea, igh as in night, oa as in boat. Long vowels enable reading more complex words.', age: '6-7' },
      { topic: '常见词Level 1', zh: '掌握第一级高频常见词（约40个）：the, a, is, it, in, on, at, and, to, I, you, he, she, we, can, go, no, yes, me, my, am, are, was, were, be, been, have, has, had, do, does, did, will, would, could, should, this, that, these, those。这些词占英语文本的50%以上。', en: 'Master Level 1 high-frequency sight words (approximately 40): the, a, is, it, in, on, at, and, to, I, you, he, she, we, can, go, no, yes, me, my, am, are, was, were, be, been, have, has, had, do, does, did, will, would, could, should, this, that, these, those. These words account for over 50% of English text.', age: '5-6' },
      { topic: '常见词Level 2', zh: '掌握第二级高频常见词（约40个）：all, call, fall, small, came, make, name, some, come, over, know, down, find, kind, mind, behind, every, after, very, many, any, only, before, more, long, along, walk, talk, work, word, world, house, about, out, our, your, found, round, sound, thought。', en: 'Master Level 2 high-frequency sight words (approximately 40): all, call, fall, small, came, make, name, some, come, over, know, down, find, kind, mind, behind, every, after, very, many, any, only, before, more, long, along, walk, talk, work, word, world, house, about, out, our, your, found, round, sound, thought.', age: '6-7' },
      { topic: '简单句子阅读', zh: '练习阅读简单句子。从最基础的句子开始：The cat sat. I can see a dog. 逐渐增加句子长度和复杂度。阅读时用手指指着每个单词读，遇到不认识的词用拼读法尝试，利用图片帮助理解。', en: 'Practice reading simple sentences. Start with basic sentences: The cat sat. I can see a dog. Gradually increase complexity. Point to each word, use phonics for unknown words, use pictures to aid comprehension.', age: '5-6' },
      { topic: '写简单句子', zh: '学习写简单句子。句子规则：开头大写，结尾有句号。从最简单的句子开始：I like cats. The dog is big. 注意主语和动词的一致：He runs, They run。使用常见词和拼读能力来拼写单词。', en: 'Learn to write simple sentences. Sentence rules: start with a capital letter, end with a full stop. Start with: I like cats. The dog is big. Note subject-verb agreement. Use sight words and phonics skills to spell words.', age: '5-7' },
      { topic: '简单标点符号', zh: '学习使用基本的标点符号。句号(.)：用在陈述句末尾。问号(?)：用在疑问句末尾。感叹号(!)：用在感叹句末尾。逗号(,)：用来分隔句子中的项目。I like cats, dogs, and birds.', en: 'Learn to use basic punctuation. Full stop (.): end of statements. Question mark (?): end of questions. Exclamation mark (!): end of exclamations. Comma (,): separate items. I like cats, dogs, and birds.', age: '5-7' },
      { topic: '名词和动词', zh: '认识名词和动词。名词(Noun)是表示人、地方或事物的词：cat, school, Tom。动词(Verb)是表示动作或状态的词：run, jump, eat, is。在句子中找出名词和动词。理解每个句子至少需要一个动词。', en: 'Recognize nouns and verbs. A noun is a word for a person, place, or thing. A verb is a word for an action or state. Find nouns and verbs in sentences. Understand that every sentence needs at least one verb.', age: '6-7' },
      { topic: '形容词', zh: '认识形容词(Adjective)——描述名词的词。形容词告诉我们事物的特征：大小(big, small)、颜色(red, blue)、感觉(happy, sad)。在名词前使用形容词：a big house, the red car。尝试用形容词让句子更生动。', en: 'Recognize adjectives — words that describe nouns. Adjectives tell us about characteristics: size, color, feeling. Use adjectives before nouns: a big house, the red car. Try using adjectives to make sentences more vivid.', age: '6-7' },
      { topic: '阅读理解入门', zh: '学习基本的阅读理解技能。读完一个简短段落后，回答简单问题：Who is in the story? What happened? Where does it take place? 练习在文中找到答案的依据——用手指指出答案在哪里。', en: 'Learn basic reading comprehension skills. After reading a short passage, answer simple questions: Who is in the story? What happened? Where does it take place? Practice finding evidence in the text.', age: '6-7' },
      { topic: '故事结构', zh: '认识故事的基本结构：开头(Beginning)——介绍人物和背景；中间(Middle)——发生了什么事；结尾(End)——问题怎么解决的。用"故事山"(Story Mountain)来理解故事的发展过程。', en: 'Recognize the basic structure of stories: Beginning — introducing characters and setting; Middle — what happens; End — how the problem is resolved. Use a "Story Mountain" to understand story development.', age: '6-7' },
      { topic: '创意写作入门', zh: '开始尝试创意写作。从写1-2句话开始：描述一个图片、续写一个故事开头、写自己的一次经历。使用"5W"来丰富内容：Who, What, Where, When, Why。', en: 'Begin creative writing. Start with writing 1-2 sentences: describe a picture, continue a story, or write about a personal experience. Use "5W" to enrich content: Who, What, Where, When, Why.', age: '6-7' },
      { topic: '字母顺序', zh: '学习字母表的顺序和字母排序。能按顺序背诵26个字母。理解字典中单词按字母顺序排列。首字母相同时，看第二个字母。练习将一组单词按字母顺序排列。', en: 'Learn alphabetical order. Recite the 26 letters in order. Understand dictionary alphabetical ordering. When first letters are the same, look at the second letter. Practice arranging words in alphabetical order.', age: '5-7' },
      { topic: '拼写规则：双辅音', zh: '学习双辅音拼写规则。当短元音后跟一个辅音结尾时，加后缀要双写辅音：run+ing=running, sit+ing=sitting, hop+ing=hopping, big+er=bigger。这是因为需要保持前面的元音发短音。', en: 'Learn double consonant spelling rules. When a short vowel is followed by one consonant, double it before adding a suffix: run+ing=running, sit+ing=sitting, hop+ing=hopping, big+er=bigger. This keeps the preceding vowel short.', age: '6-7' },
      { topic: '拼写规则：不发音的e', zh: '学习不发音e的拼写规则。以不发音e结尾的单词，加后缀时通常去掉e：make+ing=making, like+ed=liked。但加以辅音开头的后缀时保留e：hope+less=hopeless, care+ful=careful。', en: 'Learn silent e spelling rules. Words ending in silent e usually drop the e before adding a suffix: make+ing=making, like+ed=liked. But keep the e before consonant-starting suffixes: hope+less=hopeless, care+ful=careful.', age: '6-7' },
      { topic: '反义词', zh: '学习反义词(Antonyms)——意思相反的词。big↔small, hot↔cold, fast↔slow, tall↔short, happy↔sad, light↔dark, full↔empty, old↔new, open↔close, up↔down。在句子中使用反义词来描述和比较。', en: 'Learn antonyms — words with opposite meanings. big↔small, hot↔cold, fast↔slow, tall↔short, happy↔sad, light↔dark, full↔empty, old↔new, open↔close, up↔down. Use antonyms in sentences to describe and compare.', age: '5-7' },
      { topic: '同义词', zh: '学习同义词(Synonyms)——意思相近的词。big↔large↔huge, small↔little↔tiny, happy↔glad↔joyful, fast↔quick↔rapid。使用同义词避免重复，让写作更丰富。', en: 'Learn synonyms — words with similar meanings. big↔large↔huge, small↔little↔tiny, happy↔glad↔joyful, fast↔quick↔rapid. Use synonyms to avoid repetition and enrich writing.', age: '6-7' },
      { topic: '复数形式', zh: '学习名词的复数形式。规则变化：大多数加-s；以s, x, z, ch, sh结尾加-es；以辅音+y结尾变y为i加-es。不规则变化：child→children, mouse→mice, foot→feet, tooth→teeth。', en: 'Learn plural forms. Regular: most add -s; words ending in s, x, z, ch, sh add -es; consonant+y changes y to i and adds -es. Irregular: child→children, mouse→mice, foot→feet, tooth→teeth.', age: '6-7' },
      { topic: '现在时和过去时', zh: '学习动词的现在时和过去时。规则变化：加-ed。不规则变化需要记忆：go→went, eat→ate, see→saw, come→came, run→ran, write→wrote, take→took, give→gave。', en: 'Learn present and past tenses. Regular: add -ed. Irregular forms need memorization: go→went, eat→ate, see→saw, come→came, run→ran, write→wrote, take→took, give→gave.', age: '6-7' },
      { topic: '手写练习', zh: '练习工整的手写。学习字母的正确笔顺和书写位置：小写字母a, c, e等写在中间格；b, d, h等上伸到上面格；g, j, p等下伸到下面格。注意字母之间的间距均匀。', en: 'Practice neat handwriting. Learn correct stroke order and positioning of letters. Keep even spacing between letters and one letter space between words. Practice writing daily, gradually improving speed and neatness.', age: '5-7' },
      { topic: '听写练习', zh: '定期进行听写(Spelling Dictation)练习。老师读出单词或句子，学生听写。听写步骤：听完整词→在脑中拼读→写出单词→检查。听写训练听觉记忆和拼写能力，是检验学习效果的重要方式。', en: 'Regularly practice spelling dictation. The teacher reads words or sentences, and students write them down. Steps: listen to the complete word → sound it out mentally → write the word → check. Dictation trains auditory memory and spelling ability.', age: '6-7' },
      { topic: '诗歌欣赏', zh: '阅读和欣赏简单的儿童诗歌。诗歌有节奏和韵律，读起来像唱歌一样。注意押韵词。学习背诵简单的诗歌，感受语言的美。尝试自己写一两行押韵的诗句。', en: 'Read and appreciate simple childrens poetry. Poems have rhythm and rhyme. Notice rhyming words. Learn to recite simple poems, experiencing the beauty of language. Try writing one or two rhyming lines yourself.', age: '6-7' }
    ],

    science: [
      { topic: '植物生长', zh: '深入学习植物的生长过程。种子发芽需要水和适宜的温度。根向下生长吸收水分和养分，茎向上生长支撑叶片，叶通过光合作用制造食物。了解不同植物的生长环境不同：仙人掌适合干燥环境，睡莲适合水环境。观察并记录一颗豆子从种子到开花的完整生长过程。', en: 'Deepen understanding of plant growth. Seeds need water and suitable temperature to germinate. Roots grow downward to absorb water and nutrients, stems grow upward to support leaves, and leaves make food through photosynthesis. Different plants suit different environments: cacti suit dry environments, water lilies suit aquatic environments. Observe and record a beans complete growth process from seed to flower.', age: '5-7' },
      { topic: '动物分类', zh: '学习对动物进行基本分类。按有无脊椎分为脊椎动物和无脊椎动物。脊椎动物包括：哺乳动物（猫、狗、鲸鱼）、鸟类（麻雀、老鹰）、爬行动物（蛇、蜥蜴）、两栖动物（青蛙、蝾螈）、鱼类（金鱼、鲨鱼）。无脊椎动物包括：昆虫（蝴蝶、蚂蚁）、蜘蛛、蜗牛、蚯蚓等。了解各类动物的基本特征。', en: 'Learn basic animal classification. By backbone presence: vertebrates and invertebrates. Vertebrates include: mammals (cats, dogs, whales), birds (sparrows, eagles), reptiles (snakes, lizards), amphibians (frogs, salamanders), fish (goldfish, sharks). Invertebrates include: insects (butterflies, ants), spiders, snails, earthworms. Understand basic characteristics of each group.', age: '5-7' },
      { topic: '材料特性', zh: '深入学习不同材料的特性。木头：坚硬、可以雕刻、会腐烂；金属：坚硬、有光泽、导热、会生锈；塑料：轻便、防水、不易分解；玻璃：透明、易碎；布料：柔软、透气、吸水；橡胶：有弹性、防水。根据用途选择合适的材料：窗户用玻璃因为透明，雨衣用塑料因为防水。', en: 'Deepen understanding of material properties. Wood: hard, carvable, rots; Metal: hard, shiny, conducts heat, rusts; Plastic: light, waterproof, does not decompose easily; Glass: transparent, breakable; Fabric: soft, breathable, absorbs water; Rubber: elastic, waterproof. Choose appropriate materials for purposes: windows use glass for transparency, raincoats use plastic for waterproofing.', age: '5-7' },
      { topic: '季节变化', zh: '科学地理解季节变化的原因和影响。地球绕太阳公转，地轴倾斜导致不同时期接收的阳光量不同，形成四季。春天：日照增加、气温回升、植物发芽、动物活跃。夏天：日照最长、气温最高、植物茂盛。秋天：日照减少、气温下降、落叶、动物储备食物。冬天：日照最短、气温最低、有些动物冬眠。', en: 'Scientifically understand the causes and effects of seasonal changes. The Earth orbits the Sun, and the tilted axis causes varying amounts of sunlight at different times, creating four seasons. Spring: increasing daylight, warming temperatures, plants sprouting. Summer: longest daylight, highest temperatures, lush plants. Autumn: decreasing daylight, cooling temperatures, falling leaves. Winter: shortest daylight, lowest temperatures, some animals hibernate.', age: '5-7' },
      { topic: '光和暗', zh: '深入学习光和暗的科学知识。光源分为自然光源（太阳、星星）和人造光源（灯泡、蜡烛、手电筒）。光沿直线传播，遇到不透明物体形成影子。影子的方向与光源方向相反，光源越近影子越大，光源越远影子越小。透明材料让光完全通过，半透明材料让部分光通过，不透明材料不让光通过。', en: 'Deepen scientific knowledge of light and dark. Light sources include natural (sun, stars) and artificial (bulbs, candles, flashlights). Light travels in straight lines and forms shadows when blocked by opaque objects. Shadow direction is opposite to the light source direction. Closer light sources make larger shadows, farther ones make smaller shadows. Transparent materials let all light through, translucent let some through, opaque block all light.', age: '5-7' },
      { topic: '声音', zh: '学习声音的科学知识。声音是由振动产生的——拨动吉他弦可以看到弦在振动，敲鼓时鼓面在振动。声音需要介质传播，在空气中传播，在水中传播更快，在真空中不能传播。声音有音调（高低）和音量（大小）两个特征。音调由振动频率决定——振动越快音调越高。音量由振动幅度决定——振幅越大音量越大。', en: 'Learn the science of sound. Sound is produced by vibrations — pluck a guitar string and see it vibrate, hit a drum and the surface vibrates. Sound needs a medium to travel: it travels through air, faster through water, and cannot travel through a vacuum. Sound has pitch (high/low) and volume (loud/soft). Pitch depends on vibration frequency — faster vibrations make higher pitch. Volume depends on amplitude — larger amplitude makes louder sound.', age: '5-7' },
      { topic: '电的初步认识', zh: '初步了解电的知识。电是一种能量形式，我们日常使用的电来自发电站。电可以产生光（灯泡）、热（电暖器）、运动（电风扇）。了解安全用电常识：不用湿手触摸电器，不把金属物品插入插座，不在电线上挂东西。认识电池——储存电能的装置，为手电筒、玩具等提供电力。', en: 'Introduction to electricity. Electricity is a form of energy; our daily electricity comes from power stations. Electricity can produce light (bulbs), heat (heaters), and motion (fans). Learn electrical safety: do not touch appliances with wet hands, do not insert metal objects into sockets, do not hang things on wires. Recognize batteries — devices that store electrical energy, powering flashlights and toys.', age: '6-7' },
      { topic: '简单电路', zh: '学习搭建简单电路。电路的基本组成：电源（电池）、导线、用电器（灯泡）。闭合电路时灯泡亮，断开电路时灯泡灭。尝试用一节电池、两根导线和一个灯泡搭建简单电路。了解开关的作用——控制电路的通断。注意：只能使用电池做实验，绝不能使用家用电源做实验，非常危险！', en: 'Learn to build simple circuits. Basic circuit components: power source (battery), wires, and a device (bulb). When the circuit is closed, the bulb lights up; when open, it goes off. Try building a simple circuit with one battery, two wires, and one bulb. Understand the function of switches — controlling circuit opening and closing. Safety: only use batteries for experiments, never household electricity — it is very dangerous!', age: '6-7' },
      { topic: '力和运动', zh: '学习力和运动的基本概念。力可以改变物体的形状（捏橡皮泥）、运动状态（推车使它动起来）和运动方向（踢球改变方向）。摩擦力是阻碍物体运动的力——在粗糙表面上物体运动较慢，在光滑表面上运动较快。重力是地球吸引物体的力——使苹果从树上掉下来，使我们站在地面上。', en: 'Learn basic concepts of forces and motion. Forces can change an objects shape (squeezing clay), motion state (pushing a cart to move it), and direction (kicking a ball). Friction opposes motion — objects move slower on rough surfaces, faster on smooth surfaces. Gravity is the Earths pulling force — making apples fall from trees, keeping us on the ground.', age: '6-7' },
      { topic: '岩石和土壤', zh: '认识常见的岩石和土壤。岩石分为三大类：火成岩（由岩浆冷却形成，如花岗岩）、沉积岩（由沉积物压缩形成，如石灰岩）、变质岩（由高温高压改变形成，如大理石）。土壤由岩石风化、有机物分解形成，是植物生长的基础。不同类型的土壤（沙土、黏土、壤土）有不同的保水和透气特性。', en: 'Recognize common rocks and soil. Three main rock types: igneous (formed from cooling magma, like granite), sedimentary (formed from compressed sediments, like limestone), metamorphic (formed by heat and pressure, like marble). Soil forms from weathered rock and decomposed organic matter, providing the basis for plant growth. Different soil types (sandy, clay, loam) have different water retention and aeration properties.', age: '6-7' },
      { topic: '食物链', zh: '学习食物链的基本概念。食物链描述谁吃谁的关系：草→兔子→狐狸。植物是生产者——能自己制造食物；动物是消费者——需要吃其他生物。食物链从生产者开始，到顶级消费者结束。了解食物链中每个角色的重要性：如果兔子消失了，草会过度生长，狐狸会缺少食物。保护生态平衡很重要。', en: 'Learn the basic concept of food chains. Food chains describe who eats whom: grass → rabbit → fox. Plants are producers — they make their own food; animals are consumers — they eat other organisms. Food chains start with producers and end with top consumers. Understand the importance of each role: if rabbits disappear, grass grows excessively and foxes lack food. Protecting ecological balance is important.', age: '6-7' },
      { topic: '人体和健康', zh: '学习人体的基本结构和健康知识。人体有骨骼系统（支撑身体、保护器官）、肌肉系统（使身体运动）、消化系统（消化食物、吸收营养）、呼吸系统（吸入氧气、呼出二氧化碳）、循环系统（运输血液和营养）。了解保持健康的方法：均衡饮食、适量运动、充足睡眠、保持清洁。', en: 'Learn basic human body structure and health knowledge. The human body has a skeletal system (supporting body, protecting organs), muscular system (enabling movement), digestive system (digesting food, absorbing nutrients), respiratory system (inhaling oxygen, exhaling carbon dioxide), and circulatory system (transporting blood and nutrients). Ways to stay healthy: balanced diet, regular exercise, adequate sleep, and good hygiene.', age: '5-7' },
      { topic: '天气观察和记录', zh: '系统学习天气观察和记录。使用温度计测量温度，用雨量器测量降雨量，用风向标观察风向。记录每日天气数据：温度、降雨量、风向、云量。发现天气的规律：早晨通常比中午凉，阴天温度比晴天低。了解极端天气：暴风雨、洪水、干旱，以及如何保护自己。', en: 'Systematically learn weather observation and recording. Use thermometers to measure temperature, rain gauges for rainfall, wind vanes for wind direction. Record daily weather data: temperature, rainfall, wind direction, cloud cover. Discover weather patterns: mornings are usually cooler than noon, cloudy days are cooler than sunny days. Learn about extreme weather: storms, floods, droughts, and how to protect yourself.', age: '5-7' },
      { topic: '水的循环', zh: '学习水的循环过程。太阳加热水面，水变成水蒸气上升（蒸发）；水蒸气在高空遇冷变成小水滴（凝结）；小水滴聚集形成云；云中的水滴变大变重，落下来就是雨（降水）；雨水流入河流、湖泊和地下，最终回到大海，循环往复。水循环确保地球上的淡水不断更新。', en: 'Learn the water cycle process. The sun heats water surfaces, turning water into vapor that rises (evaporation); vapor cools at high altitudes and becomes tiny water droplets (condensation); droplets gather to form clouds; cloud droplets grow larger and heavier, falling as rain (precipitation); rainwater flows into rivers, lakes, and underground, eventually returning to the sea, cycling continuously. The water cycle ensures Earths freshwater is constantly renewed.', age: '6-7' },
      { topic: ' habitats和适应', zh: '学习栖息地(Habitat)和适应的概念。栖息地是动物和植物生活的地方，提供食物、水和庇护所。不同栖息地有不同的生物：森林里有鹿和松鼠，沙漠里有骆驼和仙人掌，海洋里有鱼和海藻。适应是生物为在特定环境中生存而发展出的特征：北极熊有厚毛保暖，骆驼能长时间不喝水，仙人掌能储存水分。', en: 'Learn the concepts of habitats and adaptation. A habitat is where animals and plants live, providing food, water, and shelter. Different habitats have different organisms: forests have deer and squirrels, deserts have camels and cacti, oceans have fish and seaweed. Adaptation is characteristics organisms develop to survive in specific environments: polar bears have thick fur for warmth, camels can go long periods without water, cacti can store water.', age: '6-7' },
      { topic: '简单机械', zh: '认识简单的机械。杠杆：一根硬棒绕一个固定点转动，如跷跷板、开瓶器。轮轴：轮子和轴固定在一起转动，如门把手、方向盘。斜面：倾斜的平面帮助省力地移动物体，如斜坡、楼梯。滑轮：用绳子和轮子改变力的方向，如升旗用的滑轮。简单机械帮助我们省力或改变力的方向。', en: 'Recognize simple machines. Lever: a rigid bar rotating around a fixed point, like seesaws and bottle openers. Wheel and axle: a wheel fixed to an axle that rotates together, like door handles and steering wheels. Inclined plane: a slanted surface that helps move objects with less effort, like ramps and stairs. Pulley: using rope and wheel to change force direction, like flagpole pulleys. Simple machines help us save effort or change force direction.', age: '6-7' },
      { topic: '环境保护', zh: '学习环境保护的基本知识。了解污染：空气污染（工厂废气、汽车尾气）、水污染（工业废水、垃圾入河）、土壤污染（农药、垃圾填埋）。学习减少污染的方法：节约用水用电、减少垃圾、回收利用、绿色出行。了解回收标志：纸张、塑料、玻璃、金属可以回收再利用。每个人都可以为保护环境做出贡献。', en: 'Learn basic environmental protection knowledge. Understand pollution: air pollution (factory emissions, car exhaust), water pollution (industrial wastewater, litter in rivers), soil pollution (pesticides, landfill waste). Learn ways to reduce pollution: conserve water and electricity, reduce waste, recycle, green transportation. Understand recycling symbols: paper, plastic, glass, and metal can be recycled. Everyone can contribute to protecting the environment.', age: '5-7' },
      { topic: '太阳系初步', zh: '初步认识太阳系。太阳是一颗恒星，为地球提供光和热。地球是太阳系的八大行星之一，按离太阳的距离排列：水星、金星、地球、火星、木星、土星、天王星、海王星。地球是唯一已知有生命的行星，因为它有适宜的温度、水和大气层。月球是地球的卫星，绕地球运行，约28天转一圈。', en: 'Introduction to the solar system. The Sun is a star providing light and heat to Earth. Earth is one of eight planets in the solar system, ordered by distance from the Sun: Mercury, Venus, Earth, Mars, Jupiter, Saturn, Uranus, Neptune. Earth is the only known planet with life, having suitable temperature, water, and atmosphere. The Moon is Earths satellite, orbiting Earth approximately every 28 days.', age: '6-7' },
      { topic: '磁力', zh: '深入学习磁力的知识。磁铁有两个极：北极(N)和南极(S)。同极相斥（N和N推开，S和S推开），异极相吸（N和S互相吸引）。磁力可以隔着一些材料起作用——磁铁隔着纸或木板还能吸引铁。磁铁的磁力有范围——离得太远就吸不到了。地球本身就是一个大磁铁，指南针就是利用地球磁力来指示方向的。', en: 'Deepen knowledge of magnetic force. Magnets have two poles: north (N) and south (S). Like poles repel (N and N push apart, S and S push apart), opposite poles attract (N and S pull together). Magnetic force works through some materials — magnets can attract iron through paper or wood. Magnetic force has a range — too far away and it cannot attract. Earth itself is a giant magnet; compasses use Earths magnetic force to indicate direction.', age: '6-7' },
      { topic: '物质的状态', zh: '学习物质的三种状态：固态、液态和气态。固态：形状和体积固定，如冰块、石头。液态：体积固定但形状随容器变化，如水、牛奶。气态：没有固定形状和体积，会充满整个容器，如空气、水蒸气。物质的状态可以改变：冰加热变成水（融化），水加热变成水蒸气（蒸发），水蒸气冷却变成水（凝结），水冷却变成冰（凝固）。', en: 'Learn the three states of matter: solid, liquid, and gas. Solid: fixed shape and volume, like ice and rocks. Liquid: fixed volume but shape changes with container, like water and milk. Gas: no fixed shape or volume, fills the container, like air and steam. States can change: ice heated becomes water (melting), water heated becomes steam (evaporation), steam cooled becomes water (condensation), water cooled becomes ice (freezing).', age: '6-7' },
      { topic: '动物的生命周期', zh: '深入学习动物的生命周期。所有动物都经历出生、成长、繁殖和死亡的过程。不同动物的生命周期不同：蝴蝶经历完全变态（卵→幼虫→蛹→成虫），青蛙经历不完全变态（卵→蝌蚪→成蛙），哺乳动物直接生出幼崽。了解幼年和成年动物的区别：小蝌蚪用鳃呼吸、有尾巴，成年青蛙用肺和皮肤呼吸、有四条腿。', en: 'Deepen understanding of animal life cycles. All animals go through birth, growth, reproduction, and death. Different animals have different life cycles: butterflies undergo complete metamorphosis (egg → larva → pupa → adult), frogs undergo incomplete metamorphosis (egg → tadpole → adult frog), mammals give birth to live young. Understand differences between young and adult animals: tadpoles breathe with gills and have tails, adult frogs breathe with lungs and skin and have four legs.', age: '5-7' },
      { topic: '感官和科学观察', zh: '学习使用感官进行科学观察。观察是科学研究的第一步。用眼睛观察颜色、形状、大小和变化；用耳朵听声音的高低和强弱；用鼻子闻气味；用手触摸感受温度和质地；用舌头尝味道（仅在安全时）。学习记录观察结果：画图、写描述、做表格。科学观察要仔细、客观、有系统。', en: 'Learn to use senses for scientific observation. Observation is the first step in scientific research. Use eyes to observe color, shape, size, and changes; ears to hear pitch and volume; nose to smell; hands to feel temperature and texture; tongue to taste (only when safe). Learn to record observations: drawing, writing descriptions, making tables. Scientific observation should be careful, objective, and systematic.', age: '5-7' }
    ],

    history: [
      { topic: '个人时间线', zh: '学习创建个人时间线。从出生开始，记录重要事件：出生、第一次走路、上幼儿园、学会骑自行车、上小学等。理解"过去""现在""未来"的时间概念。时间线帮助我们看到自己如何成长和变化。比较不同人的时间线，发现每个人的经历都是独特的。', en: 'Learn to create a personal timeline. Starting from birth, record important events: birth, first steps, starting kindergarten, learning to ride a bike, starting school, etc. Understand the time concepts of "past," "present," and "future." Timelines help us see how we grow and change. Compare different peoples timelines, discovering that everyones experiences are unique.', age: '5-6' },
      { topic: '家庭历史', zh: '学习了解家庭历史。询问父母和祖父母关于过去的故事：他们小时候住在哪里、上什么学校、玩什么游戏。比较过去和现在的生活：以前没有智能手机，人们用信件联系；以前的食物种类没有现在多。制作简单的家谱，了解家庭成员之间的关系。珍惜家庭记忆和传统。', en: 'Learn about family history. Ask parents and grandparents about stories from the past: where they lived as children, what schools they attended, what games they played. Compare past and present life: before smartphones, people communicated by letters; there were fewer food varieties before. Create a simple family tree, understanding relationships between family members. Cherish family memories and traditions.', age: '5-7' },
      { topic: '重要人物：科学家', zh: '了解改变世界的重要科学家。艾萨克·牛顿——发现万有引力，据说一个苹果从树上掉下来启发了他。玛丽·居里——发现放射性元素，是第一位获得诺贝尔奖的女性。亚历山大·弗莱明——发现青霉素，拯救了无数人的生命。了解这些科学家的故事，激发对科学的好奇心和探索精神。', en: 'Learn about important scientists who changed the world. Isaac Newton — discovered gravity, reportedly inspired by an apple falling from a tree. Marie Curie — discovered radioactive elements, the first woman to win a Nobel Prize. Alexander Fleming — discovered penicillin, saving countless lives. Learn these scientists stories, inspiring curiosity and exploration in science.', age: '6-7' },
      { topic: '重要人物：探险家', zh: '了解著名的探险家。克里斯托弗·哥伦布——1492年横渡大西洋，到达美洲大陆。马可·波罗——从意大利旅行到中国，写了《马可·波罗游记》。费迪南德·麦哲伦——领导了第一次环球航行。探险家们勇敢地探索未知世界，他们的发现改变了人们对地球的认识。', en: 'Learn about famous explorers. Christopher Columbus — crossed the Atlantic in 1492, reaching the Americas. Marco Polo — traveled from Italy to China, writing "The Travels of Marco Polo." Ferdinand Magellan — led the first circumnavigation of the globe. Explorers bravely explored the unknown, and their discoveries changed peoples understanding of Earth.', age: '6-7' },
      { topic: '交通工具的变迁', zh: '了解交通工具的历史变迁。古代：步行、骑马、坐马车；中世纪：帆船远航；工业革命：蒸汽火车和蒸汽轮船；20世纪：汽车和飞机普及；现代：高铁、太空飞船。每种新交通工具的出现都大大缩短了旅行时间。从伦敦到巴黎，马车需要几天，现在坐欧洲之星只要2小时。', en: 'Understand the historical evolution of transportation. Ancient: walking, horseback, horse-drawn carriages; Medieval: sailing ships; Industrial Revolution: steam trains and steamships; 20th century: automobiles and airplanes became common; Modern: high-speed trains, spacecraft. Each new transportation mode greatly reduced travel time. From London to Paris: horse carriages took days, now the Eurostar takes just 2 hours.', age: '5-7' },
      { topic: '通信方式的变迁', zh: '了解通信方式的历史变迁。古代：口信、烽火、信鸽；中世纪：手写信件由邮差传递；19世纪：电报和电话发明；20世纪：广播、电视、传真；21世纪：互联网、电子邮件、智能手机视频通话。通信方式的进步使人们可以即时联系世界各地的朋友和家人。', en: 'Understand the historical evolution of communication. Ancient: verbal messages, beacon fires, carrier pigeons; Medieval: handwritten letters delivered by postal workers; 19th century: telegraph and telephone invented; 20th century: radio, television, fax; 21st century: internet, email, smartphone video calls. Communication advances enable instant contact with friends and family worldwide.', age: '5-7' },
      { topic: '城堡和中世纪生活', zh: '了解欧洲中世纪的城堡和生活。城堡是领主和家人的住所，也是防御工事。城堡有厚厚的石墙、塔楼、护城河和吊桥。中世纪人们的社会角色不同：领主管理土地，骑士作战，农民种地，工匠制作物品。了解中世纪的日常生活：穿什么衣服、吃什么食物、孩子们玩什么游戏。', en: 'Learn about European medieval castles and life. Castles were homes for lords and their families, also defensive fortifications. Castles had thick stone walls, towers, moats, and drawbridges. Medieval social roles differed: lords managed land, knights fought, peasants farmed, craftsmen made goods. Learn about daily medieval life: clothing, food, and childrens games.', age: '6-7' },
      { topic: '伟大的发明', zh: '了解改变世界的伟大发明。约翰内斯·古腾堡——印刷术，使书籍大量生产成为可能。托马斯·爱迪生——实用电灯泡，让人们不再依赖蜡烛和油灯。亚历山大·贝尔——电话，让人们可以远距离通话。莱特兄弟——飞机，实现了人类飞行的梦想。这些发明改变了人类的生活方式。', en: 'Learn about great inventions that changed the world. Johannes Gutenberg — printing press, enabling mass production of books. Thomas Edison — practical light bulb, freeing people from candles and oil lamps. Alexander Graham Bell — telephone, enabling long-distance conversation. Wright Brothers — airplane, realizing humanitys dream of flight. These inventions changed how people live.', age: '6-7' },
      { topic: '节日和传统', zh: '了解欧洲的重要节日和传统。圣诞节：12月25日，庆祝耶稣诞生，有圣诞树、礼物和圣诞老人。复活节：春分后第一个满月后的星期日，庆祝耶稣复活，有彩蛋和兔子。万圣节：10月31日，孩子们穿上奇装异服挨家挨户要糖果。了解不同国家有不同的节日传统，尊重文化多样性。', en: 'Learn about important European festivals and traditions. Christmas: December 25, celebrating Jesus birth, with Christmas trees, gifts, and Santa Claus. Easter: the first Sunday after the first full moon after the spring equinox, celebrating Jesus resurrection, with painted eggs and bunnies. Halloween: October 31, children dress up and go trick-or-treating. Different countries have different festival traditions; respect cultural diversity.', age: '5-7' },
      { topic: '学校的历史', zh: '了解学校教育的历史变迁。古代：只有富裕家庭的孩子能上学，学习阅读和写作。中世纪：修道院学校教授宗教和拉丁语。19世纪：开始有面向所有孩子的公立学校，但教室条件简陋，纪律严格。现代：所有孩子都有受教育的权利，教室有电脑和智能白板，学习内容丰富多样。珍惜今天的学习机会。', en: 'Understand the historical changes in school education. Ancient: only wealthy families children attended school, learning reading and writing. Medieval: monastery schools taught religion and Latin. 19th century: public schools for all children began, but conditions were basic and discipline was strict. Modern: all children have the right to education, classrooms have computers and smart boards, learning is rich and diverse. Value todays learning opportunities.', age: '6-7' },
      { topic: '历史上的儿童生活', zh: '了解历史上儿童的生活是什么样的。古罗马：男孩上学学习阅读和数学，女孩在家学习家务。中世纪：很多孩子从小就要干活。维多利亚时代：穷人的孩子去工厂或矿井做工，工作时间长、条件恶劣。现代：儿童有受教育的权利，有法律保护儿童不受剥削。了解儿童权利的进步。', en: 'Learn what childrens lives were like in history. Ancient Rome: boys attended school learning reading and math, girls learned household duties at home. Medieval: many children worked from a young age. Victorian era: poor children worked in factories or mines with long hours and terrible conditions. Modern: children have the right to education, with laws protecting them from exploitation. Understand the progress in childrens rights.', age: '6-7' },
      { topic: '伦敦大火', zh: '了解1666年伦敦大火。大火从一家面包店开始，因为当时伦敦的房子大多是木制的，街道狭窄，火势迅速蔓延。大火烧了4天，摧毁了13000多栋房屋和87座教堂。大火后，伦敦用砖石重建房屋，街道变宽，消防制度改善。这场灾难改变了伦敦的城市面貌。', en: 'Learn about the Great Fire of London in 1666. The fire started in a bakery; because most London houses were wooden and streets were narrow, the fire spread rapidly. It burned for 4 days, destroying over 13,000 houses and 87 churches. After the fire, London was rebuilt with brick and stone, wider streets, and improved firefighting. This disaster changed Londons cityscape.', age: '6-7' },
      { topic: '护士之母：南丁格尔', zh: '了解弗洛伦斯·南丁格尔的故事。南丁格尔是英国护士，在1853-1856年的克里米亚战争期间，她带领护士团队前往前线照顾伤兵。她发现医院条件极差，通过改善卫生条件，大大降低了伤兵的死亡率。她被称为"提灯女神"，开创了现代护理专业。了解关爱他人和坚持做正确事情的重要性。', en: 'Learn about Florence Nightingale. Nightingale was a British nurse who, during the Crimean War (1853-1856), led a team of nurses to care for wounded soldiers at the front. She found terrible hospital conditions and greatly reduced mortality by improving hygiene. Called "The Lady with the Lamp," she founded modern nursing. Learn the importance of caring for others and persisting in doing what is right.', age: '6-7' },
      { topic: '历史上的房子', zh: '了解不同历史时期的房子。史前时代：山洞和简陋的棚屋。古罗马：有庭院和供暖系统的石砌房屋。中世纪：木架结构的半木屋和石头城堡。维多利亚时代：排屋和联排别墅，有烟囱和煤气灯。现代：公寓楼和独立住宅，有中央供暖和现代设施。房子的变化反映了技术进步和生活方式的改变。', en: 'Learn about houses in different historical periods. Prehistoric: caves and simple shelters. Ancient Rome: stone houses with courtyards and heating systems. Medieval: timber-framed houses and stone castles. Victorian: terraced houses with chimneys and gas lamps. Modern: apartment buildings and detached houses with central heating and modern facilities. Changes in houses reflect technological progress and lifestyle changes.', age: '5-7' },
      { topic: '火的使用', zh: '了解火在人类历史中的重要作用。早期人类发现火可以取暖、照明、烹饪食物和驱赶野兽。学会生火是人类最重要的发现之一。从最初的保留天然火种，到后来学会用摩擦或击石取火。火的使用使人类能够吃熟食（更易消化、更安全），在寒冷地区生存，并在夜间活动。', en: 'Understand fires important role in human history. Early humans discovered fire could provide warmth, light, cook food, and scare away wild animals. Learning to make fire was one of humanitys most important discoveries. From preserving natural fire to learning friction or flint fire-making. Fire enabled eating cooked food (easier to digest, safer), surviving in cold regions, and being active at night.', age: '5-7' },
      { topic: '地图和历史', zh: '学习通过地图了解历史。比较不同时期的地图，发现边界的变化、城市的兴衰。古罗马帝国的地图显示它曾横跨欧洲、亚洲和非洲。中世纪欧洲的地图与今天大不相同——很多现代国家当时还不存在。了解地图是了解历史的重要工具，也是历史记录的一种形式。', en: 'Learn to understand history through maps. Compare maps from different periods, discovering changing borders and the rise and fall of cities. Ancient Roman Empire maps show it spanned Europe, Asia, and Africa. Medieval European maps differ greatly from today — many modern nations did not exist then. Understand maps are important tools for understanding history and a form of historical record.', age: '6-7' },
      { topic: '历史上的服装', zh: '了解不同历史时期的服装。古罗马：穿长袍(toga)和束腰外衣(tunic)。中世纪：农民穿简单的麻布衣服，贵族穿丝绸和毛皮。维多利亚时代：女性穿紧身胸衣和长裙，男性穿西装戴礼帽。现代：服装舒适多样，有牛仔裤、T恤、运动服等。服装的变化反映了社会观念和技术的进步。', en: 'Learn about clothing in different historical periods. Ancient Rome: togas and tunics. Medieval: peasants wore simple linen clothes, nobles wore silk and fur. Victorian: women wore corsets and long dresses, men wore suits and top hats. Modern: comfortable and diverse clothing — jeans, T-shirts, sportswear. Clothing changes reflect social attitudes and technological progress.', age: '5-7' },
      { topic: '口述历史', zh: '学习通过访谈收集口述历史。采访长辈：您小时候的生活是什么样的？您记得最重要的历史事件是什么？您小时候玩什么游戏？口述历史是记录普通人生活经历的重要方式，补充了书本历史没有记录的细节。学习提问技巧：开放式问题（"请告诉我关于……"）比是非题能获得更多信息。', en: 'Learn to collect oral history through interviews. Interview elders: What was your childhood like? What important historical events do you remember? What games did you play as a child? Oral history records ordinary peoples life experiences, supplementing details not recorded in books. Learn questioning techniques: open-ended questions ("Tell me about...") yield more information than yes/no questions.', age: '6-7' },
      { topic: '历史年表', zh: '学习使用和理解历史年表。年表按时间顺序排列重要事件，帮助我们理解事件发生的先后和间隔。了解公元前(BC)和公元后(AD)的概念。在年表上标记学习过的重要事件：古罗马时期、中世纪、伦敦大火等。理解历史时间的长度——从古罗马到今天约有2000年。', en: 'Learn to use and understand historical timelines. Timelines arrange important events chronologically, helping us understand sequence and intervals. Understand BC (Before Christ) and AD (Anno Domini) concepts. Mark important events on timelines: Ancient Rome, Medieval period, Great Fire of London. Understand the length of historical time — about 2000 years from Ancient Rome to today.', age: '6-7' },
      { topic: '历史证据', zh: '学习如何使用历史证据了解过去。历史证据包括：文字记录（日记、信件、官方文件）、实物（工具、武器、硬币）、图片（照片、绘画）、建筑（城堡、教堂）。历史学家像侦探一样，收集和分析各种证据来重建过去。了解不同类型的证据有不同的可靠性——同时期的记录比后来的回忆更可靠。', en: 'Learn how to use historical evidence to understand the past. Historical evidence includes: written records (diaries, letters, official documents), artifacts (tools, weapons, coins), images (photographs, paintings), buildings (castles, churches). Historians, like detectives, collect and analyze various evidence to reconstruct the past. Different types of evidence have different reliability — contemporary records are more reliable than later recollections.', age: '6-7' },
      { topic: '本地历史', zh: '学习了解本地的历史。观察周围的老建筑：它们建于什么时候？有什么故事？参观当地的博物馆和历史遗迹。了解本地地名的由来——很多地名包含历史信息。比较本地的新旧照片，发现变化。本地历史帮助我们理解自己生活的地方是如何发展成今天的样子的。', en: 'Learn about local history. Observe old buildings around you: when were they built? What stories do they have? Visit local museums and historical sites. Learn the origins of local place names — many contain historical information. Compare old and new photos of the local area, discovering changes. Local history helps us understand how where we live developed into what it is today.', age: '5-7' }
    ],

    geography: [
      { topic: '本地环境', zh: '学习观察和描述本地环境。本地有哪些自然特征：河流、山丘、森林、公园？有哪些人工特征：房屋、学校、商店、道路？本地环境有什么优点和需要改进的地方？通过实地考察和地图绘制来了解本地环境。培养对居住地的归属感和责任感。', en: 'Learn to observe and describe the local environment. What natural features exist locally: rivers, hills, forests, parks? What human features: houses, schools, shops, roads? What are the strengths and areas for improvement? Understand the local environment through field trips and map-making. Develop a sense of belonging and responsibility toward where you live.', age: '5-7' },
      { topic: '简单地图', zh: '学习阅读和绘制简单地图。理解地图是缩小版的俯瞰图。认识地图的基本元素：标题、方向标（指北针）、图例（符号说明）。绘制教室或学校的简单地图，用符号表示桌椅、门、窗等。学习按地图上的路线行走。理解地图上的方向：上北下南左西右东。', en: 'Learn to read and draw simple maps. Understand maps are scaled-down birds-eye views. Recognize basic map elements: title, compass rose, legend/key. Draw simple maps of the classroom or school, using symbols for desks, doors, windows. Follow routes on maps. Understand map directions: north is up, south is down, west is left, east is right.', age: '5-7' },
      { topic: '天气观察', zh: '系统观察和记录天气变化。每天记录天气状况：晴、多云、阴、雨、雪。使用简单工具：温度计测量温度，雨量器测量降雨量。发现天气的规律：夏天通常比冬天热，雨天通常比晴天凉爽。了解极端天气（暴风雨、热浪）的安全知识。制作天气图表展示一周的天气变化。', en: 'Systematically observe and record weather changes. Daily record weather conditions: sunny, cloudy, overcast, rain, snow. Use simple tools: thermometers for temperature, rain gauges for rainfall. Discover weather patterns: summer is usually hotter than winter, rainy days are usually cooler than sunny days. Learn safety knowledge for extreme weather. Create weather charts showing weekly changes.', age: '5-7' },
      { topic: '世界地图和大陆', zh: '认识世界地图和七大洲。七大洲：亚洲、非洲、北美洲、南美洲、南极洲、欧洲、大洋洲。了解各大洲的基本特征：非洲有撒哈拉沙漠和热带雨林，南极洲是最冷的大洲，欧洲是我们所在的大洲。在地球仪和世界地图上找到各大洲的位置。了解地球大部分被水覆盖。', en: 'Recognize world maps and seven continents. Seven continents: Asia, Africa, North America, South America, Antarctica, Europe, Oceania. Understand basic features: Africa has the Sahara Desert and tropical rainforests, Antarctica is the coldest continent, Europe is where we live. Find continents on globes and world maps. Understand Earth is mostly covered by water.', age: '6-7' },
      { topic: '海洋和河流', zh: '认识世界的主要海洋和河流。四大洋：太平洋（最大）、大西洋、印度洋、北冰洋（最小）。欧洲的重要河流：泰晤士河（英国）、塞纳河（法国）、莱茵河（德国）、多瑙河。河流对人类很重要：提供饮用水、灌溉农田、运输货物。了解河流从山上流下，最终汇入海洋。', en: 'Recognize major oceans and rivers of the world. Four oceans: Pacific (largest), Atlantic, Indian, Arctic (smallest). Important European rivers: Thames (UK), Seine (France), Rhine (Germany), Danube. Rivers are important to humans: providing drinking water, irrigating farmland, transporting goods. Understand rivers flow from mountains and eventually reach the sea.', age: '6-7' },
      { topic: '城镇和乡村', zh: '比较城镇和乡村的不同。城镇：人口多、建筑密集、有商店和学校、交通便利、工作机会多。乡村：人口少、空间开阔、有农田和牧场、环境安静、空气清新。了解有些人选择住在城镇，有些人选择住在乡村，各有优缺点。有些人住在城镇，每天到乡村工作；有些人住在乡村，到城镇上学。', en: 'Compare differences between towns and countryside. Towns: large population, dense buildings, shops and schools, convenient transport, more job opportunities. Countryside: small population, open space, farmland and pastures, quiet environment, fresh air. Understand people choose to live in towns or countryside, each with advantages and disadvantages. Some live in towns and work in the countryside; some live in the countryside and attend school in towns.', age: '5-7' },
      { topic: '学校周围的环境', zh: '深入了解学校周围的环境。学校附近有什么：公园、商店、图书馆、邮局、医院？画出学校周围的简单地图，标出重要地点。了解这些地方的功能和人们的工作。讨论如何改善学校周围的环境：增加绿化、减少垃圾、改善交通安全。', en: 'Deepen understanding of the area around school. What is near the school: parks, shops, libraries, post offices, hospitals? Draw a simple map of the school surroundings, marking important places. Understand the functions of these places and peoples jobs. Discuss how to improve the school environment: more greenery, less litter, better traffic safety.', age: '5-7' },
      { topic: '欧洲国家', zh: '认识欧洲的主要国家。英国、法国、德国、意大利、西班牙、荷兰、比利时、瑞士、奥地利、波兰等。了解每个国家的首都：伦敦、巴黎、柏林、罗马、马德里、阿姆斯特丹等。在欧洲地图上找到这些国家的位置。了解欧洲国家使用同一种货币——欧元（但英国使用英镑）。', en: 'Recognize major European countries. UK, France, Germany, Italy, Spain, Netherlands, Belgium, Switzerland, Austria, Poland, etc. Know each countrys capital: London, Paris, Berlin, Rome, Madrid, Amsterdam, etc. Find these countries on a European map. Understand European countries share a common currency — the euro (though the UK uses the British pound).', age: '6-7' },
      { topic: '地图符号和图例', zh: '学习地图符号和图例的使用。地图用符号代替真实的事物：蓝色表示水，绿色表示公园，红色线表示道路，黑色点表示建筑。图例(legend/key)解释每个符号代表什么。阅读不同类型的地图：街道地图、地铁图、公园导览图。练习使用图例来理解地图信息。', en: 'Learn to use map symbols and legends. Maps use symbols instead of real things: blue for water, green for parks, red lines for roads, black dots for buildings. The legend/key explains what each symbol represents. Read different types of maps: street maps, subway maps, park guides. Practice using legends to understand map information.', age: '5-7' },
      { topic: '方向和指南针', zh: '学习使用指南针确定方向。指南针的针总是指向北方。四个基本方向：北(N)、东(E)、南(S)、西(W)。四个中间方向：东北(NE)、东南(SE)、西南(SW)、西北(NW)。在操场上使用指南针确定方向。面朝北方时，右手边是东方，背后是南方，左手边是西方。', en: 'Learn to use a compass to determine direction. A compass needle always points north. Four cardinal directions: North (N), East (E), South (S), West (W). Four intercardinal directions: NE, SE, SW, NW. Use a compass on the playground to determine directions. Facing north, your right is east, behind you is south, your left is west.', age: '6-7' },
      { topic: '热带和寒带', zh: '了解地球上的热带和寒带。赤道附近是热带——全年炎热，没有明显的四季。两极附近是寒带——全年寒冷，有极昼和极夜现象。温带在热带和寒带之间——有明显的四季变化，欧洲大部分位于温带。不同气候带生活着不同的动植物：热带有热带雨林，寒带有北极熊和企鹅。', en: 'Understand tropical and polar zones on Earth. Near the equator is the tropical zone — hot year-round, no distinct seasons. Near the poles are polar zones — cold year-round, with midnight sun and polar night phenomena. Temperate zones lie between — with distinct seasons, most of Europe is in the temperate zone. Different climate zones have different plants and animals: tropical rainforests in the tropics, polar bears and penguins in the polar zones.', age: '6-7' },
      { topic: '水和人类', zh: '了解水对人类生活的重要性。人类用水来饮用、烹饪、清洁、灌溉和工业生产。淡水是有限的资源——地球上97%的水是咸水，只有3%是淡水，其中大部分被冻结在冰川中。节约用水的方法：关紧水龙头、缩短洗澡时间、收集雨水浇花。了解缺水地区人们的生活困难。', en: 'Understand the importance of water for human life. Humans use water for drinking, cooking, cleaning, irrigation, and industry. Freshwater is a limited resource — 97% of Earths water is saltwater, only 3% is freshwater, most of which is frozen in glaciers. Water conservation methods: turn off taps tightly, shorten showers, collect rainwater for watering plants. Understand the difficulties of life in water-scarce regions.', age: '6-7' },
      { topic: '世界各地的房屋', zh: '了解世界各地不同类型的房屋。因纽特人的冰屋——用冰块建造，保暖效果好。非洲的茅草屋——通风凉爽，适合炎热气候。荷兰的风车房屋——利用风能排水。日本的传统木屋——抗震设计。现代高楼公寓——节省土地空间。不同地区的房屋设计反映了当地的气候、材料和文化。', en: 'Learn about different types of houses around the world. Inuit igloos — built from ice blocks, excellent insulation. African thatched huts — well-ventilated, suitable for hot climates. Dutch windmill houses — using wind energy for drainage. Japanese traditional wooden houses — earthquake-resistant design. Modern high-rise apartments — saving land space. House designs reflect local climate, materials, and culture.', age: '5-7' },
      { topic: '地球仪和地球', zh: '学习使用地球仪了解地球。地球仪是地球的缩小模型，蓝色表示海洋，绿色/棕色表示陆地。地球表面71%被水覆盖，29%是陆地。地球绕地轴自转一圈需要24小时（一天），绕太阳公转一圈需要365天（一年）。地球是球形的，所以不同地方接收到的阳光量不同。', en: 'Learn to use globes to understand Earth. A globe is a scaled-down model of Earth; blue represents oceans, green/brown represents land. Earths surface is 71% water, 29% land. Earth rotates on its axis once every 24 hours (one day), and orbits the Sun once every 365 days (one year). Earth is spherical, so different places receive different amounts of sunlight.', age: '6-7' },
      { topic: '交通和旅行', zh: '了解不同的交通方式和旅行。短途：步行、自行车、公交车。中途：汽车、火车。长途：飞机、轮船。不同交通方式各有优缺点：步行最环保但最慢，飞机最快但最贵，火车舒适且环保。了解欧洲的著名交通：法国TGV高铁、英吉利海峡隧道、欧洲之星列车。旅行时需要准备什么：护照、车票、地图。', en: 'Learn about different transportation and travel. Short distance: walking, cycling, bus. Medium distance: car, train. Long distance: airplane, ship. Different modes have pros and cons: walking is most eco-friendly but slowest, airplanes are fastest but most expensive, trains are comfortable and eco-friendly. Learn about famous European transport: French TGV, Channel Tunnel, Eurostar. What to prepare for travel: passport, tickets, maps.', age: '5-7' },
      { topic: '环境保护和回收', zh: '学习环境保护和回收的知识。减少(Reduce)：少用一次性物品，节约水电。再利用(Reuse)：旧衣服捐给需要的人，玻璃瓶重复使用。回收(Recycle)：纸张、塑料、玻璃、金属分类回收。了解垃圾分类：可回收垃圾、厨余垃圾、有害垃圾、其他垃圾。在学校建立回收站，实践环保行动。', en: 'Learn about environmental protection and recycling. Reduce: use fewer disposable items, conserve water and electricity. Reuse: donate old clothes, reuse glass bottles. Recycle: sort paper, plastic, glass, and metal for recycling. Understand waste sorting: recyclable waste, kitchen waste, hazardous waste, other waste. Set up recycling stations at school, practicing environmental action.', age: '6-7' },
      { topic: '世界各地的食物', zh: '了解世界各地的不同食物。意大利：披萨和意大利面。法国：法棍面包和奶酪。德国：香肠和椒盐卷饼。英国：炸鱼薯条。日本：寿司和拉面。印度：咖喱和烤饼。墨西哥：玉米饼和辣椒。不同地区的食物受当地气候、农业和文化的影响。尝试品尝不同国家的食物，了解饮食文化的多样性。', en: 'Learn about different foods around the world. Italy: pizza and pasta. France: baguettes and cheese. Germany: sausages and pretzels. UK: fish and chips. Japan: sushi and ramen. India: curry and naan. Mexico: tortillas and chili. Different regional foods are influenced by local climate, agriculture, and culture. Try tasting foods from different countries, understanding the diversity of food culture.', age: '5-7' },
      { topic: '季节和农业', zh: '了解季节与农业的关系。春天：播种，农民在田地里种下种子。夏天：作物生长，需要充足的阳光和雨水。秋天：收获季节，农民收割成熟的庄稼。冬天：休耕或种植冬季作物。不同季节种植不同的作物：春天种小麦，夏天种玉米，秋天种冬油菜。了解现代农业技术：温室种植、灌溉系统、农业机械。', en: 'Understand the relationship between seasons and agriculture. Spring: sowing, farmers plant seeds in fields. Summer: crops grow, needing adequate sunlight and rain. Autumn: harvest season, farmers harvest mature crops. Winter: fallow or plant winter crops. Different crops in different seasons: wheat in spring, corn in summer, winter rapeseed in autumn. Learn about modern agricultural technology: greenhouse growing, irrigation systems, agricultural machinery.', age: '6-7' }
    ]
  },

  // ============================================================
  // Key Stage 2 (Age 7-11, Grade 3-6)
  // 英国Key Stage 2 / 德国Grundschule 3-4年级及Gymnasium 5-6年级 / 法国CE2-CM2
  // ============================================================
  ks2: {

    math: [
      { topic: '四位数加减法', zh: '掌握四位数的加减法。使用竖式计算：相同数位对齐，从个位算起。加法满十进一，减法不够减借一当十。例如：3456+2789=6245，5432-3678=1754。通过大量练习达到熟练计算，目标是准确快速地完成四位数运算。学会验算：加法用减法验算，减法用加法验算。', en: 'Master four-digit addition and subtraction. Use column method: align place values, calculate from ones. Carry over in addition, borrow in subtraction. For example: 3456+2789=6245, 5432-3678=1754. Achieve fluent calculation through extensive practice. Learn to check: verify addition with subtraction, verify subtraction with addition.', age: '7-9' },
      { topic: '乘法：两位数乘一位数', zh: '学习两位数乘一位数的乘法。使用竖式计算：先用一位数乘个位，再乘十位，满几十进几。例如：34×6=204（6×4=24，写4进2；6×3=18，18+2=20，写20）。理解每一步的含义：6×34就是6个34，即6×30+6×4=180+24=204。通过分配律理解竖式乘法的原理。', en: 'Learn two-digit by one-digit multiplication. Use column method: multiply ones first, then tens, carrying over. For example: 34×6=204. Understand each step: 6×34 means 6 groups of 34, i.e., 6×30+6×4=180+24=204. Understand column multiplication through the distributive property.', age: '7-9' },
      { topic: '乘法：两位数乘两位数', zh: '学习两位数乘两位数的乘法。使用竖式计算：先用下面数的个位乘上面的数，再用十位乘上面的数（注意要左移一位），最后相加。例如：23×14=23×4+23×10=92+230=322。理解每一步的含义：14个23等于4个23加10个23。', en: 'Learn two-digit by two-digit multiplication. Use column method: multiply by ones digit first, then by tens digit (shift one position left), then add. For example: 23×14=23×4+23×10=92+230=322. Understand: 14 groups of 23 equals 4 groups of 23 plus 10 groups of 23.', age: '8-10' },
      { topic: '长除法', zh: '学习长除法（竖式除法）。步骤：除→乘→减→落。例如：96÷6：9÷6=1余3，写1；1×6=6，9-6=3；落下6，36÷6=6，写6。所以96÷6=16。有余数的除法：97÷6=16余1。验算：16×6+1=97。长除法是数学的重要基础技能，需要反复练习。', en: 'Learn long division. Steps: divide → multiply → subtract → bring down. For example: 96÷6: 9÷6=1 remainder 3, write 1; 1×6=6, 9-6=3; bring down 6, 36÷6=6, write 6. So 96÷6=16. Division with remainders: 97÷6=16 remainder 1. Check: 16×6+1=97. Long division is an important foundational math skill requiring repeated practice.', age: '8-10' },
      { topic: '分数的加减', zh: '学习同分母和异分母分数的加减法。同分母：分母不变，分子相加减。1/5+2/5=3/5。异分母：先通分（找最小公倍数），再加减。1/3+1/4=4/12+3/12=7/12。结果要化简为最简分数：4/8=1/2。理解分数加减的含义——把相同大小的部分合在一起或取走。', en: 'Learn fraction addition and subtraction. Same denominators: keep denominator, add/subtract numerators. 1/5+2/5=3/5. Different denominators: find common denominator first (LCM), then add/subtract. 1/3+1/4=4/12+3/12=7/12. Simplify results to lowest terms: 4/8=1/2. Understand fraction addition/subtraction as combining or removing equal-sized parts.', age: '9-11' },
      { topic: '分数和小数', zh: '学习分数和小数的互化。1/10=0.1, 1/4=0.25, 1/2=0.5, 3/4=0.75, 1/5=0.2, 1/8=0.125。分母是10、100、1000的分数可以直接写成小数：3/10=0.3, 47/100=0.47。小数比较：先比整数部分，再比小数部分。0.5>0.3, 0.45<0.5。理解小数是分数的另一种写法。', en: 'Learn to convert between fractions and decimals. 1/10=0.1, 1/4=0.25, 1/2=0.5, 3/4=0.75, 1/5=0.2, 1/8=0.125. Fractions with denominators 10, 100, 1000 convert directly: 3/10=0.3, 47/100=0.47. Decimal comparison: compare whole parts first, then decimal parts. 0.5>0.3, 0.45<0.5. Understand decimals as another way to write fractions.', age: '9-11' },
      { topic: '小数加减法', zh: '学习小数的加减法。关键：小数点对齐（相同数位对齐）。例如：3.45+2.3=5.75（注意2.3=2.30），10.5-3.82=6.68。计算时可以在末尾补0使位数相同。小数加减法在日常生活中经常使用：计算购物总价、测量长度等。', en: 'Learn decimal addition and subtraction. Key: align decimal points (same place values). For example: 3.45+2.3=5.75 (note 2.3=2.30), 10.5-3.82=6.68. Add zeros at the end to make the same number of decimal places. Decimal operations are frequently used in daily life: calculating shopping totals, measuring lengths, etc.', age: '9-11' },
      { topic: '面积和周长', zh: '学习计算面积和周长。周长：围绕图形一周的长度。长方形周长=2×(长+宽)，正方形周长=4×边长。面积：图形所占平面的大小。长方形面积=长×宽，正方形面积=边长×边长。单位：周长用长度单位(cm, m)，面积用面积单位(cm², m²)。1m²=10000cm²。计算不规则图形的面积：可以分割成规则图形再相加。', en: 'Learn to calculate area and perimeter. Perimeter: the distance around a shape. Rectangle perimeter=2×(length+width), square perimeter=4×side. Area: the space a shape covers. Rectangle area=length×width, square area=side×side. Units: perimeter uses length units (cm, m), area uses square units (cm², m²). 1m²=10000cm². Irregular shapes: divide into regular shapes and add areas.', age: '8-10' },
      { topic: '角度', zh: '学习角度的概念和测量。角度是两条射线从同一点出发所张开的程度。使用量角器测量角度：将量角器的中心对准角的顶点，0°线对准一条边，读出另一条边对应的刻度。特殊角：直角=90°，平角=180°，周角=360°，锐角<90°，钝角>90°。三角形内角和=180°。', en: 'Learn the concept and measurement of angles. An angle is the amount of opening between two rays from the same point. Use a protractor to measure: align the center with the vertex, 0° line with one side, read the other sides measurement. Special angles: right angle=90°, straight angle=180°, full angle=360°, acute<90°, obtuse>90°. Triangle angles sum=180°.', age: '9-11' },
      { topic: '3D图形', zh: '学习3D图形的认识和性质。立方体(Cube)：6个正方形面、12条棱、8个顶点。长方体(Cuboid)：6个长方形面。球体(Sphere)：没有棱和顶点。圆柱体(Cylinder)：2个圆形面和1个曲面。圆锥体(Cone)：1个圆形面和1个曲面。棱锥体(Pyramid)：底面是多边形，侧面是三角形。了解3D图形的展开图(net)。', en: 'Learn to recognize and describe 3D shapes. Cube: 6 square faces, 12 edges, 8 vertices. Cuboid: 6 rectangular faces. Sphere: no edges or vertices. Cylinder: 2 circular faces and 1 curved surface. Cone: 1 circular face and 1 curved surface. Pyramid: polygonal base with triangular sides. Understand nets of 3D shapes.', age: '8-10' },
      { topic: '坐标系统', zh: '学习平面直角坐标系。在坐标平面上，水平方向是x轴，垂直方向是y轴，交点是原点(0,0)。用有序数对(x,y)表示点的位置：先写x坐标（横向），再写y坐标（纵向）。例如点(3,4)表示从原点向右3格、向上4格的位置。在坐标平面上标出点和绘制简单图形。', en: 'Learn the Cartesian coordinate system. On a coordinate plane, the horizontal axis is x, the vertical axis is y, and the intersection is the origin (0,0). Use ordered pairs (x,y) to represent point positions: x-coordinate first (horizontal), y-coordinate second (vertical). For example, point (3,4) is 3 right and 4 up from the origin. Plot points and draw simple shapes on coordinate planes.', age: '9-11' },
      { topic: '数据统计', zh: '学习收集、整理和分析数据。制作条形图(Bar Chart)：用长方形的高度表示数量，注意标题、坐标轴标签和刻度。折线图(Line Graph)：用线段连接数据点，显示变化趋势。饼图(Pie Chart)：用扇形大小表示各部分占总体的比例。计算平均数(Mean)：所有数据之和÷数据个数。读懂统计图并从中得出结论。', en: 'Learn to collect, organize, and analyze data. Create bar charts: use rectangle heights for quantities, noting titles, axis labels, and scales. Line graphs: connect data points with lines showing trends. Pie charts: use sector sizes to show proportions. Calculate the mean: sum of all data ÷ number of data points. Read statistical charts and draw conclusions.', age: '9-11' },
      { topic: '比例', zh: '学习比例的概念和计算。比例表示两个量之间的关系。例如：3个苹果2欧元，6个苹果多少欧元？用比例计算：3:2=6:x，x=4欧元。比例在日常生活中的应用：食谱的份量换算、地图比例尺（1:10000表示图上1cm等于实际100m）、模型制作。理解正比例关系：一个量增大，另一个量也按相同比例增大。', en: 'Learn the concept and calculation of ratio and proportion. Proportion represents the relationship between two quantities. For example: 3 apples cost 2 euros, how much for 6 apples? 3:2=6:x, x=4 euros. Applications: recipe scaling, map scales (1:10000 means 1cm on map=100m real), model making. Understand direct proportion: as one quantity increases, the other increases by the same ratio.', age: '9-11' },
      { topic: '负数', zh: '学习负数的概念和运算。负数是比0小的数，用负号表示：-1, -2, -3...在数轴上，负数在0的左边。负数的应用：温度（-5°C表示零下5度）、海拔（-100m表示低于海平面100米）、银行账户（-50欧元表示透支50欧元）。负数加法：(-3)+(-2)=-5。负数减法：(-3)-(-2)=-1。理解正数和负数的加减法规则。', en: 'Learn the concept and operations of negative numbers. Negative numbers are less than 0, written with a minus sign: -1, -2, -3... On a number line, negatives are to the left of 0. Applications: temperature (-5°C means 5 below zero), elevation (-100m means 100m below sea level), bank accounts (-50 euros means 50 overdrawn). Addition: (-3)+(-2)=-5. Subtraction: (-3)-(-2)=-1. Understand rules for adding and subtracting positive and negative numbers.', age: '10-11' },
      { topic: '罗马数字', zh: '学习罗马数字系统。基本符号：I=1, V=5, X=10, L=50, C=100, D=500, M=1000。规则：相同符号重复表示相加（III=3）；大符号在左表示相加（VI=6）；小符号在左表示相减（IV=4, IX=9）。练习转换：2024=MMXXIV, 1492=MCDXCII。罗马数字至今仍在使用：钟表、书籍章节、君主称号。', en: 'Learn the Roman numeral system. Basic symbols: I=1, V=5, X=10, L=50, C=100, D=500, M=1000. Rules: repeated symbols add (III=3); larger symbol on left adds (VI=6); smaller symbol on left subtracts (IV=4, IX=9). Practice conversion: 2024=MMXXIV, 1492=MCDXCII. Roman numerals are still used today: clocks, book chapters, monarch titles.', age: '8-10' },
      { topic: '对称', zh: '学习对称的概念。轴对称(Reflection Symmetry)：图形沿一条线对折后两边完全重合，这条线叫对称轴。正方形有4条对称轴，等腰三角形有1条，圆有无数条。旋转对称(Rotational Symmetry)：图形旋转一定角度后与原图形重合。正方形旋转90°后重合，旋转对称阶数为4。在方格纸上画对称图形。', en: 'Learn the concept of symmetry. Reflection symmetry: a shape folds along a line with both sides matching exactly; this line is the line of symmetry. A square has 4 lines of symmetry, an isosceles triangle has 1, a circle has infinitely many. Rotational symmetry: a shape coincides with itself after rotating by a certain angle. A square coincides after 90° rotation, order 4. Draw symmetrical shapes on grid paper.', age: '8-10' },
      { topic: '时间计算', zh: '学习时间的计算。时间单位换算：1小时=60分钟=3600秒，1天=24小时，1周=7天，1年=365天（闰年366天）。计算时间间隔：从8:45到11:30经过了多少时间？2小时45分钟。跨天的时间计算：晚上10:30到第二天早上6:15，经过了7小时45分钟。了解24小时制和12小时制的转换。', en: 'Learn time calculations. Unit conversions: 1 hour=60 minutes=3600 seconds, 1 day=24 hours, 1 week=7 days, 1 year=365 days (366 in leap years). Calculate time intervals: from 8:45 to 11:30 is 2 hours 45 minutes. Cross-midnight calculations: 10:30 PM to 6:15 AM next day is 7 hours 45 minutes. Understand 24-hour and 12-hour clock conversions.', age: '7-9' },
      { topic: '体积', zh: '学习体积的概念和计算。体积是物体所占空间的大小。长方体体积=长×宽×高，正方体体积=边长×边长×边长。体积单位：mm³, cm³, m³。1cm³就是边长1cm的正方体的体积。液体体积用升和毫升：1L=1000mL=1000cm³。测量不规则物体体积：用量筒，记录放入前后水面刻度的差值。', en: 'Learn the concept and calculation of volume. Volume is the space an object occupies. Cuboid volume=length×width×height, cube volume=side×side×side. Units: mm³, cm³, m³. 1cm³ is the volume of a 1cm cube. Liquid volume uses liters and milliliters: 1L=1000mL=1000cm³. Measure irregular object volume: use a measuring cylinder, record the water level difference before and after adding the object.', age: '10-11' },
      { topic: '概率初步', zh: '学习概率的初步概念。概率描述某件事发生的可能性大小。概率范围从0（不可能发生）到1（一定发生）。抛硬币正面朝上的概率是1/2。掷骰子得到3的概率是1/6。从一副扑克牌中抽到红心的概率是1/4。用分数表示概率：事件发生的方式数÷所有可能的方式数。通过实验验证理论概率。', en: 'Learn introductory probability concepts. Probability describes how likely an event is to occur. Range from 0 (impossible) to 1 (certain). Coin flip heads probability is 1/2. Rolling a 3 on a die is 1/6. Drawing a heart from a deck is 1/4. Express probability as fractions: favorable outcomes ÷ total possible outcomes. Verify theoretical probability through experiments.', age: '10-11' },
      { topic: '代数初步', zh: '学习代数的初步概念。用字母表示未知数：如果x+3=7，那么x=4。用字母表示规律：第n个三角形数=n(n+1)/2。简单方程：2x+1=9，2x=8，x=4。理解等式的性质：等式两边同时加、减、乘、除同一个数，等式仍然成立。代数是数学从具体到抽象的重要飞跃。', en: 'Learn introductory algebra concepts. Use letters for unknowns: if x+3=7, then x=4. Use letters for patterns: the nth triangular number=n(n+1)/2. Simple equations: 2x+1=9, 2x=8, x=4. Understand equality properties: adding, subtracting, multiplying, or dividing both sides by the same number maintains equality. Algebra is an important leap from concrete to abstract mathematics.', age: '10-11' },
      { topic: '乘法表6-9', zh: '学习6、7、8、9的乘法表。6×1=6到6×12=72；7×1=7到7×12=84；8×1=8到8×12=96；9×1=9到9×12=108。记忆技巧：9的乘法表结果，十位数字和个位数字之和等于9（如9×7=63，6+3=9）。7×8=56是常见的难点，用"5,6,7,8"记忆（56=7×8）。通过歌曲、游戏和反复练习来熟练掌握所有乘法表。', en: 'Learn the 6, 7, 8, and 9 times tables. Memory tricks: 9 times table results have digit sums equaling 9 (9×7=63, 6+3=9). 7×8=56 is a common difficulty, use "5,6,7,8" to remember (56=7×8). Master all times tables through songs, games, and repeated practice.', age: '7-9' },
      { topic: '分数的乘除', zh: '学习分数的乘法和除法。分数乘法：分子乘分子，分母乘分母。1/2×3/4=3/8。分数乘整数：1/3×6=6/3=2。分数除法：除以一个分数等于乘以它的倒数。1/2÷1/4=1/2×4/1=4/2=2。理解含义：1/2÷1/4=2表示1/2里面有几个1/4，答案是2个。结果要化简为最简分数。', en: 'Learn fraction multiplication and division. Fraction multiplication: multiply numerators, multiply denominators. 1/2×3/4=3/8. Fraction times whole number: 1/3×6=6/3=2. Fraction division: dividing by a fraction equals multiplying by its reciprocal. 1/2÷1/4=1/2×4/1=4/2=2. Understanding: 1/2÷1/4=2 means how many 1/4s are in 1/2, the answer is 2. Simplify results to lowest terms.', age: '10-11' }
    ],

    english: [
      { topic: '阅读理解进阶', zh: '提高阅读理解能力。阅读较长的文本后，回答更复杂的问题：事实性问题（文中明确写出的答案）、推理性问题（需要根据线索推断的答案）、评价性问题（你对文中观点的看法）。学习使用PEE方法回答问题：Point(观点)+Evidence(证据)+Explanation(解释)。从文本中引用证据支持你的观点。', en: 'Improve reading comprehension skills. After reading longer texts, answer more complex questions: factual (explicitly stated), inferential (requiring deduction from clues), evaluative (your opinion on text views). Learn the PEE method: Point + Evidence + Explanation. Quote evidence from the text to support your views.', age: '7-9' },
      { topic: '创意写作：故事', zh: '学习写完整的故事。故事结构：开头（设置场景和介绍人物）、发展（问题出现）、高潮（最紧张的时刻）、解决（问题被解决）、结尾。使用描写性语言让故事更生动：形容词、副词、比喻。注意段落划分——每个新话题或时间变化开始新段落。写300-500字的故事，注意开头吸引读者、结尾令人满意。', en: 'Learn to write complete stories. Story structure: opening (setting scene and introducing characters), development (problem arises), climax (most tense moment), resolution (problem solved), ending. Use descriptive language: adjectives, adverbs, similes. Note paragraph division — start a new paragraph for each new topic or time change. Write 300-500 word stories with engaging openings and satisfying endings.', age: '8-11' },
      { topic: '创意写作：描写文', zh: '学习写描写文(Description)。用五官感受来描写：视觉（看到了什么颜色、形状）、听觉（听到了什么声音）、嗅觉（闻到了什么气味）、触觉（摸到了什么感觉）、味觉（尝到了什么味道）。使用比喻和拟人让描写更生动："月亮像一只银盘""风在树间低语"。写一段关于森林、海滩或城市的描写文。', en: 'Learn to write descriptive texts. Use five senses: sight (colors, shapes), hearing (sounds), smell (scents), touch (textures), taste (flavors). Use similes and personification: "The moon was like a silver plate" "The wind whispered through the trees." Write a descriptive passage about a forest, beach, or city.', age: '8-11' },
      { topic: '语法：词性', zh: '系统学习英语的词性(Parts of Speech)。名词(Noun)：人、地方、事物。动词(Verb)：动作或状态。形容词(Adjective)：描述名词。副词(Adverb)：描述动词、形容词或其他副词。代词(Pronoun)：代替名词。介词(Preposition)：表示位置关系。连词(Conjunction)：连接词或句子。冠词(Article)：a, an, the。在句子中识别不同词性。', en: 'Systematically learn English parts of speech. Noun: person, place, thing. Verb: action or state. Adjective: describes nouns. Adverb: describes verbs, adjectives, or other adverbs. Pronoun: replaces nouns. Preposition: shows position relationships. Conjunction: connects words or sentences. Article: a, an, the. Identify different parts of speech in sentences.', age: '7-11' },
      { topic: '语法：时态', zh: '系统学习英语时态。现在进行时：am/is/are+动词ing（I am running）。一般现在时：动词原形/第三人称加s（I run / She runs）。一般过去时：动词过去式（I ran）。现在完成时：have/has+过去分词（I have run）。过去进行时：was/were+动词ing（I was running）。了解每种时态的用法和标志词。', en: 'Systematically learn English tenses. Present continuous: am/is/are+verb-ing (I am running). Simple present: verb/s (I run/She runs). Simple past: past tense form (I ran). Present perfect: have/has+past participle (I have run). Past continuous: was/were+verb-ing (I was running). Understand usage and signal words for each tense.', age: '8-11' },
      { topic: '语法：从句', zh: '学习从句(Clause)的概念和用法。主句(Main Clause)：可以独立成句。从句(Subordinate Clause)：不能独立成句，需要和主句一起才有完整意义。状语从句：When I got home（当我到家时），I was tired（我很累）。关系从句：The boy who won the race（赢得比赛的男孩）。使用从句让句子更丰富、更复杂。', en: 'Learn the concept and usage of clauses. Main clause: can stand alone as a sentence. Subordinate clause: cannot stand alone, needs a main clause for complete meaning. Adverbial clause: When I got home, I was tired. Relative clause: The boy who won the race. Use clauses to make sentences richer and more complex.', age: '9-11' },
      { topic: '拼写：前缀和后缀', zh: '学习常见的前缀和后缀。前缀（加在词首改变含义）：un-=不（unhappy不开心），re-=再（rewrite重写），dis-=否定（disagree不同意），pre-=之前（preview预习）。后缀（加在词尾改变词性）：-ness=名词（happiness幸福），-ful=形容词（beautiful美丽），-less=没有（homeless无家可归），-ment=名词（enjoyment享受），-ly=副词（quickly快速地）。', en: 'Learn common prefixes and suffixes. Prefixes (added to beginning, changing meaning): un-=not (unhappy), re-=again (rewrite), dis-=opposite (disagree), pre-=before (preview). Suffixes (added to end, changing word class): -ness=noun (happiness), -ful=adjective (beautiful), -less=without (homeless), -ment=noun (enjoyment), -ly=adverb (quickly).', age: '7-11' },
      { topic: '演讲技能', zh: '学习演讲的基本技能。准备演讲：选择主题、收集信息、组织结构（开头、主体、结尾）。写演讲稿：使用简单明了的语言，避免过长的句子。演讲技巧：声音洪亮、语速适中、与观众眼神交流、使用手势辅助表达。练习在班级面前做1-3分钟的演讲，主题可以是：我最喜欢的动物、一个重要的发明等。', en: 'Learn basic public speaking skills. Preparation: choose topic, gather information, organize structure (opening, body, conclusion). Writing: use clear language, avoid overly long sentences. Speaking techniques: speak loudly, moderate pace, eye contact with audience, use gestures. Practice 1-3 minute speeches in class on topics like: my favorite animal, an important invention.', age: '9-11' },
      { topic: '非虚构文本阅读', zh: '学习阅读非虚构文本。非虚构文本包括：说明文、新闻报道、百科全书条目、说明书等。阅读策略：浏览标题和小标题了解大意；细读获取详细信息；识别文本结构（因果、比较、时间顺序）；区分事实和观点。练习阅读并总结非虚构文本的要点。', en: 'Learn to read non-fiction texts. Non-fiction includes: explanations, news reports, encyclopedia entries, instructions. Reading strategies: scan headings for overview; read closely for details; identify text structure (cause-effect, comparison, chronological); distinguish fact from opinion. Practice reading and summarizing key points of non-fiction texts.', age: '9-11' },
      { topic: '诗歌创作和欣赏', zh: '深入学习诗歌的创作和欣赏。诗歌的要素：节奏、韵律、意象、比喻。诗歌的形式：自由诗（没有固定格式）、押韵诗（有规律的押韵模式）、俳句（5-7-5音节的日本诗体）、五行打油诗(Limerick)。欣赏经典儿童诗歌，分析诗人使用的技巧。尝试创作不同形式的诗歌。', en: 'Deepen poetry creation and appreciation. Poetry elements: rhythm, rhyme, imagery, metaphor. Poetry forms: free verse, rhyming poetry, haiku (5-7-5 syllables), limerick. Appreciate classic childrens poetry, analyzing techniques poets use. Try creating different forms of poetry.', age: '9-11' },
      { topic: '书信写作', zh: '学习正式和非正式书信的写作。非正式信件：写给朋友或家人，语言轻松随意，使用缩写（dont, cant）。正式信件：写给学校、公司或官员，语言正式礼貌，不使用缩写，格式规范（发件人地址、日期、收件人地址、称呼、正文、结尾、签名）。练习写一封投诉信和一封感谢信。', en: 'Learn formal and informal letter writing. Informal: to friends/family, casual language, contractions (dont, cant). Formal: to schools/companies/officials, polite language, no contractions, standard format (sender address, date, recipient address, salutation, body, closing, signature). Practice writing a complaint letter and a thank-you letter.', age: '8-11' },
      { topic: '说明文写作', zh: '学习写说明文(Explanation Text)。说明文解释某事如何运作或为什么发生。结构：引言（介绍要解释的事物）、步骤（按顺序解释过程）、结论（总结）。使用时间连接词：first, then, next, after that, finally。使用因果连接词：because, so, therefore, as a result。写一篇说明文：解释水循环的过程。', en: 'Learn to write explanation texts. Explanation texts explain how something works or why something happens. Structure: introduction, steps (explaining the process in order), conclusion. Use time connectives: first, then, next, after that, finally. Use causal connectives: because, so, therefore, as a result. Write an explanation: explain the water cycle process.', age: '9-11' },
      { topic: '议论文写作', zh: '学习写议论文(Argument/Persuasive Text)。议论文表达观点并说服读者。结构：引言（提出论点）、论据1（支持论点的理由）、论据2、论据3、反驳（考虑反对意见）、结论（重申论点）。使用说服性语言：I strongly believe, It is clear that, Without a doubt。练习写一篇议论文：学校是否应该禁止手机？', en: 'Learn to write argument/persuasive texts. Structure: introduction (state argument), reason 1, reason 2, reason 3, counter-argument, conclusion (restate argument). Use persuasive language: I strongly believe, It is clear that, Without a doubt. Practice writing: Should mobile phones be banned in schools?', age: '10-11' },
      { topic: '直接引语和间接引语', zh: '学习直接引语和间接引语的转换。直接引语：He said, "I am hungry." 间接引语：He said that he was hungry。转换规则：去掉引号，加that连接；人称变化（I→he/she）；时态后退（am→was, is→was, will→would, can→could）；时间和地点词变化（today→that day, here→there）。练习将对话改写为间接引语。', en: 'Learn to convert between direct and indirect speech. Direct: He said, "I am hungry." Indirect: He said that he was hungry. Rules: remove quotation marks, add "that"; change pronouns (I→he/she); backshift tenses (am→was, is→was, will→would, can→could); change time/place words (today→that day, here→there). Practice converting dialogue to indirect speech.', age: '9-11' },
      { topic: '主动语态和被动语态', zh: '学习主动语态和被动语态。主动：The dog chased the cat.（狗追了猫）被动：The cat was chased by the dog.（猫被狗追了）。被动语态结构：be+过去分词。使用被动语态的场合：强调动作承受者时、不知道或不需要说明动作执行者时。The painting was stolen in 1990.（画在1990年被盗——不知道谁偷的）。', en: 'Learn active and passive voice. Active: The dog chased the cat. Passive: The cat was chased by the dog. Passive structure: be + past participle. Use passive voice when: emphasizing the receiver, when the doer is unknown or unnecessary. The painting was stolen in 1990.', age: '10-11' },
      { topic: '比较和对比', zh: '学习比较和对比的写作技巧。比较(Compare)：找出相似之处。对比(Contrast)：找出不同之处。使用比较连接词：similarly, likewise, in the same way, both。使用对比连接词：however, on the other hand, in contrast, whereas, while。练习写一段比较和对比的文字：比较城市生活和乡村生活。', en: 'Learn comparison and contrast writing techniques. Compare: find similarities. Contrast: find differences. Use comparison connectives: similarly, likewise, in the same way, both. Use contrast connectives: however, on the other hand, in contrast, whereas, while. Practice writing a comparison and contrast paragraph: compare city life and country life.', age: '9-11' },
      { topic: '字典和词典技能', zh: '提高使用字典和词典的技能。字典查找：按字母顺序查找单词，阅读释义、词性标注、例句和发音指南。同义词词典(Thesaurus)：查找同义词和反义词，丰富写作词汇。了解字典中的缩写：n.=noun, v.=verb, adj.=adjective, adv.=adverb。使用在线字典和词典。', en: 'Improve dictionary and thesaurus skills. Dictionary lookup: find words alphabetically, read definitions, word class labels, example sentences, and pronunciation guides. Thesaurus: find synonyms and antonyms, enriching writing vocabulary. Understand dictionary abbreviations: n.=noun, v.=verb, adj.=adjective, adv.=adverb. Use online dictionaries and thesauruses.', age: '7-11' },
      { topic: '经典文学入门', zh: '开始阅读经典文学作品的简化版。了解一些著名作家和作品：罗尔德·达尔的《查理和巧克力工厂》、C.S.刘易斯的《纳尼亚传奇》、J.K.罗琳的《哈利·波特》。讨论故事的主题、人物性格和情节发展。学习区分主角和配角，理解人物的动机和变化。培养终身阅读的习惯。', en: 'Begin reading simplified versions of classic literature. Learn about famous authors and works: Roald Dahls "Charlie and the Chocolate Factory," C.S. Lewiss "The Chronicles of Narnia," J.K. Rowlings "Harry Potter." Discuss themes, character personalities, and plot development. Learn to distinguish protagonists and supporting characters, understanding motivations and changes. Develop lifelong reading habits.', age: '9-11' },
      { topic: '戏剧和角色扮演', zh: '学习戏剧和角色扮演。阅读简单的剧本，了解剧本的格式：角色名、台词、舞台指示。在小组中表演短剧，练习：大声清楚地念台词、用表情和动作表现角色、配合其他演员。即兴表演：给定一个情境，不准备台词即兴表演。戏剧培养自信心、表达能力和团队合作。', en: 'Learn drama and role-play. Read simple scripts, understanding format: character names, dialogue, stage directions. Perform short plays in groups, practicing: speaking lines clearly, using expressions and actions, cooperating with other actors. Improvisation: given a scenario, perform without prepared lines. Drama builds confidence, expression skills, and teamwork.', age: '8-11' },
      { topic: '标点符号进阶', zh: '学习更复杂的标点符号用法。冒号(:)：引出列表或解释。分号(;)：连接两个相关的独立句子。破折号(—)：表示停顿或补充说明。括号(())：添加额外信息。单引号( )：引用中的引用。省略号(...)：表示省略或停顿。在写作中正确使用各种标点符号，使文章更清晰。', en: 'Learn more complex punctuation usage. Colon (:): introducing lists or explanations. Semicolon (;): connecting two related independent sentences. Dash (—): indicating pause or additional information. Parentheses (()): adding extra information. Single quotes: quotes within quotes. Ellipsis (...): indicating omission or pause. Use various punctuation correctly in writing for clarity.', age: '9-11' },
      { topic: '词汇扩展', zh: '系统扩展英语词汇量。学习用词根词缀推测词义：tele-=远（telephone电话, television电视），-ology=学科（biology生物学, geology地质学）。学习同义词替换：good→excellent/outstanding/superb, bad→terrible/awful/dreadful, said→exclaimed/whispered/shouted。建立个人词汇本，每天学习5个新词。', en: 'Systematically expand English vocabulary. Learn to deduce word meanings from roots and affixes: tele-=distant (telephone, television), -ology=study of (biology, geology). Learn synonym replacement: good→excellent/outstanding/superb, bad→terrible/awful/dreadful, said→exclaimed/whispered/shouted. Build a personal vocabulary book, learning 5 new words daily.', age: '9-11' },
      { topic: '写作修改和编辑', zh: '学习修改和编辑自己的写作。修改步骤：1.内容检查——观点是否清楚？论据是否充分？2.结构检查——段落是否合理？过渡是否自然？3.语言检查——用词是否准确？句子是否通顺？4.拼写和标点检查——有没有拼写错误？标点是否正确？好文章是改出来的，至少修改两遍。', en: 'Learn to revise and edit your own writing. Revision steps: 1. Content check — are ideas clear? Are arguments sufficient? 2. Structure check — are paragraphs logical? Are transitions natural? 3. Language check — are word choices accurate? Are sentences fluent? 4. Spelling and punctuation check — any errors? Good writing comes from revision; revise at least twice.', age: '9-11' }
    ],

    science: [
      { topic: '电路和导体', zh: '深入学习电路的知识。串联电路：元件依次连接，一个灯泡坏了全部不亮。并联电路：元件并排连接，一个灯泡坏了其他还亮。导体：容易让电流通过的材料（铜、铝、铁等金属）。绝缘体：不容易让电流通过的材料（塑料、橡胶、玻璃、木头）。了解开关的原理——断开导体使电路断路。设计并制作一个简单的手电筒。', en: 'Deepen knowledge of circuits. Series circuit: components connected in sequence, one bulb breaks all go off. Parallel circuit: components connected side by side, one breaks others stay on. Conductors: materials that let electricity flow easily (copper, aluminum, iron). Insulators: materials that resist electricity (plastic, rubber, glass, wood). Understand switch principles. Design and build a simple flashlight.', age: '7-9' },
      { topic: '力与运动', zh: '深入学习力与运动的关系。牛顿第一定律：没有力的作用，静止的物体保持静止，运动的物体保持匀速直线运动。力改变物体的运动状态。摩擦力：固体摩擦（推箱子）、流体摩擦（空气阻力、水的阻力）。减少摩擦力的方法：润滑、轮子、流线型设计。增加摩擦力的方法：粗糙表面、刹车片。了解空气阻力——降落伞利用空气阻力减慢下落速度。', en: 'Deepen understanding of forces and motion. Newtons first law: without force, objects at rest stay at rest, moving objects maintain uniform motion. Forces change motion states. Friction: solid friction, fluid friction (air resistance, water resistance). Reducing friction: lubrication, wheels, streamlined design. Increasing friction: rough surfaces, brake pads. Air resistance — parachutes use it to slow descent.', age: '9-11' },
      { topic: '物质状态变化', zh: '深入学习物质状态变化的微观解释。固态：分子排列紧密、振动微小、有固定形状。液态：分子间距稍大、可以流动、无固定形状。气态：分子间距很大、自由运动、充满容器。融化：固→液（吸热）。凝固：液→固（放热）。蒸发：液→气（吸热）。凝结：气→液（放热）。升华：固→气（如干冰）。了解温度是分子运动快慢的量度。', en: 'Deepen microscopic understanding of state changes. Solid: tightly packed molecules, slight vibration, fixed shape. Liquid: slightly larger spacing, can flow, no fixed shape. Gas: large spacing, free movement, fills container. Melting: solid→liquid (absorbs heat). Freezing: liquid→solid (releases heat). Evaporation: liquid→gas (absorbs heat). Condensation: gas→liquid (releases heat). Sublimation: solid→gas (like dry ice). Temperature measures molecular motion speed.', age: '9-11' },
      { topic: '生命循环', zh: '深入学习动植物的生命循环。植物的生命循环：种子→发芽→生长→开花→传粉→结果→种子。动物的繁殖方式：有性繁殖（需要雌雄交配）和无性繁殖（如水螅的出芽生殖）。昆虫的完全变态：卵→幼虫→蛹→成虫（蝴蝶、蜜蜂）。不完全变态：卵→若虫→成虫（蝗虫、蜻蜓）。哺乳动物：胚胎在母体内发育，出生后哺乳。', en: 'Deepen understanding of plant and animal life cycles. Plant life cycle: seed → germination → growth → flowering → pollination → fruiting → seed. Animal reproduction: sexual (requiring mating) and asexual (like hydra budding). Insect complete metamorphosis: egg → larva → pupa → adult (butterflies, bees). Incomplete metamorphosis: egg → nymph → adult (grasshoppers, dragonflies). Mammals: embryo develops inside mother, nursed after birth.', age: '7-9' },
      { topic: '进化论初步', zh: '初步了解进化论的概念。查尔斯·达尔文提出了自然选择理论：在同一物种中，个体之间存在差异；适应环境的个体更容易生存和繁殖；不适应的个体容易被淘汰。长颈鹿的脖子为什么那么长？短脖子的个体吃不到高处的叶子，在食物短缺时容易饿死，长脖子的个体存活下来并繁殖后代。经过很多代，长颈鹿的脖子越来越长。', en: 'Introduction to evolution concepts. Charles Darwin proposed natural selection: individuals within a species vary; those better adapted to their environment survive and reproduce more successfully; less adapted individuals are eliminated. Why are giraffes necks so long? Short-necked individuals could not reach high leaves, starving during food shortages, while long-necked ones survived and reproduced. Over many generations, giraffe necks grew longer.', age: '10-11' },
      { topic: '地球和太空', zh: '深入学习地球和太空的知识。地球的结构：地壳（薄薄的外层）、地幔（厚厚的中间层）、地核（最内层，温度极高）。板块构造：地球表面由多块板块组成，板块移动导致地震和火山。太阳系：太阳、八大行星、矮行星、小行星、彗星。日食：月球挡住太阳光。月相变化：月球绕地球运行，反射太阳光的角度不同形成不同的月相。', en: 'Deepen knowledge of Earth and space. Earths structure: crust (thin outer layer), mantle (thick middle layer), core (innermost, extremely hot). Plate tectonics: Earths surface consists of plates whose movement causes earthquakes and volcanoes. Solar system: Sun, eight planets, dwarf planets, asteroids, comets. Solar eclipse: Moon blocks sunlight. Moon phases: the Moon orbits Earth, reflecting sunlight at different angles creating different phases.', age: '9-11' },
      { topic: '光和影', zh: '深入学习光和影的科学。光的反射：光射到物体表面会反弹回来。镜面反射：光滑表面（镜子）产生清晰的反射像。漫反射：粗糙表面向各方向反射光。光的折射：光从一种介质进入另一种介质时方向发生偏折——水中的筷子看起来弯曲。白光由七种颜色组成：红橙黄绿蓝靛紫。三棱镜可以将白光分解成七色光。', en: 'Deepen science of light and shadows. Reflection: light bounces off surfaces. Specular reflection: smooth surfaces (mirrors) produce clear reflected images. Diffuse reflection: rough surfaces scatter light in all directions. Refraction: light changes direction when passing from one medium to another — chopsticks in water appear bent. White light consists of seven colors: red, orange, yellow, green, blue, indigo, violet. A prism separates white light into its spectrum.', age: '9-11' },
      { topic: '声音传播', zh: '深入学习声音的传播。声音以波的形式传播——声波。声波需要介质：固体、液体或气体。声速：空气中约340m/s，水中约1500m/s，钢铁中约5000m/s。音调(Pitch)：由频率决定，频率越高音调越高。响度(Volume)：由振幅决定，振幅越大响度越大。音色(Timbre)：不同乐器演奏同一个音符听起来不同，因为音色不同。人耳可听频率范围：20Hz-20000Hz。', en: 'Deepen understanding of sound propagation. Sound travels as waves — sound waves. Sound waves need a medium: solid, liquid, or gas. Speed of sound: ~340m/s in air, ~1500m/s in water, ~5000m/s in steel. Pitch: determined by frequency, higher frequency=higher pitch. Volume: determined by amplitude, larger amplitude=louder. Timbre: different instruments playing the same note sound different due to timbre. Human hearing range: 20Hz-20000Hz.', age: '9-11' },
      { topic: '消化系统', zh: '学习人体的消化系统。消化的过程：口腔（牙齿咀嚼、唾液分解淀粉）→食道（将食物推入胃）→胃（胃酸和酶分解蛋白质）→小肠（进一步消化、吸收营养）→大肠（吸收水分）→直肠→肛门。小肠是最主要的吸收器官，内壁有绒毛增大吸收面积。肝脏分泌胆汁帮助消化脂肪。胰腺分泌胰岛素调节血糖。', en: 'Learn the human digestive system. Digestion process: mouth (teeth chew, saliva breaks down starch) → esophagus (pushes food to stomach) → stomach (acid and enzymes break down proteins) → small intestine (further digestion, nutrient absorption) → large intestine (water absorption) → rectum → anus. The small intestine is the main absorption organ, with villi increasing surface area. The liver produces bile for fat digestion. The pancreas produces insulin for blood sugar regulation.', age: '9-11' },
      { topic: '循环系统', zh: '学习人体的循环系统。心脏是循环系统的泵，分为四个腔：左心房、左心室、右心房、右心室。血液循环路线：体循环（左心室→全身→右心房）和肺循环（右心室→肺部→左心房）。动脉将血液从心脏输送到全身，静脉将血液从全身送回心脏。毛细血管连接动脉和静脉，是物质交换的场所。血液成分：红细胞（运输氧气）、白细胞（免疫防御）、血小板（止血）、血浆（运输营养和废物）。', en: 'Learn the human circulatory system. The heart has four chambers: left atrium, left ventricle, right atrium, right ventricle. Circulation routes: systemic (left ventricle → body → right atrium) and pulmonary (right ventricle → lungs → left atrium). Arteries carry blood from heart to body, veins return blood to heart. Capillaries connect arteries and veins for material exchange. Blood components: red blood cells (carry oxygen), white blood cells (immune defense), platelets (clotting), plasma (transports nutrients and waste).', age: '10-11' },
      { topic: '植物的光合作用', zh: '深入学习植物的光合作用。光合作用方程式：二氧化碳+水→葡萄糖+氧气（需要光能和叶绿素）。光合作用在叶子的叶绿体中进行。叶子结构适应光合作用：扁平的叶片增大受光面积，气孔允许二氧化碳进入和氧气排出，叶脉运输水分和养分。光合作用的重要性：制造有机物（食物链的基础）、释放氧气（维持大气成分）。', en: 'Deepen understanding of photosynthesis. Equation: carbon dioxide + water → glucose + oxygen (requiring light energy and chlorophyll). Photosynthesis occurs in leaf chloroplasts. Leaf structure adapts for photosynthesis: flat blades maximize light exposure, stomata allow CO2 entry and O2 exit, veins transport water and nutrients. Importance: produces organic matter (foundation of food chains), releases oxygen (maintaining atmospheric composition).', age: '9-11' },
      { topic: '岩石和化石', zh: '深入学习岩石和化石。化石是保存在岩石中的古代生物遗迹或痕迹。化石形成条件：生物遗体被沉积物迅速掩埋，经过漫长地质年代矿化形成。化石告诉我们：古代存在什么生物、环境如何变化、物种如何演化。地质年代：古生代（三叶虫等）、中生代（恐龙时代）、新生代（哺乳动物时代）。', en: 'Deepen knowledge of rocks and fossils. Fossils are preserved remains of ancient organisms in rocks. Formation: organisms rapidly buried by sediment, mineralized over geological time. Fossils reveal: ancient organisms, environmental changes, species evolution. Geological eras: Paleozoic (trilobites), Mesozoic (dinosaurs), Cenozoic (mammals).', age: '9-11' },
      { topic: '呼吸系统', zh: '学习人体的呼吸系统。呼吸过程：鼻腔→咽→喉→气管→支气管→肺。肺泡是气体交换的场所：氧气进入血液，二氧化碳排出体外。呼吸运动：吸气时横膈膜收缩下降、胸腔扩大；呼气时横膈膜放松上升、胸腔缩小。了解吸烟对呼吸系统的危害。', en: 'Learn the human respiratory system. Breathing process: nasal cavity → pharynx → larynx → trachea → bronchi → lungs. Alveoli: gas exchange sites. Breathing mechanics: inhaling — diaphragm contracts, chest expands; exhaling — diaphragm relaxes, chest shrinks. Understand smoking hazards to the respiratory system.', age: '9-11' },
      { topic: '微生物', zh: '学习微生物的知识。微生物包括：细菌、病毒、真菌。有益微生物：肠道细菌帮助消化、酵母菌制作面包、青霉菌产生青霉素。有害微生物：致病细菌引起食物中毒，病毒引起感冒和流感。防止传播：勤洗手、食物充分加热。抗生素只对细菌有效，对病毒无效。', en: 'Learn about microorganisms. Types: bacteria, viruses, fungi. Beneficial: gut bacteria aid digestion, yeast makes bread, Penicillium produces penicillin. Harmful: pathogenic bacteria cause food poisoning, viruses cause colds and flu. Prevention: wash hands, cook food thoroughly. Antibiotics only work on bacteria, not viruses.', age: '9-11' },
      { topic: '食物网', zh: '学习食物网的概念。食物网由多条相互关联的食物链组成。生产者→初级消费者→次级消费者→顶级消费者。分解者分解死亡的生物，将营养归还土壤。能量在食物链中逐级递减——只有约10%传递到下一级。了解人类活动对食物网的影响。', en: 'Learn about food webs. Multiple interconnected food chains. Producers → primary consumers → secondary consumers → top consumers. Decomposers return nutrients to soil. Energy decreases at each level — only about 10% transfers. Understand human impacts on food webs.', age: '9-11' },
      { topic: '电和电磁', zh: '学习电和电磁的知识。电磁铁：电流通过线圈产生磁场。增加线圈匝数或增大电流可增强磁力。应用：电铃、电磁起重机、电动机。电动机：通电线圈在磁场中转动。发电机：线圈在磁场中转动产生电流。发电站：燃烧燃料或核能产生蒸汽推动涡轮机带动发电机。', en: 'Learn about electricity and electromagnetism. Electromagnets: current through coil creates magnetic field. More turns or stronger current increases force. Applications: bells, cranes, motors. Motors: current-carrying coil rotates in magnetic field. Generators: rotating coil in magnetic field produces current. Power stations: fuel or nuclear energy creates steam driving turbines.', age: '10-11' },
      { topic: '分离混合物', zh: '学习分离混合物的方法。过滤：分离不溶性固体和液体。蒸发：从溶液中获取溶质。蒸馏：分离不同沸点的液体。色谱法：分离混合物中的色素。磁选：用磁铁分离磁性物质。选择合适的分离方法取决于混合物的性质。', en: 'Learn methods of separating mixtures. Filtration: insoluble solids from liquids. Evaporation: solute from solution. Distillation: liquids with different boiling points. Chromatography: separating pigments. Magnetic separation: magnetic from non-magnetic materials. Choose methods based on mixture properties.', age: '9-11' },
      { topic: '骨骼和肌肉系统', zh: '学习人体的骨骼和肌肉系统。成人有206块骨头。骨骼功能：支撑身体、保护器官、储存矿物质、制造血细胞。关节类型：铰链关节（肘、膝）、球窝关节（肩、髋）。肌肉与骨骼协作：肌肉收缩拉动骨骼产生运动。拮抗肌：一组收缩时另一组放松。', en: 'Learn skeletal and muscular systems. Adults have 206 bones. Functions: support, protect organs, store minerals, produce blood cells. Joint types: hinge (elbow, knee), ball-and-socket (shoulder, hip). Muscles and bones cooperate: muscle contraction pulls bones. Antagonistic muscles work in pairs.', age: '9-11' },
      { topic: '科学调查方法', zh: '学习科学调查的完整方法。步骤：1.提出问题 2.做出假设 3.设计实验（控制变量：自变量、因变量、控制变量）4.收集数据 5.分析结果 6.得出结论 7.评估实验。公平测试：只改变一个变量，其他条件保持相同。使用表格和图表展示数据。', en: 'Learn complete scientific investigation method. Steps: 1. Ask question 2. Hypothesize 3. Design experiment (control variables) 4. Collect data 5. Analyze 6. Conclude 7. Evaluate. Fair test: change only one variable. Use tables and charts to present data.', age: '9-11' }
    ],

    history: [
      { topic: '古罗马文明', zh: '学习古罗马文明。罗马帝国从公元前27年持续到公元476年。罗马人的贡献：法律体系、道路建设、拉丁语、混凝土和拱形建筑。罗马社会：元老院、角斗士比赛。罗马军队是最强大的军事力量。了解罗马对欧洲的深远影响。', en: 'Learn about Ancient Rome. Empire from 27 BC to 476 AD. Contributions: legal system, roads, Latin, concrete and arches. Society: Senate, gladiator games. Roman army was the strongest military. Understand Romes profound influence on Europe.', age: '7-9' },
      { topic: '维京人', zh: '学习维京人的历史。来自斯堪的纳维亚，约793-1066年活跃。出色的航海家和战士，使用龙头船远航。不仅是掠夺者，也是商人、农民和探险家——到达冰岛、格陵兰甚至北美洲。信仰北欧神话（奥丁、托尔），使用如尼文字。', en: 'Learn about Vikings. From Scandinavia, active 793-1066. Excellent seafarers and warriors using dragon-headed longships. Not just raiders but traders, farmers, explorers — reaching Iceland, Greenland, even North America. Believed in Norse mythology (Odin, Thor), used runic writing.', age: '7-9' },
      { topic: '都铎王朝', zh: '学习英国都铎王朝(1485-1603)。亨利八世与罗马教廷决裂，创立英国国教。伊丽莎白一世的"黄金时代"：击败西班牙无敌舰队、莎士比亚创作戏剧、海外探险。了解都铎时期的社会生活和王朝对英国国家认同的塑造。', en: 'Learn about the Tudor period (1485-1603). Henry VIII broke with Rome, establishing Church of England. Elizabeth Is "Golden Age": defeating Spanish Armada, Shakespeares plays, overseas exploration. Understand Tudor social life and national identity formation.', age: '9-11' },
      { topic: '工业革命', zh: '学习英国工业革命(1760-1840)。关键发明：瓦特改良蒸汽机、珍妮纺纱机、蒸汽火车。生产从手工转向机器，从家庭转向工厂。社会影响：人口迁移到城市、工人条件恶劣、环境污染。正面影响：生产力提高、交通改善、生活水平逐渐上升。', en: 'Learn about the Industrial Revolution (1760-1840). Key inventions: Watts steam engine, spinning jenny, steam locomotive. Production shifted from handcraft to machines. Social impacts: urbanization, poor working conditions, pollution. Positive: increased productivity, improved transport, rising living standards.', age: '9-11' },
      { topic: '第二次世界大战', zh: '学习二战(1939-1945)。起因：纳粹德国侵略邻国。阵营：同盟国vs轴心国。关键事件：敦刻尔克大撤退、不列颠空战、诺曼底登陆。对平民的影响：大屠杀、城市轰炸、食物配给、儿童疏散。了解二战的教训和联合国成立的意义。', en: 'Learn about WWII (1939-1945). Causes: Nazi aggression. Sides: Allies vs Axis. Key events: Dunkirk, Battle of Britain, D-Day. Civilian impact: Holocaust, bombing, rationing, child evacuation. Understand WWII lessons and UN founding.', age: '9-11' },
      { topic: '古希腊文明', zh: '学习古希腊文明。民主：雅典发明直接民主制。哲学：苏格拉底、柏拉图、亚里士多德。奥运会：公元前776年首次举办。神话：宙斯、雅典娜等。希腊字母在数学和科学中使用。', en: 'Learn about Ancient Greece. Democracy: Athens invented direct democracy. Philosophy: Socrates, Plato, Aristotle. Olympics: first held 776 BC. Mythology: Zeus, Athena. Greek letters used in math and science.', age: '7-9' },
      { topic: '古埃及文明', zh: '学习古埃及文明。尼罗河是生命线。金字塔：法老陵墓，胡夫金字塔用约230万块石头。木乃伊：保存遗体以待来世。象形文字：罗塞塔石碑帮助破解。发明：纸莎草纸、日历。', en: 'Learn about Ancient Egypt. Nile was the lifeline. Pyramids: pharaohs tombs, Great Pyramid used ~2.3 million stones. Mummies: preserving bodies for afterlife. Hieroglyphics: decoded via Rosetta Stone. Inventions: papyrus, calendar.', age: '7-9' },
      { topic: '盎格鲁-撒克逊和诺曼征服', zh: '学习盎格鲁-撒克逊时期(410-1066)和诺曼征服。日耳曼部落迁入不列颠建立七国。1066年，征服者威廉在黑斯廷斯战役中击败哈罗德。诺曼征服的影响：引入封建制度、建造城堡、法语影响英语。贝叶挂毯记录了战役过程。', en: 'Learn about Anglo-Saxons (410-1066) and Norman Conquest. Germanic tribes established seven kingdoms. 1066: William the Conqueror defeated Harold at Hastings. Impacts: feudalism, castles, French influenced English. Bayeux Tapestry records the battle.', age: '9-11' },
      { topic: '大航海时代', zh: '学习大航海时代(15-17世纪)。欧洲人寻找通往亚洲的新航路。达·伽马到达印度，哥伦布到达美洲，麦哲伦环球航行。影响：全球贸易网络建立、哥伦布大交换、殖民主义开始。了解这一时期对全球化的推动。', en: 'Learn about Age of Exploration (15th-17th centuries). Europeans sought new routes to Asia. Da Gama reached India, Columbus reached Americas, Magellan circumnavigated. Impacts: global trade, Columbian Exchange, colonialism began.', age: '9-11' },
      { topic: '法国大革命', zh: '学习法国大革命(1789-1799)。起因：社会不平等、财政危机、启蒙思想。1789年7月14日攻占巴士底狱。《人权宣言》宣布自由平等。恐怖统治时期大量人被处决。拿破仑崛起。法国大革命影响了全世界的民主运动。', en: 'Learn about French Revolution (1789-1799). Causes: inequality, financial crisis, Enlightenment ideas. July 14, 1789: Bastille stormed. Declaration of Rights of Man. Reign of Terror. Napoleon rose. Influenced democratic movements worldwide.', age: '10-11' },
      { topic: '维多利亚时代', zh: '学习维多利亚时代(1837-1901)。大英帝国最强盛时期。工业革命深入发展、铁路网遍布、电报发明。贫富差距巨大。1870年教育法案通过后儿童才普遍接受教育。', en: 'Learn about Victorian era (1837-1901). British Empire at its peak. Industrial Revolution deepened, railways spread, telegraph invented. Huge wealth gap. Universal education only after 1870 Education Act.', age: '9-11' },
      { topic: '第一次世界大战', zh: '学习一战(1914-1918)。起因：帝国主义竞争、联盟体系、萨拉热窝事件。新式武器：机关枪、毒气、坦克。堑壕战条件极其恶劣。约2000万人死亡。影响：帝国崩溃、国际联盟成立。', en: 'Learn about WWI (1914-1918). Causes: imperialist competition, alliances, Sarajevo assassination. New weapons: machine guns, gas, tanks. Terrible trench conditions. ~20 million dead. Impacts: empires collapsed, League of Nations formed.', age: '10-11' },
      { topic: '民权运动', zh: '学习民权运动。马丁·路德·金争取黑人平等权利。纳尔逊·曼德拉反对种族隔离。妇女争取投票权。平等权利是通过斗争争取的。', en: 'Learn about civil rights movements. MLK fought for Black equality. Mandela opposed apartheid. Women fought for voting rights. Equal rights were won through struggle.', age: '10-11' },
      { topic: '丝绸之路', zh: '学习丝绸之路。连接中国和欧洲的古代贸易路线。交换货物：中国丝绸、茶叶、瓷器；欧洲玻璃、黄金。文化交流：佛教、伊斯兰教传播，造纸术传入欧洲。了解早期全球化。', en: 'Learn about the Silk Road. Ancient trade routes connecting China and Europe. Goods: Chinese silk, tea, porcelain; European glass, gold. Cultural exchange: Buddhism, Islam spread, papermaking reached Europe. Early globalization.', age: '9-11' },
      { topic: '欧洲联盟', zh: '学习欧盟的历史。1951年欧洲煤钢共同体，1957年罗马条约，1993年欧盟正式成立，2002年欧元流通。宗旨：促进和平、经济一体化、公民自由流动。讨论脱欧和欧盟挑战。', en: 'Learn about the EU. 1951 Coal and Steel Community, 1957 Treaty of Rome, 1993 EU formed, 2002 Euro circulated. Aims: peace, economic integration, free movement. Discuss Brexit and EU challenges.', age: '10-11' },
      { topic: '黑死病', zh: '学习14世纪黑死病。1347-1351年鼠疫从亚洲传播到欧洲，约三分之一人口死亡。影响：劳动力短缺、工资上涨、封建制度动摇、医学意识提高。了解瘟疫对欧洲社会的深远影响。', en: 'Learn about the Black Death. 1347-1351 plague from Asia killed ~1/3 of Europes population. Impacts: labor shortage, rising wages, feudal system weakened, medical awareness improved.', age: '9-11' },
      { topic: '阿兹特克文明', zh: '学习阿兹特克文明。位于今墨西哥，首都特诺奇蒂特兰建在湖上。建造金字塔神庙，发展历法和文字。浮岛农业。1521年西班牙征服者摧毁了阿兹特克帝国。了解殖民对美洲文明的破坏。', en: 'Learn about Aztec civilization. In modern Mexico, capital Tenochtitlan on a lake. Built pyramids, developed calendars and writing. Floating gardens. 1521: Spanish conquistadors destroyed the empire. Understand colonial destruction of American civilizations.', age: '9-11' },
      { topic: '历史中的女性', zh: '学习历史上杰出女性的故事。埃及艳后克利奥帕特拉、圣女贞德、玛丽·居里、马拉拉。了解女性在历史上面临的限制以及她们如何突破障碍。', en: 'Learn about remarkable women in history. Cleopatra, Joan of Arc, Marie Curie, Malala. Understand constraints women faced and how they overcame barriers.', age: '9-11' },
      { topic: '医学发展史', zh: '学习医学发展。希波克拉底提出疾病有自然原因。巴斯德证明细菌致病，李斯特推广手术消毒。弗莱明发现青霉素。现代：基因治疗、器官移植、疫苗研发。科学方法推动医学进步。', en: 'Learn about medical history. Hippocrates: natural causes of disease. Pasteur: germ theory, Lister: surgical antisepsis. Fleming: penicillin. Modern: gene therapy, organ transplants, vaccines. Scientific methods advanced medicine.', age: '9-11' },
      { topic: '历史年表和时期', zh: '系统学习历史时期划分。史前（前3000年以前）、古代（前3000-476年）、中世纪（476-1453年）、近代早期（1453-1789年）、近代（1789-1914年）、现代（1914年至今）。了解各时期特征和转折点。', en: 'Systematically learn historical periods. Prehistoric (before 3000 BC), Ancient (3000 BC-476 AD), Medieval (476-1453), Early Modern (1453-1789), Modern (1789-1914), Contemporary (1914-present). Understand characteristics and turning points.', age: '9-11' }
    ],

    geography: [
      { topic: '欧洲地理', zh: '深入学习欧洲地理。面积约1018万平方公里。主要半岛：斯堪的纳维亚、伊比利亚、亚平宁、巴尔干。主要山脉：阿尔卑斯山、比利牛斯山。主要河流：多瑙河（流经10国）、莱茵河、伏尔加河。海岸线曲折，多优良港湾。', en: 'Deepen European geography. ~10.18 million km². Peninsulas: Scandinavian, Iberian, Italian, Balkan. Mountains: Alps, Pyrenees. Rivers: Danube (10 countries), Rhine, Volga. Rugged coastline with excellent harbors.', age: '9-11' },
      { topic: '河流和山脉', zh: '学习世界主要河流和山脉。河流：尼罗河（最长）、亚马逊河（流量最大）、多瑙河（流经最多国家）。山脉：喜马拉雅山（最高）、安第斯山（最长）、阿尔卑斯山。了解河流和山脉对人类活动的影响。', en: 'Learn major rivers and mountains. Rivers: Nile (longest), Amazon (largest flow), Danube (most countries). Mountains: Himalayas (highest), Andes (longest), Alps. Understand how rivers and mountains influence human activities.', age: '9-11' },
      { topic: '气候变化', zh: '学习气候变化。温室效应：温室气体保持地球温暖。人类活动增加温室气体。全球变暖影响：冰川融化、海平面上升、极端天气增多。应对措施：减少碳排放、发展可再生能源、植树造林。了解《巴黎协定》。', en: 'Learn about climate change. Greenhouse effect: gases trap heat. Human activities increase greenhouse gases. Impacts: melting glaciers, rising sea levels, extreme weather. Solutions: reduce emissions, renewable energy, plant trees. Understand Paris Agreement.', age: '9-11' },
      { topic: '人口和城市', zh: '学习人口和城市地理。世界人口约80亿，分布不均匀。城市化：越来越多人迁移到城市。大城市问题：住房紧张、交通拥堵、污染。欧洲主要城市：伦敦、巴黎、柏林、罗马。', en: 'Learn population and urban geography. World population ~8 billion, unevenly distributed. Urbanization: more people moving to cities. Big city challenges: housing, traffic, pollution. Major European cities: London, Paris, Berlin, Rome.', age: '9-11' },
      { topic: '地震和火山', zh: '学习地震和火山。板块构造：地球表面由多块板块组成。板块边界：汇聚、分离、转换。地震：板块突然滑动释放能量。火山：岩浆从地壳裂缝喷出。环太平洋火山带集中了75%的火山。了解防灾知识。', en: 'Learn about earthquakes and volcanoes. Plate tectonics: Earths surface consists of plates. Boundaries: convergent, divergent, transform. Earthquakes: sudden plate movement. Volcanoes: magma erupts through cracks. Pacific Ring of Fire has 75% of volcanoes. Learn disaster preparedness.', age: '9-11' },
      { topic: '生态系统', zh: '学习世界主要生态系统。热带雨林：生物多样性最丰富。沙漠：干旱少雨。草原：适合放牧。温带森林：四季分明。苔原：寒冷。海洋：覆盖地球70%。了解人类活动对生态系统的威胁。', en: 'Learn major ecosystems. Tropical rainforest: most biodiverse. Desert: arid. Grassland: grazing. Temperate forest: four seasons. Tundra: cold. Ocean: covers 70%. Understand human threats to ecosystems.', age: '9-11' },
      { topic: '地图技能进阶', zh: '提高地图技能。比例尺：1:50000表示图上1cm=实际500m。等高线：连接相同海拔的线，越密坡越陡。经纬度确定位置。时区：24个时区，15°经度差1小时。使用六位格网坐标精确定位。', en: 'Improve map skills. Scale: 1:50000 means 1cm=500m. Contour lines: equal elevation, closer=steeper. Latitude/longitude for location. Time zones: 24 zones, 15°=1 hour. Use six-figure grid references.', age: '9-11' },
      { topic: '水资源', zh: '学习水资源。全球淡水：冰川68.7%、地下水30.1%、地表水1.2%。中东和北非最缺水。水资源冲突：多国共享河流可能引发争端。可持续管理：节水灌溉、海水淡化、雨水收集。', en: 'Learn about water resources. Freshwater: glaciers 68.7%, groundwater 30.1%, surface 1.2%. Middle East/North Africa most water-scarce. Conflicts: shared rivers. Sustainable management: efficient irrigation, desalination, rainwater harvesting.', age: '9-11' },
      { topic: '贸易和全球化', zh: '学习贸易和全球化。国际贸易：国家间交换商品和服务。出口和进口。欧盟单一市场。全球化使世界经济文化日益紧密。公平贸易确保发展中国家生产者获得合理报酬。了解全球化利弊。', en: 'Learn about trade and globalization. International trade: exchanging goods and services. Exports and imports. EU single market. Globalization connects economies and cultures. Fair Trade ensures fair compensation. Understand pros and cons.', age: '10-11' },
      { topic: '能源资源', zh: '学习能源资源。不可再生：化石燃料（有限、污染）、核能（高效但有风险）。可再生：太阳能、风能、水力、地热。欧洲政策：减少碳排放、增加可再生能源比例。了解能源选择的环境和经济权衡。', en: 'Learn about energy resources. Non-renewable: fossil fuels (limited, polluting), nuclear (efficient but risky). Renewable: solar, wind, hydro, geothermal. European policy: reduce emissions, increase renewables. Understand environmental and economic trade-offs.', age: '10-11' },
      { topic: '非洲地理', zh: '学习非洲地理。世界第二大洲。撒哈拉沙漠：最大热沙漠。东非大裂谷。尼罗河、刚果河。乞力马扎罗山。54个国家，发展中国家最集中。挑战：贫困、疾病、气候变化。', en: 'Learn about African geography. Second-largest continent. Sahara: largest hot desert. East African Rift. Nile, Congo rivers. Kilimanjaro. 54 countries, most concentrated developing nations. Challenges: poverty, disease, climate change.', age: '9-11' },
      { topic: '亚洲地理', zh: '学习亚洲地理。世界最大洲，4458万平方公里。喜马拉雅山最高，珠穆朗玛峰8848米。人口约47亿，占世界60%。区域：东亚、东南亚、南亚、西亚、中亚。了解亚洲的多样性和快速发展。', en: 'Learn about Asian geography. Largest continent, 44.58 million km². Himalayas highest, Everest 8848m. Population ~4.7 billion, 60% of world. Regions: East, Southeast, South, West, Central Asia. Understand diversity and rapid development.', age: '9-11' },
      { topic: '沿海和海洋', zh: '学习沿海和海洋地理。海岸侵蚀形成海蚀洞、拱门、海蚀柱。潮汐由月球和太阳引力引起。洋流影响气候（墨西哥湾暖流使西欧温暖）。海洋污染：塑料、石油泄漏、过度捕捞。保护海洋的重要性。', en: 'Learn about coasts and oceans. Erosion forms caves, arches, stacks. Tides from Moon/Sun gravity. Ocean currents affect climate (Gulf Stream warms Western Europe). Marine pollution: plastic, oil spills, overfishing. Importance of ocean conservation.', age: '9-11' },
      { topic: '可持续发展', zh: '学习可持续发展的概念。可持续发展：满足当代人需求而不损害后代人满足需求的能力。三大支柱：经济发展、社会公平、环境保护。实践：减少废物、节约能源、保护生物多样性、公平贸易。了解联合国可持续发展目标(SDGs)。每个人都可以为可持续发展做出贡献。', en: 'Learn about sustainable development. Meeting present needs without compromising future generations. Three pillars: economic development, social equity, environmental protection. Practice: reduce waste, conserve energy, protect biodiversity, fair trade. Understand UN Sustainable Development Goals (SDGs). Everyone can contribute.', age: '10-11' },
      { topic: '冰川和冰盖', zh: '学习冰川和冰盖的知识。冰川：由积雪压缩形成的大冰体，缓慢流动。冰盖：覆盖大面积陆地的冰层（南极冰盖和格陵兰冰盖）。冰川的作用：塑造地形（U形谷、冰碛湖）、储存淡水（占全球淡水68.7%）。冰川退缩：全球变暖导致冰川加速融化，影响海平面和水资源。了解冰川对气候变化的敏感性。', en: 'Learn about glaciers and ice sheets. Glaciers: large ice bodies from compressed snow, flowing slowly. Ice sheets: ice covering large land areas (Antarctic, Greenland). Glacier roles: shaping landscapes (U-valleys, moraine lakes), storing freshwater (68.7%). Glacier retreat: global warming accelerates melting, affecting sea levels and water resources. Understand glacier sensitivity to climate change.', age: '10-11' },
      { topic: '世界人口增长', zh: '学习世界人口增长的历程和趋势。公元前10000年：约400万人。公元1年：约2亿人。1800年：约10亿人。2024年：约80亿人。人口增长加速的原因：农业发展、工业革命、医学进步。人口问题：资源消耗增加、环境压力增大、发展中国家人口增长快。人口转型：从高出生率高死亡率转向低出生率低死亡率。', en: 'Learn about world population growth. 10000 BC: ~4 million. Year 1: ~200 million. 1800: ~1 billion. 2024: ~8 billion. Acceleration causes: agriculture, Industrial Revolution, medical advances. Population challenges: increased resource consumption, environmental pressure, rapid growth in developing countries. Demographic transition: from high birth/death rates to low birth/death rates.', age: '10-11' },
      { topic: '天气和气候', zh: '区分天气和气候。天气：短时间内大气的状态（今天的温度、降水）。气候：一个地区长期的天气平均模式（地中海气候：夏季干热、冬季温和多雨）。影响气候的因素：纬度、海拔、距海远近、洋流。不同气候类型：热带气候、干旱气候、温带气候、大陆性气候、极地气候。了解气候变化与天气变化的区别。', en: 'Distinguish weather and climate. Weather: short-term atmospheric conditions. Climate: long-term weather patterns (Mediterranean climate: dry hot summers, mild wet winters). Climate factors: latitude, altitude, distance from sea, ocean currents. Climate types: tropical, arid, temperate, continental, polar. Understand difference between climate change and weather variation.', age: '9-11' },
      { topic: '自然灾害', zh: '学习自然灾害的知识。地震：板块运动引起，用里氏震级测量。海啸：海底地震引起的巨浪。火山喷发：岩浆和气体喷出。飓风/台风：热带海洋上形成的强烈风暴。洪水：暴雨或河流泛滥。干旱：长期缺水。了解不同自然灾害的成因、影响和防灾减灾措施。早期预警系统可以减少伤亡。', en: 'Learn about natural disasters. Earthquakes: plate movement, measured by Richter scale. Tsunamis: huge waves from undersea earthquakes. Volcanic eruptions: magma and gas expelled. Hurricanes/typhoons: intense storms over tropical oceans. Floods: heavy rain or river overflow. Droughts: prolonged water shortage. Understand causes, impacts, and disaster prevention. Early warning systems reduce casualties.', age: '9-11' },
      { topic: '欧洲国家研究', zh: '深入学习欧洲主要国家。法国：首都巴黎，以美食、时尚和艺术闻名，欧盟核心成员。德国：首都柏林，欧洲最大经济体，以工程和制造业著称。意大利：首都罗马，拥有丰富的历史遗迹和文化遗产。西班牙：首都马德里，以弗拉门戈舞和斗牛闻名。了解各国的人口、语言、货币和主要产业。', en: 'Deepen study of major European countries. France: capital Paris, known for cuisine, fashion, art, core EU member. Germany: capital Berlin, largest European economy, known for engineering. Italy: capital Rome, rich historical heritage. Spain: capital Madrid, known for flamenco. Understand population, language, currency, and main industries of each country.', age: '9-11' }
    ],

    foreignLanguage: [
      { topic: '法语基础：问候', zh: '学习法语的基本问候。Bonjour（你好，白天用）、Bonsoir（晚上好）、Salut（嗨，非正式）、Au revoir（再见）、Merci（谢谢）、S\'il vous plaît（请）、De rien（不客气）、Comment allez-vous?（您好吗？）、Je vais bien（我很好）。法语是法国、比利时、瑞士和许多非洲国家的官方语言。', en: 'Learn basic French greetings. Bonjour (hello, daytime), Bonsoir (good evening), Salut (hi, informal), Au revoir (goodbye), Merci (thank you), S\'il vous plaît (please), De rien (youre welcome), Comment allez-vous? (how are you?), Je vais bien (Im fine). French is official in France, Belgium, Switzerland, and many African countries.', age: '7-9' },
      { topic: '法语基础：数字', zh: '学习法语的数字。1-10：un, deux, trois, quatre, cinq, six, sept, huit, neuf, dix。11-20：onze, douze, treize, quatorze, quinze, seize, dix-sept, dix-huit, dix-neuf, vingt。法语数字有特殊的计数方式：70=soixante-dix（60+10），80=quatre-vingts（4×20），90=quatre-vingt-dix（4×20+10）。', en: 'Learn French numbers. 1-10: un, deux, trois, quatre, cinq, six, sept, huit, neuf, dix. 11-20: onze, douze, treize, quatorze, quinze, seize, dix-sept, dix-huit, dix-neuf, vingt. Special counting: 70=soixante-dix (60+10), 80=quatre-vingts (4×20), 90=quatre-vingt-dix (4×20+10).', age: '7-9' },
      { topic: '法语基础：日常用语', zh: '学习法语的日常用语。Je m\'appelle...（我叫……）、J\'ai ... ans（我……岁）、J\'habite à...（我住在……）、Je suis anglais(e)（我是英国人）、Oui（是）、Non（不）、Excusez-moi（对不起/打扰了）、Parlez-vous anglais?（您说英语吗？）、Je ne comprends pas（我不明白）。', en: 'Learn French everyday expressions. Je m\'appelle... (My name is...), J\'ai ... ans (I am ... years old), J\'habite à... (I live in...), Je suis anglais(e) (I am English), Oui (yes), Non (no), Excusez-moi (excuse me), Parlez-vous anglais? (Do you speak English?), Je ne comprends pas (I dont understand).', age: '7-11' },
      { topic: '德语基础：问候和介绍', zh: '学习德语的基本问候和介绍。Guten Tag（你好）、Guten Morgen（早上好）、Guten Abend（晚上好）、Auf Wiedersehen（再见）、Tschüss（再见，非正式）、Danke（谢谢）、Bitte（请/不客气）、Wie heißt du?（你叫什么？）、Ich heiße...（我叫……）、Wie alt bist du?（你几岁？）、Ich bin ... Jahre alt（我……岁）。德语是德国、奥地利和瑞士的官方语言。', en: 'Learn basic German greetings and introductions. Guten Tag (hello), Guten Morgen (good morning), Guten Abend (good evening), Auf Wiedersehen (goodbye), Tschüss (bye, informal), Danke (thank you), Bitte (please/youre welcome), Wie heißt du? (whats your name?), Ich heiße... (my name is...). German is official in Germany, Austria, and Switzerland.', age: '7-9' },
      { topic: '德语基础：数字', zh: '学习德语的数字。1-10：eins, zwei, drei, vier, fünf, sechs, sieben, acht, neun, zehn。11-20：elf, zwölf, dreizehn, vierzehn, fünfzehn, sechzehn, siebzehn, achtzehn, neunzehn, zwanzig。德语数字组合方式：21=einundzwanzig（一和二十），与英语顺序相反。', en: 'Learn German numbers. 1-10: eins, zwei, drei, vier, fünf, sechs, sieben, acht, neun, zehn. 11-20: elf, zwölf, dreizehn, vierzehn, fünfzehn, sechzehn, siebzehn, achtzehn, neunzehn, zwanzig. Number combination: 21=einundzwanzig (one-and-twenty), reverse order from English.', age: '7-9' },
      { topic: '西班牙语基础', zh: '学习西班牙语的基本用语。Hola（你好）、Buenos días（早上好）、Buenas tardes（下午好）、Adiós（再见）、Gracias（谢谢）、Por favor（请）、¿Cómo te llamas?（你叫什么？）、Me llamo...（我叫……）、¿Cuántos años tienes?（你几岁？）、Tengo ... años（我……岁）。西班牙语是世界第二大母语语言。', en: 'Learn basic Spanish. Hola (hello), Buenos días (good morning), Buenas tardes (good afternoon), Adiós (goodbye), Gracias (thank you), Por favor (please), ¿Cómo te llamas? (whats your name?), Me llamo... (my name is...). Spanish is the worlds second-largest native language.', age: '7-11' },
      { topic: '法语：颜色和描述', zh: '学习法语的颜色和描述词。颜色：rouge（红）、bleu（蓝）、vert（绿）、jaune（黄）、noir（黑）、blanc（白）、orange（橙）、rose（粉）。描述：grand/petite（大/小）、beau/belle（美）、nouveau/nouvelle（新）、vieux/vieille（旧）。法语名词分阴阳性，形容词要与名词性数一致。', en: 'Learn French colors and descriptions. Colors: rouge (red), bleu (blue), vert (green), jaune (yellow), noir (black), blanc (white). Descriptions: grand/petite (big/small), beau/belle (beautiful), nouveau/nouvelle (new), vieux/vieille (old). French nouns have gender; adjectives agree in gender and number.', age: '9-11' },
      { topic: '法语：食物和饮料', zh: '学习法语的食物和饮料词汇。Le pain（面包）、le fromage（奶酪）、le croissant（牛角面包）、le vin（葡萄酒）、l\'eau（水）、le café（咖啡）、la pomme（苹果）、la viande（肉）、le poisson（鱼）、les légumes（蔬菜）。在法国餐厅点餐：Je voudrais...（我想要……）、L\'addition, s\'il vous plaît（买单）。', en: 'Learn French food and drink vocabulary. Le pain (bread), le fromage (cheese), le croissant (croissant), le vin (wine), l\'eau (water), le café (coffee), la pomme (apple), la viande (meat), le poisson (fish), les légumes (vegetables). Ordering: Je voudrais... (I would like...), L\'addition, s\'il vous plaît (the bill, please).', age: '9-11' },
      { topic: '德语：学校和生活', zh: '学习德语的学校和生活词汇。Die Schule（学校）、der Lehrer/die Lehrerin（老师）、das Buch（书）、der Stift（笔）、die Hausaufgabe（作业）、das Klassenzimmer（教室）、die Pause（休息）、das Essen（食物）、das Haus（房子）、die Familie（家庭）。德语名词首字母大写，有三种性（阳性、阴性、中性）。', en: 'Learn German school and life vocabulary. Die Schule (school), der Lehrer/die Lehrerin (teacher), das Buch (book), der Stift (pen), die Hausaufgabe (homework), das Klassenzimmer (classroom), die Pause (break), das Essen (food), das Haus (house), die Familie (family). German nouns are capitalized and have three genders (masculine, feminine, neuter).', age: '9-11' },
      { topic: '欧洲语言概览', zh: '了解欧洲的语言多样性。印欧语系：日耳曼语族（英语、德语、荷兰语）、罗曼语族（法语、西班牙语、意大利语）、斯拉夫语族（俄语、波兰语）。非印欧语系：芬兰语、匈牙利语、巴斯克语。欧盟有24种官方语言。英语是欧洲最广泛使用的第二语言。多语言能力在欧洲非常重要。', en: 'Understand European language diversity. Indo-European: Germanic (English, German, Dutch), Romance (French, Spanish, Italian), Slavic (Russian, Polish). Non-Indo-European: Finnish, Hungarian, Basque. EU has 24 official languages. English is the most widely used second language. Multilingual ability is very important in Europe.', age: '9-11' },
      { topic: '法语：学校词汇', zh: '学习法语的学校相关词汇。L\'école（学校）、le professeur（老师）、l\'élève（学生）、le livre（书）、les devoirs（作业）、la classe（班级）、la récréation（课间休息）。描述学校生活：J\'aime l\'école（我喜欢学校）、Mon sujet préféré est...（我最喜欢的科目是……）。', en: 'Learn French school vocabulary. L\'école (school), le professeur (teacher), l\'élève (student), le livre (book), les devoirs (homework), la classe (class), la récréation (break). Describe school life: J\'aime l\'école (I like school), Mon sujet préféré est... (My favorite subject is...).', age: '9-11' },
      { topic: '法语：时间和日期', zh: '学习法语的时间和日期表达。星期：lundi, mardi, mercredi, jeudi, vendredi, samedi, dimanche。月份：janvier到décembre。Quelle heure est-il?（几点了？）Il est trois heures（三点）。', en: 'Learn French time and date expressions. Days: lundi to dimanche. Months: janvier to décembre. Quelle heure est-il? (What time is it?) Il est trois heures (Its three oclock).', age: '9-11' },
      { topic: '德语：日常活动', zh: '学习德语描述日常活动。Ich stehe auf（我起床）、Ich frühstücke（我吃早餐）、Ich gehe zur Schule（我去上学）、Ich spiele（我玩）、Ich lese（我阅读）、Ich schlafe（我睡觉）。用德语描述自己的一天。', en: 'Learn German daily activities. Ich stehe auf (I get up), Ich frühstücke (I have breakfast), Ich gehe zur Schule (I go to school). Describe your day in German.', age: '9-11' },
      { topic: '西班牙语：基础对话', zh: '学习西班牙语基础对话。¿De dónde eres?（你从哪里来？）Soy de...（我来自……）、¿Qué te gusta?（你喜欢什么？）Me gusta...（我喜欢……）、Tengo un hermano（我有一个兄弟）。', en: 'Learn basic Spanish conversation. ¿De dónde eres? (Where are you from?) Soy de... (Im from...), ¿Qué te gusta? (What do you like?) Me gusta... (I like...).', age: '9-11' },
      { topic: '法语：家庭和人物', zh: '学习法语的家庭和人物描述。La mère（母亲）、le père（父亲）、le frère（兄弟）、la sœur（姐妹）。描述人物：Il est grand（他很高）、Elle est blonde（她是金发）、Il a les yeux bleus（他有蓝眼睛）。', en: 'Learn French family and person descriptions. La mère (mother), le père (father), le frère (brother), la sœur (sister). Il est grand (He is tall), Elle est blonde (She is blonde).', age: '9-11' },
      { topic: '德语：颜色和描述', zh: '学习德语的颜色和描述词。rot（红）、blau（蓝）、grün（绿）、gelb（黄）、schwarz（黑）、weiß（白）。groß/klein（大/小）、schön（美）、neu（新）、alt（旧）。德语形容词在名词前需要变格。', en: 'Learn German colors and descriptions. rot (red), blau (blue), grün (green), gelb (yellow). groß/klein (big/small), schön (beautiful), neu (new), alt (old). German adjectives decline before nouns.', age: '9-11' },
      { topic: '法语：天气和季节', zh: '学习法语的天气和季节表达。le printemps（春天）、l\'été（夏天）、l\'automne（秋天）、l\'hiver（冬天）。Il fait beau（天气好）、Il fait froid（天气冷）、Il pleut（下雨）、Il neige（下雪）。', en: 'Learn French weather and seasons. le printemps (spring), l\'été (summer), l\'automne (autumn), l\'hiver (winter). Il fait beau (nice weather), Il fait froid (its cold), Il pleut (its raining).', age: '9-11' }
    ]
  },

  // ============================================================
  // Key Stage 3 (Age 11-14, Grade 7-9)
  // ============================================================
  ks3: {

    math: [
      { topic: '代数表达式', zh: '学习代数表达式的建立和化简。同类项合并：3x+5x=8x。展开括号：2(x+3)=2x+6。因式分解：6x+9=3(2x+3), x²-9=(x+3)(x-3)。代数是解决实际问题的强大工具。', en: 'Learn to build and simplify algebraic expressions. Like terms: 3x+5x=8x. Expanding brackets: 2(x+3)=2x+6. Factorising: 6x+9=3(2x+3), x²-9=(x+3)(x-3). Algebra is a powerful tool for solving real problems.', age: '11-13' },
      { topic: '线性方程', zh: '学习解线性方程。一步方程：x+5=12, x=7。两步方程：2x+3=11, x=4。含括号方程：3(x-2)=15, x=7。含分数方程：x/3+2=5, x=9。等式性质：两边同时加减乘除相同的数，等式仍然成立。', en: 'Learn to solve linear equations. One-step: x+5=12, x=7. Two-step: 2x+3=11, x=4. With brackets: 3(x-2)=15, x=7. With fractions: x/3+2=5, x=9. Equality properties maintain balance.', age: '11-13' },
      { topic: '不等式', zh: '学习解不等式。不等式符号：<, >, ≤, ≥。两边乘以或除以负数时要变号：-2x>6, x<-3。在数轴上表示解集。解复合不等式：2<x+1<5, 1<x<4。应用：速度限制、温度范围等实际问题。', en: 'Learn to solve inequalities. Symbols: <, >, ≤, ≥. Reverse sign when multiplying/dividing by negative: -2x>6, x<-3. Represent on number lines. Compound inequalities: 2<x+1<5, 1<x<4. Applications: speed limits, temperature ranges.', age: '12-14' },
      { topic: '几何证明', zh: '学习几何证明的方法。三角形内角和=180°的证明。平行线性质：同位角相等、内错角相等。全等三角形判定：SSS, SAS, ASA, AAS, RHS。用逻辑推理写出完整的证明过程。', en: 'Learn geometric proof methods. Triangle angle sum=180° proof. Parallel line properties: corresponding and alternate angles. Congruent triangle criteria: SSS, SAS, ASA, AAS, RHS. Write complete proofs using logical reasoning.', age: '12-14' },
      { topic: '概率统计', zh: '深入学习概率和统计。互斥事件：P(A或B)=P(A)+P(B)。独立事件：P(A且B)=P(A)×P(B)。树形图计算多步实验概率。统计：平均数、中位数、众数、极差。累积频数曲线。散点图和相关关系。', en: 'Deepen probability and statistics. Mutually exclusive: P(A or B)=P(A)+P(B). Independent: P(A and B)=P(A)×P(B). Tree diagrams. Statistics: mean, median, mode, range. Cumulative frequency curves. Scatter plots and correlation.', age: '12-14' },
      { topic: '比例和比率', zh: '深入学习比例和比率。直接比例：y=kx。反比例：y=k/x。比例问题：如果3个工人5天完成工作，5个工人需要几天？（反比例：3×5=5×x, x=3天）。比例在科学和工程中广泛应用。', en: 'Deepen ratio and proportion. Direct proportion: y=kx. Inverse proportion: y=k/x. If 3 workers take 5 days, how long for 5 workers? (Inverse: 3×5=5×x, x=3 days). Proportion is widely used in science and engineering.', age: '11-13' },
      { topic: '勾股定理', zh: '学习勾股定理。直角三角形中，a²+b²=c²（c为斜边）。求斜边：3²+4²=c², c=5。应用：判断直角三角形、计算距离。证明方法：面积法。中国称为勾股定理，西方称为毕达哥拉斯定理。', en: 'Learn Pythagoras theorem. In right triangles, a²+b²=c². Find hypotenuse: 3²+4²=c², c=5. Applications: determine right triangles, calculate distances. Proof: area method. Known as Gougu theorem in China, Pythagorean in the West.', age: '12-14' },
      { topic: '三角函数入门', zh: '学习三角函数基础。sinθ=对边/斜边, cosθ=邻边/斜边, tanθ=对边/邻边。记忆口诀：SOH-CAH-TOA。已知角和一边求另一边。已知两边求角。三角函数在测量、导航和工程中广泛应用。', en: 'Learn introductory trigonometry. sinθ=opposite/hypotenuse, cosθ=adjacent/hypotenuse, tanθ=opposite/adjacent. Mnemonic: SOH-CAH-TOA. Find sides given angle and side. Find angles given two sides. Used in surveying, navigation, engineering.', age: '13-14' },
      { topic: '函数和图像', zh: '学习函数的概念和图像。线性函数y=mx+c：m是斜率，c是y截距。画图像：列表取值→描点→连线。二次函数y=ax²+bx+c是抛物线。理解图像与方程的对应关系。', en: 'Learn function concepts and graphs. Linear y=mx+c: m is gradient, c is y-intercept. Plotting: table of values → plot points → connect. Quadratic y=ax²+bx+c is a parabola. Understand correspondence between graphs and equations.', age: '12-14' },
      { topic: '圆的性质', zh: '学习圆的几何性质。周长=2πr, 面积=πr²。弧长=θ/360×2πr, 扇形面积=θ/360×πr²。圆的定理：圆心角是圆周角的两倍；直径所对的圆周角是直角；切线与半径垂直。', en: 'Learn circle geometry. Circumference=2πr, Area=πr². Arc length=θ/360×2πr, Sector area=θ/360×πr². Circle theorems: center angle is twice circumference angle; angle in semicircle is 90°; tangent perpendicular to radius.', age: '12-14' },
      { topic: '指数和根式', zh: '学习指数和根式运算。指数法则：aᵐ×aⁿ=aᵐ⁺ⁿ, aᵐ÷aⁿ=aᵐ⁻ⁿ, (aᵐ)ⁿ=aᵐⁿ, a⁰=1, a⁻ⁿ=1/aⁿ。科学记数法：3.5×10⁶=3500000。有理化分母：1/√2=√2/2。', en: 'Learn exponent and radical operations. Index laws: aᵐ×aⁿ=aᵐ⁺ⁿ, aᵐ÷aⁿ=aᵐ⁻ⁿ, (aᵐ)ⁿ=aᵐⁿ, a⁰=1, a⁻ⁿ=1/aⁿ. Scientific notation: 3.5×10⁶=3500000. Rationalizing: 1/√2=√2/2.', age: '12-14' },
      { topic: '序列和级数', zh: '学习序列和级数。等差数列：第n项=a+(n-1)d，前n项和=n/2×(2a+(n-1)d)。等比数列：第n项=arⁿ⁻¹。识别规律：2,5,8,11...（等差，d=3）；3,6,12,24...（等比，r=2）。', en: 'Learn sequences and series. Arithmetic: nth term=a+(n-1)d, sum=n/2×(2a+(n-1)d). Geometric: nth term=arⁿ⁻¹. Patterns: 2,5,8,11... (arithmetic, d=3); 3,6,12,24... (geometric, r=2).', age: '13-14' },
      { topic: '变换几何', zh: '学习几何变换。平移：沿指定方向移动。反射：关于一条线的镜像。旋转：绕一个点旋转指定角度。放大：按比例因子放大或缩小。复合变换：连续进行多种变换。', en: 'Learn geometric transformations. Translation: move by direction and distance. Reflection: mirror image about a line. Rotation: rotate around a point. Enlargement: scale by a factor. Composite transformations.', age: '11-13' },
      { topic: '实数系统', zh: '学习实数系统。自然数→整数→有理数→实数。有理数：可表示为p/q的数。无理数：如√2, π。证明√2是无理数（反证法）。了解不同数集之间的关系。', en: 'Learn the real number system. Natural→Integers→Rational→Real. Rational: expressible as p/q. Irrational: like √2, π. Prove √2 is irrational (contradiction). Understand relationships between number sets.', age: '12-14' },
      { topic: '联立方程', zh: '学习解联立方程组。代入法：从一个方程表示一个变量，代入另一个方程。消元法：加减方程消去一个变量。例如：x+y=10, x-y=4，相加得2x=14, x=7, y=3。应用：解决实际问题，如两种商品的价格。', en: 'Learn to solve simultaneous equations. Substitution: express one variable from one equation, substitute into the other. Elimination: add/subtract equations to eliminate a variable. Example: x+y=10, x-y=4, adding gives 2x=14, x=7, y=3. Applications: solving real problems like pricing.', age: '12-14' },
      { topic: '二次方程', zh: '学习解二次方程。因式分解法：x²-5x+6=0, (x-2)(x-3)=0, x=2或x=3。求根公式：x=(-b±√(b²-4ac))/2a。配方法：x²+6x+5=0, (x+3)²=4, x=-1或x=-5。判别式Δ=b²-4ac：Δ>0两个实根，Δ=0一个实根，Δ<0无实根。', en: 'Learn to solve quadratic equations. Factorising: x²-5x+6=0, (x-2)(x-3)=0, x=2 or 3. Quadratic formula: x=(-b±√(b²-4ac))/2a. Completing the square. Discriminant Δ=b²-4ac: Δ>0 two real roots, Δ=0 one real root, Δ<0 no real roots.', age: '13-14' },
      { topic: '统计调查方法', zh: '学习设计和执行统计调查。步骤：明确目的→设计问卷→选择抽样方法→收集数据→整理展示→分析解释。偏差来源：抽样偏差、无回应偏差、问题设计偏差。确保调查结果可靠的方法。', en: 'Learn to design and conduct statistical surveys. Steps: define purpose → design questionnaire → choose sampling → collect data → organize → analyze. Bias sources: sampling, non-response, question design bias. Ensuring reliable results.', age: '12-14' },
      { topic: '相似和全等', zh: '学习相似和全等三角形。全等：形状和大小完全相同，判定条件SSS, SAS, ASA, AAS, RHS。相似：形状相同但大小不同，判定条件AA, SAS, SSS。相似比：对应边之比相等。面积比=相似比的平方。体积比=相似比的立方。应用：测量不可到达的距离。', en: 'Learn similar and congruent triangles. Congruent: identical shape and size, criteria SSS, SAS, ASA, AAS, RHS. Similar: same shape, different size, criteria AA, SAS, SSS. Ratio of areas=similarity ratio². Ratio of volumes=similarity ratio³. Applications: measuring inaccessible distances.', age: '12-14' },
      { topic: '坐标几何', zh: '学习坐标几何。两点间距离：d=√((x₂-x₁)²+(y₂-y₁)²)。中点公式：((x₁+x₂)/2, (y₁+y₂)/2)。直线斜率：m=(y₂-y₁)/(x₂-x₁)。直线方程：y-y₁=m(x-x₁)。平行线斜率相同，垂直线斜率之积为-1。', en: 'Learn coordinate geometry. Distance between points: d=√((x₂-x₁)²+(y₂-y₁)²). Midpoint: ((x₁+x₂)/2, (y₁+y₂)/2). Gradient: m=(y₂-y₁)/(x₂-x₁). Line equation: y-y₁=m(x-x₁). Parallel lines have equal gradients; perpendicular lines have gradients whose product is -1.', age: '13-14' },
      { topic: '负数和绝对值', zh: '深入学习负数运算和绝对值。负数乘法：(-3)×(-4)=12（负负得正）。绝对值：|x|表示x到0的距离，|-5|=5, |3|=3。绝对值方程：|x|=3, x=3或x=-3。绝对值不等式：|x|<3, -3<x<3。数轴上理解绝对值的几何意义。', en: 'Deepen understanding of negative number operations and absolute value. Negative multiplication: (-3)×(-4)=12. Absolute value: |x| represents distance from 0, |-5|=5. Absolute value equations: |x|=3, x=3 or -3. Absolute value inequalities: |x|<3, -3<x<3. Understand geometric meaning on number line.', age: '11-13' },
      { topic: '数学建模', zh: '学习数学建模的基本方法。建模步骤：实际问题→简化假设→建立数学模型→求解→验证→改进模型。例如：预测人口增长（指数模型）、计算贷款利息（复利公式）、优化路线（最短路径）。数学建模将数学应用于解决现实世界的复杂问题。', en: 'Learn basic mathematical modeling methods. Steps: real problem → simplify assumptions → build mathematical model → solve → verify → improve. Examples: predicting population growth (exponential model), calculating loan interest (compound interest), optimizing routes (shortest path). Mathematical modeling applies math to solve complex real-world problems.', age: '13-14' }
    ],

    english: [
      { topic: '文学分析', zh: '学习文学分析的方法。分析要素：主题（作品探讨的核心思想）、人物（性格特征、动机、变化）、情节（事件结构）、背景（时间和地点）、叙事视角（谁在讲故事）。使用PEE/PETAL结构回答分析题：Point(观点)→Evidence(引用证据)→Technique(分析手法)→Analysis(深入分析)→Link(联系主题)。分析时使用学术语言。', en: 'Learn literary analysis methods. Elements: theme, character, plot, setting, narrative perspective. Use PEE/PETAL structure: Point → Evidence → Technique → Analysis → Link. Use academic language when analyzing. Analyze how writers use language, structure, and form to create effects and meanings.', age: '12-14' },
      { topic: '议论文写作', zh: '学习写正式的议论文。结构：引言（提出论点和背景）→正文段落（每个段落一个论据，使用PEEL结构）→反驳（考虑对立观点）→结论（重申论点，总结要点）。PEEL：Point(论点)→Evidence(证据)→Explanation(解释)→Link(联系)。使用正式语言和学术词汇，避免口语化和缩写。', en: 'Learn to write formal argumentative essays. Structure: introduction (thesis and context) → body paragraphs (one argument each, PEEL structure) → counter-argument → conclusion. PEEL: Point → Evidence → Explanation → Link. Use formal language and academic vocabulary, avoiding colloquialisms and contractions.', age: '12-14' },
      { topic: '莎士比亚', zh: '学习莎士比亚及其作品。威廉·莎士比亚(1564-1616)是英国最伟大的剧作家。主要作品：悲剧（《罗密欧与朱丽叶》《哈姆雷特》《麦克白》）、喜剧（《仲夏夜之梦》《威尼斯商人》）。莎士比亚对英语的贡献：创造约1700个新词和众多习语。理解伊丽莎白时代的背景。分析莎士比亚的语言：无韵诗、比喻、双关语。', en: 'Learn about Shakespeare and his works. William Shakespeare (1564-1616) was Englands greatest playwright. Major works: tragedies (Romeo and Juliet, Hamlet, Macbeth), comedies (A Midsummer Nights Dream, The Merchant of Venice). Contributions to English: ~1700 new words and many idioms. Understand Elizabethan context. Analyze his language: blank verse, metaphor, puns.', age: '12-14' },
      { topic: '诗歌分析', zh: '深入学习诗歌分析。分析维度：形式（十四行诗、自由诗、俳句）、结构（诗节、韵律模式）、语言（意象、比喻、拟人、明喻）、音韵（押韵、头韵、半韵、节奏）。比较诗歌：找出两首诗在主题、语言和态度上的相似和不同。了解不同的诗歌运动和流派。用学术语言写出诗歌分析。', en: 'Deepen poetry analysis. Dimensions: form (sonnet, free verse), structure (stanzas, rhyme scheme), language (imagery, metaphor, personification, simile), sound (rhyme, alliteration, rhythm). Comparing poems: find similarities and differences in theme, language, and attitude. Understand different poetic movements. Write poetry analysis using academic language.', age: '12-14' },
      { topic: '修辞手法', zh: '系统学习修辞手法。明喻(Simile)：用"像"比较——"Her eyes were like stars"。暗喻(Metaphor)：直接说A是B——"Time is money"。拟人(Personification)：赋予非人事物人的特征——"The wind whispered"。夸张(Hyperbole)：故意夸大——"Ive told you a million times"。反讽(Irony)：说反话。排比(Parallelism)：重复句式结构。识别和分析文本中的修辞手法。', en: 'Systematically learn rhetorical devices. Simile: comparison using "like/as." Metaphor: saying A is B. Personification: giving human qualities to non-human things. Hyperbole: deliberate exaggeration. Irony: saying the opposite. Parallelism: repeating sentence structures. Identify and analyze rhetorical devices in texts.', age: '12-14' },
      { topic: '批判性阅读', zh: '学习批判性阅读技能。区分事实和观点：事实可以验证，观点是个人看法。识别偏见和立场：作者是否有倾向性？评估证据的可靠性：来源是否可信？论据是否充分？分析说服技巧：作者如何试图说服读者？比较不同来源对同一事件的报道。培养独立思考和判断的能力。', en: 'Learn critical reading skills. Distinguish fact from opinion. Identify bias and stance: does the author have an agenda? Evaluate evidence reliability: are sources credible? Are arguments well-supported? Analyze persuasive techniques: how does the author try to convince readers? Compare different sources covering the same event. Develop independent thinking and judgment.', age: '12-14' },
      { topic: '创意写作进阶', zh: '提高创意写作水平。叙事技巧：展示而非告知（Show, dont tell）——"她的手在颤抖"比"她很紧张"更生动。人物塑造：通过对话、行动和内心独白展现人物性格。氛围营造：用环境描写创造情绪。节奏控制：紧张时用短句，舒缓时用长句。修改和润色：好文章是改出来的。', en: 'Improve creative writing skills. Narrative techniques: "Show, dont tell" — "Her hands trembled" is more vivid than "She was nervous." Character development: reveal personality through dialogue, actions, and inner monologue. Atmosphere: use setting to create mood. Pacing: short sentences for tension, long for relaxation. Revision and polishing: good writing comes from revision.', age: '12-14' },
      { topic: '小说分析', zh: '学习分析小说。分析要素：叙事视角（第一人称、第三人称有限/全知）、人物类型（主角、反派、圆形/扁平人物）、情节结构（开端、发展、高潮、下降、结局）、主题和象征。阅读并分析一部完整的小说，写一篇800-1000字的分析文章。了解不同文学流派：现实主义、浪漫主义、哥特小说。', en: 'Learn to analyze novels. Elements: narrative perspective (first person, third person limited/omniscient), character types (protagonist, antagonist, round/flat), plot structure, themes and symbolism. Read and analyze a complete novel, writing an 800-1000 word analytical essay. Understand literary genres: realism, romanticism, Gothic fiction.', age: '12-14' },
      { topic: '语法进阶：从句', zh: '深入学习从句的用法。主语从句：What he said surprised everyone。宾语从句：I know that she is right。定语从句：The book which I bought yesterday is excellent（限定性）/My mother, who is a teacher, loves reading（非限定性）。状语从句：时间(when)、原因(because)、条件(if)、让步(although)、目的(so that)。正确使用从句使写作更复杂和精确。', en: 'Deepen understanding of clauses. Subject clauses: What he said surprised everyone. Object clauses: I know that she is right. Relative clauses: restrictive (which I bought) and non-restrictive (who is a teacher). Adverbial clauses: time (when), reason (because), condition (if), concession (although), purpose (so that). Use clauses correctly for complex and precise writing.', age: '12-14' },
      { topic: '非虚构写作', zh: '学习非虚构写作的技巧。说明文：清晰解释一个概念或过程。议论文：有理有据地论证一个观点。评论：评价一部作品或一个事件。写作原则：准确（事实正确）、清晰（逻辑清楚）、简洁（没有多余的话）、客观（避免偏见）。引用来源：标注信息来源，避免抄袭。', en: 'Learn non-fiction writing techniques. Explanatory: clearly explain a concept or process. Argumentative: support a viewpoint with evidence. Review: evaluate a work or event. Writing principles: accurate (correct facts), clear (logical), concise (no redundancy), objective (avoid bias). Cite sources to avoid plagiarism.', age: '12-14' },
      { topic: '戏剧研究', zh: '学习戏剧的分析和表演。戏剧要素：对话、舞台指示、角色、冲突、高潮。阅读完整剧本并分析：人物关系、冲突发展、主题表达。了解不同的戏剧传统：古希腊悲剧、莎士比亚戏剧、现代话剧。表演技能：台词表达、角色理解、舞台空间利用。在课堂上表演剧本片段。', en: 'Learn drama analysis and performance. Elements: dialogue, stage directions, character, conflict, climax. Read complete plays analyzing character relationships, conflict development, theme expression. Understand dramatic traditions: Greek tragedy, Shakespearean drama, modern theater. Performance skills: line delivery, character understanding, stage space use. Perform play excerpts in class.', age: '12-14' },
      { topic: '比较写作', zh: '学习比较写作的技巧。比较两篇文本：主题、语言、结构、态度的异同。使用比较连接词：similarly, likewise, in contrast, whereas, on the other hand, both, while。结构选择：逐点比较（先比主题，再比语言）或逐篇比较（先完整分析A，再分析B）。写一篇比较两首诗或两个文本的文章。', en: 'Learn comparative writing techniques. Compare two texts: themes, language, structure, attitudes. Use comparative connectives: similarly, likewise, in contrast, whereas, on the other hand. Structure choices: point-by-point or text-by-text. Write an essay comparing two poems or texts.', age: '12-14' },
      { topic: '学术写作基础', zh: '学习学术写作的基础。特点：正式、客观、精确、有证据支持。避免：口语化、缩写、第一人称（通常）、情感化语言。引用格式：作者-年份制（Smith, 2020）或脚注。参考文献列表：列出所有引用的来源。学术诚信：正确引用，不抄袭。为高中和大学的学术写作做准备。', en: 'Learn academic writing basics. Characteristics: formal, objective, precise, evidence-supported. Avoid: colloquialisms, contractions, first person (usually), emotional language. Citation format: author-year (Smith, 2020) or footnotes. Reference list: all cited sources. Academic integrity: cite properly, no plagiarism. Prepare for high school and university academic writing.', age: '13-14' },
      { topic: '口语和辩论', zh: '学习口语表达和辩论技能。正式演讲：结构清晰、论据充分、语言正式。辩论：正方和反方就一个议题展开辩论。辩论技巧：开场陈述、反驳、总结陈词。倾听和回应：认真听取对方论点，有针对性地反驳。评估论据的强度和逻辑性。培养自信和有说服力的口头表达能力。', en: 'Learn speaking and debating skills. Formal speeches: clear structure, sufficient evidence, formal language. Debating: proposition and opposition argue an issue. Debate techniques: opening statement, rebuttal, closing argument. Listening and responding: hear opposing arguments and rebut specifically. Evaluate argument strength and logic. Develop confident and persuasive oral expression.', age: '12-14' },
      { topic: '媒体素养', zh: '学习媒体素养。分析不同媒体文本：新闻文章、广告、社交媒体帖子、视频。识别说服技巧：情感诉求、权威引用、数据使用、选择性呈现。了解媒体如何塑造公众观点。事实核查：验证信息的真实性。数字素养：安全地使用互联网，保护个人隐私。培养批判性消费媒体的习惯。', en: 'Learn media literacy. Analyze different media texts: news articles, advertisements, social media posts, videos. Identify persuasive techniques: emotional appeal, authority citation, data use, selective presentation. Understand how media shapes public opinion. Fact-checking: verify information accuracy. Digital literacy: safe internet use, protect privacy. Develop critical media consumption habits.', age: '12-14' },
      { topic: '英国文学传统', zh: '了解英国文学传统。古英语时期：《贝奥武夫》。中世纪：乔叟《坎特伯雷故事集》。文艺复兴：莎士比亚。浪漫主义：华兹华斯、济慈、雪莱。维多利亚时代：狄更斯、勃朗特姐妹。现代主义：T.S.艾略特、弗吉尼亚·伍尔夫。当代：伊恩·麦克尤恩等。了解文学如何反映社会变迁。', en: 'Understand English literary tradition. Old English: Beowulf. Medieval: Chaucers Canterbury Tales. Renaissance: Shakespeare. Romantic: Wordsworth, Keats, Shelley. Victorian: Dickens, Brontë sisters. Modernist: T.S. Eliot, Virginia Woolf. Contemporary: Ian McEwan etc. Understand how literature reflects social change.', age: '13-14' },
      { topic: '描述性写作进阶', zh: '提高描述性写作水平。感官细节：视觉、听觉、嗅觉、触觉、味觉的精确描写。比喻语言：创造新颖的比喻而非陈词滥调。动词选择：用精确的动词代替泛泛的词（"疾冲"而非"走"）。节奏变化：长短句交替创造节奏感。写一篇500-700字的描述性文章，展现高级写作技巧。', en: 'Improve descriptive writing. Sensory details: precise descriptions of sight, sound, smell, touch, taste. Figurative language: create fresh metaphors rather than clichés. Verb choice: precise verbs over generic ones. Rhythm variation: alternate long and short sentences. Write a 500-700 word descriptive piece demonstrating advanced writing techniques.', age: '12-14' },
      { topic: '语法进阶：虚拟语气', zh: '学习虚拟语气的用法。与现在事实相反：If I were rich, I would travel the world. 与过去事实相反：If I had studied harder, I would have passed. 与将来可能相反：If it should rain, we would cancel. Wish后面的虚拟：I wish I were taller (现在), I wish I had studied (过去). 了解虚拟语气表达假设、愿望和与事实相反的情况。', en: 'Learn the subjunctive mood. Contrary to present: If I were rich, I would travel. Contrary to past: If I had studied harder, I would have passed. Contrary to future: If it should rain, we would cancel. After wish: I wish I were taller (present), I wish I had studied (past). Understand subjunctive for hypotheticals, wishes, and counterfactuals.', age: '13-14' },
      { topic: '词汇和词源学', zh: '学习词汇和词源学。词根：dict=说（dictate, dictionary, predict）；spect=看（inspect, spectator, perspective）。前缀：anti-=反对, pre-=之前, sub-=下面。后缀：-tion=名词, -ous=形容词, -ify=动词。拉丁语和法语对英语词汇的影响：约60%的英语词汇来自拉丁语或法语。了解词源帮助记忆和理解词汇。', en: 'Learn vocabulary and etymology. Roots: dict=say (dictate, dictionary, predict); spect=look (inspect, spectator, perspective). Prefixes: anti-=against, pre-=before, sub-=under. Suffixes: -tion=noun, -ous=adjective, -ify=verb. Latin and French influence: ~60% of English vocabulary comes from Latin or French. Etymology helps memorize and understand vocabulary.', age: '12-14' },
      { topic: '阅读策略', zh: '学习高级阅读策略。预测：根据标题和首段预测内容。提问：在阅读前、中、后提出问题。可视化：在脑中形成画面。联系：将文本与自身经验、其他文本和世界联系。推断：读出言外之意。总结：用自己的话概括要点。评估：判断文本的质量和可信度。综合：整合多个来源的信息。', en: 'Learn advanced reading strategies. Predict: anticipate content from title and opening. Question: ask questions before, during, and after reading. Visualize: form mental images. Connect: relate text to self, other texts, and the world. Infer: read between the lines. Summarize: restate key points in own words. Evaluate: judge quality and credibility. Synthesize: integrate information from multiple sources.', age: '12-14' }
    ],

    science: [
      { topic: '原子和元素', zh: '学习原子和元素的知识。原子结构：原子核（质子+中子）+电子云。质子带正电，中子不带电，电子带负电。原子序数=质子数，质量数=质子数+中子数。元素周期表：按原子序数排列，同族元素化学性质相似。前20个元素：H, He, Li, Be, B, C, N, O, F, Ne, Na, Mg, Al, Si, P, S, Cl, Ar, K, Ca。了解元素符号和名称。', en: 'Learn about atoms and elements. Atomic structure: nucleus (protons + neutrons) + electron cloud. Protons positive, neutrons neutral, electrons negative. Atomic number=protons, mass number=protons+neutrons. Periodic table: arranged by atomic number, same group elements have similar properties. First 20 elements: H, He, Li, Be, B, C, N, O, F, Ne, Na, Mg, Al, Si, P, S, Cl, Ar, K, Ca.', age: '11-13' },
      { topic: '化学反应', zh: '学习化学反应的知识。化学方程式：用化学式表示反应。例如：2H₂+O₂→2H₂O。反应类型：化合（A+B→AB）、分解（AB→A+B）、置换（A+BC→AC+B）、复分解（AB+CD→AD+CB）。化学反应的特征：生成新物质、能量变化（放热或吸热）、可能产生气体或沉淀。配平化学方程式：两边各原子数相等。', en: 'Learn about chemical reactions. Chemical equations: 2H₂+O₂→2H₂O. Reaction types: synthesis (A+B→AB), decomposition (AB→A+B), displacement (A+BC→AC+B), double displacement (AB+CD→AD+CB). Characteristics: new substances formed, energy changes (exothermic or endothermic), possible gas or precipitate. Balancing equations: equal atoms on both sides.', age: '11-14' },
      { topic: '力和压力', zh: '学习力和压力的知识。力：F=ma（力=质量×加速度）。单位：牛顿(N)。重力：F=mg（g≈9.8m/s²）。压力=力÷面积，单位：帕斯卡(Pa)=N/m²。压强应用：为什么针容易刺入皮肤（面积小，压力大）？为什么雪鞋防止陷入雪中（面积大，压力小）？液体压力随深度增加。大气压力：约101325Pa。', en: 'Learn about forces and pressure. Force: F=ma. Unit: Newton (N). Weight: F=mg (g≈9.8m/s²). Pressure=Force÷Area, unit: Pascal (Pa)=N/m². Applications: why needles pierce easily (small area, high pressure); why snowshoes prevent sinking (large area, low pressure). Liquid pressure increases with depth. Atmospheric pressure: ~101325Pa.', age: '11-14' },
      { topic: '能量转换', zh: '学习能量转换的知识。能量守恒定律：能量既不会凭空产生，也不会凭空消失，只能从一种形式转化为另一种形式。常见能量形式：动能、势能、热能、电能、光能、化学能、声能。实例：电灯（电能→光能+热能）、汽车（化学能→动能+热能）、水力发电（势能→动能→电能）、太阳能电池（光能→电能）、植物光合作用（光能→化学能）。理解能量转换效率：有用能量/总输入能量×100%。', en: 'Learn about energy transformation. Law of conservation: energy cannot be created or destroyed, only transformed. Forms: kinetic, potential, thermal, electrical, light, chemical, sound. Examples: light bulb (electrical→light+heat), car (chemical→kinetic+heat), hydroelectric (potential→kinetic→electrical), solar cell (light→electrical), photosynthesis (light→chemical). Efficiency = useful energy/total input × 100%.', age: '11-14' },
      { topic: '生态系统与物质循环', zh: '学习生态系统和物质循环。生态系统组成：生产者（植物）、消费者（动物）、分解者（细菌真菌）。食物链：草→兔→狐→鹰。食物网：多条食物链交织。碳循环：光合作用吸收CO₂，呼吸作用释放CO₂，化石燃料燃烧释放CO₂。水循环：蒸发→凝结→降水→径流→蒸发。氮循环：固氮→硝化→同化→反硝化。理解人类活动对物质循环的影响。', en: 'Learn about ecosystems and material cycles. Ecosystem: producers (plants), consumers (animals), decomposers (bacteria, fungi). Food chain: grass→rabbit→fox→eagle. Food web: interconnected chains. Carbon cycle: photosynthesis absorbs CO₂, respiration releases CO₂, fossil fuels release CO₂. Water cycle: evaporation→condensation→precipitation→runoff→evaporation. Nitrogen cycle: fixation→nitrification→assimilation→denitrification. Human impact on cycles.', age: '11-14' },
      { topic: '遗传与进化', zh: '学习遗传和进化的知识。DNA：脱氧核糖核酸，双螺旋结构，携带遗传信息。基因：DNA上有遗传效应的片段。染色体：人类有23对（46条）。遗传规律：孟德尔分离定律和自由组合定律。显性与隐性性状。变异：基因突变、基因重组、染色体变异。进化论：达尔文自然选择学说——适者生存。证据：化石记录、比较解剖学、分子生物学。适应：长颈鹿长颈、保护色等。', en: 'Learn about genetics and evolution. DNA: double helix carrying genetic information. Genes: functional DNA segments. Chromosomes: humans have 23 pairs (46 total). Mendel: law of segregation and independent assortment. Dominant and recessive traits. Variation: mutation, recombination, chromosomal changes. Evolution: Darwin natural selection—survival of the fittest. Evidence: fossil record, comparative anatomy, molecular biology. Adaptations: giraffe neck, camouflage, etc.', age: '11-14' },
      { topic: '地球结构与板块构造', zh: '学习地球结构和板块构造。地球结构：地壳（5-70km）、地幔（2900km）、外核（液态）、内核（固态）。板块构造：岩石圈分为多个板块，漂浮在软流圈上。板块边界：汇聚型（形成山脉、海沟）、离散型（形成大洋中脊）、转换型（形成断层）。地震：板块运动释放能量产生地震波。火山：岩浆从地幔上升喷出。阿尔卑斯山：非洲板块与欧亚板块碰撞形成。', en: 'Learn about Earth structure and plate tectonics. Structure: crust (5-70km), mantle (2900km), outer core (liquid), inner core (solid). Plates: lithosphere divided into plates floating on asthenosphere. Boundaries: convergent (mountains, trenches), divergent (mid-ocean ridges), transform (faults). Earthquakes: energy release from plate movement. Volcanoes: magma rising from mantle. Alps: formed by African and Eurasian plate collision.', age: '11-14' },
      { topic: '声音与波动', zh: '学习声音和波动的知识。波的类型：横波（质点振动方向垂直于传播方向）和纵波（质点振动方向平行于传播方向）。声音是纵波，需要介质传播。声速：空气中约340m/s，水中约1500m/s，固体中更快。频率决定音调，振幅决定响度。人耳听觉范围：20Hz-20000Hz。超声波和次声波。多普勒效应：波源靠近时频率升高，远离时频率降低。回声和声学应用。', en: 'Learn about sound and waves. Wave types: transverse (perpendicular vibration) and longitudinal (parallel vibration). Sound is longitudinal, needs a medium. Speed: ~340m/s in air, ~1500m/s in water, faster in solids. Frequency determines pitch, amplitude determines loudness. Hearing range: 20Hz-20000Hz. Ultrasound and infrasound. Doppler effect: frequency increases as source approaches, decreases as it recedes. Echoes and acoustic applications.', age: '11-13' },
      { topic: '光与电磁波', zh: '学习光和电磁波的知识。电磁波谱：无线电波→微波→红外线→可见光→紫外线→X射线→γ射线。可见光：红橙黄绿蓝靛紫（波长700nm-400nm）。光的传播：直线传播、反射（入射角=反射角）、折射（斯涅尔定律）。透镜：凸透镜会聚光线，凹透镜发散光线。色散：白光通过棱镜分解为七色光。光的粒子性：光子，E=hf。激光的原理和应用。', en: 'Learn about light and electromagnetic waves. EM spectrum: radio→microwave→infrared→visible→UV→X-ray→gamma. Visible light: red to violet (700nm-400nm). Propagation: rectilinear, reflection (angle in=angle out), refraction (Snell law). Lenses: convex converges, concave diverges. Dispersion: white light splits through prism. Particle nature: photons, E=hf. Laser principles and applications.', age: '11-14' },
      { topic: '电与电路', zh: '学习电和电路的知识。电荷：正电荷和负电荷，同种相斥异种相吸。电流：电荷的定向移动，单位安培(A)。电压：电势差，驱动电流，单位伏特(V)。电阻：导体对电流的阻碍，单位欧姆(Ω)。欧姆定律：V=IR。串联电路：电流相同，电压分配。并联电路：电压相同，电流分配。电功率：P=VI=I²R=V²/R。安全用电：保险丝、接地、漏电保护。', en: 'Learn about electricity and circuits. Charge: positive and negative, like repels, unlike attracts. Current: directional charge flow, unit Ampere (A). Voltage: potential difference driving current, unit Volt (V). Resistance: opposition to current, unit Ohm (Ω). Ohm law: V=IR. Series: same current, voltage divides. Parallel: same voltage, current divides. Power: P=VI=I²R=V²/R. Electrical safety: fuses, grounding, RCD protection.', age: '11-14' },
      { topic: '细胞与生命过程', zh: '学习细胞和生命过程。细胞结构：细胞膜（控制物质进出）、细胞质（化学反应场所）、细胞核（含DNA，控制细胞活动）。植物细胞特有：细胞壁（支撑）、叶绿体（光合作用）、液泡（储存）。细胞分裂：有丝分裂（体细胞增殖）和减数分裂（产生生殖细胞）。组织→器官→系统→生物体。生命过程：营养、呼吸、排泄、反应、运动、繁殖、生长。', en: 'Learn about cells and life processes. Cell structure: membrane (controls entry/exit), cytoplasm (reactions), nucleus (DNA, controls activities). Plant-specific: cell wall (support), chloroplasts (photosynthesis), vacuole (storage). Division: mitosis (body cell reproduction) and meiosis (producing sex cells). Tissue→organ→system→organism. Life processes: nutrition, respiration, excretion, response, movement, reproduction, growth.', age: '11-13' },
      { topic: '人体系统', zh: '学习人体系统的知识。消化系统：口腔→食道→胃→小肠→大肠，消化酶分解食物。循环系统：心脏→动脉→毛细血管→静脉→心脏，运输氧气和营养。呼吸系统：鼻腔→气管→支气管→肺泡，气体交换。神经系统：大脑→脊髓→神经，传递信号。内分泌系统：激素调节生长代谢。泌尿系统：肾脏过滤血液产生尿液。免疫系统：白细胞抵御病原体。', en: 'Learn about human body systems. Digestive: mouth→esophagus→stomach→small intestine→large intestine, enzymes break down food. Circulatory: heart→arteries→capillaries→veins→heart, transports oxygen and nutrients. Respiratory: nose→trachea→bronchi→alveoli, gas exchange. Nervous: brain→spinal cord→nerves, signal transmission. Endocrine: hormones regulate growth and metabolism. Urinary: kidneys filter blood. Immune: white blood cells fight pathogens.', age: '11-14' },
      { topic: '天文学与宇宙', zh: '学习天文学和宇宙的知识。太阳系：八大行星——水星、金星、地球、火星、木星、土星、天王星、海王星。恒星：太阳是恒星，通过核聚变产生能量。银河系：约2000亿颗恒星组成的旋涡星系。宇宙：约138亿年前大爆炸诞生。光年：光走一年的距离（约9.46万亿公里）。月球：潮汐现象的原因。日食和月食。国际空间站。太空探索：从加加林到火星探测器。', en: 'Learn about astronomy and the universe. Solar system: 8 planets—Mercury, Venus, Earth, Mars, Jupiter, Saturn, Uranus, Neptune. Stars: Sun is a star, energy from nuclear fusion. Milky Way: spiral galaxy with ~200 billion stars. Universe: born ~13.8 billion years ago in Big Bang. Light-year: distance light travels in a year (~9.46 trillion km). Moon: causes tides. Solar and lunar eclipses. ISS. Space exploration: from Gagarin to Mars rovers.', age: '11-14' },
      { topic: '酸碱与中和反应', zh: '学习酸碱和中和反应。酸：pH<7，使石蕊变红，含H⁺离子。常见酸：盐酸HCl、硫酸H₂SO₄、醋酸CH₃COOH。碱：pH>7，使石蕊变蓝，含OH⁻离子。常见碱：氢氧化钠NaOH、氢氧化钙Ca(OH)₂。中和反应：酸+碱→盐+水。例如：HCl+NaOH→NaCl+H₂O。pH试纸和指示剂。酸雨：SO₂和NOx溶于水形成。生活中的酸碱：柠檬酸、小苏打、肥皂。', en: 'Learn about acids, bases, and neutralization. Acids: pH<7, turn litmus red, contain H⁺. Common: HCl, H₂SO₄, CH₃COOH. Bases: pH>7, turn litmus blue, contain OH⁻. Common: NaOH, Ca(OH)₂. Neutralization: acid+base→salt+water. Example: HCl+NaOH→NaCl+H₂O. pH paper and indicators. Acid rain: SO₂ and NOx dissolve in water. Everyday acids and bases: citric acid, baking soda, soap.', age: '11-14' },
      { topic: '运动与速度', zh: '学习运动和速度的知识。速度=距离÷时间，单位m/s。加速度=速度变化÷时间，单位m/s²。匀速运动：速度不变。变速运动：速度改变。距离-时间图：斜率=速度。速度-时间图：斜率=加速度，面积=距离。牛顿运动三定律：惯性定律、F=ma、作用力与反作用力。自由落体：g≈9.8m/s²。终端速度：空气阻力等于重力时。', en: 'Learn about motion and speed. Speed=distance÷time, unit m/s. Acceleration=velocity change÷time, unit m/s². Uniform motion: constant speed. Non-uniform: changing speed. Distance-time graph: slope=speed. Velocity-time graph: slope=acceleration, area=distance. Newton three laws: inertia, F=ma, action-reaction. Free fall: g≈9.8m/s². Terminal velocity: when air resistance equals weight.', age: '11-14' },
      { topic: '热与热传递', zh: '学习热和热传递的知识。温度：分子平均动能的量度，单位开尔文(K)或摄氏度(°C)。热传递方式：传导（固体中分子振动传递）、对流（流体中热上升冷下降）、辐射（电磁波传递，不需介质）。比热容：使1kg物质升高1°C所需热量。水的比热容大，调节气候。热膨胀：物体受热膨胀。物态变化：熔化、凝固、汽化、液化、升华、凝华。', en: 'Learn about heat and thermal transfer. Temperature: measure of average molecular kinetic energy, units Kelvin (K) or Celsius (°C). Transfer methods: conduction (molecular vibration in solids), convection (hot rises, cold sinks in fluids), radiation (EM waves, no medium needed). Specific heat capacity: heat to raise 1kg by 1°C. Water high capacity regulates climate. Thermal expansion. State changes: melting, freezing, vaporization, condensation, sublimation, deposition.', age: '11-13' },
      { topic: '环境与可持续发展', zh: '学习环境和可持续发展的知识。环境问题：全球变暖（CO₂等温室气体增加）、臭氧层破坏、酸雨、水污染、空气污染、土壤退化、生物多样性丧失。可持续发展：满足当代需求而不损害后代满足其需求的能力。可再生能源：太阳能、风能、水能、地热能。不可再生能源：煤炭、石油、天然气。碳足迹：个人或组织排放的温室气体总量。3R原则：减少(Reduce)、再利用(Reuse)、回收(Recycle)。', en: 'Learn about environment and sustainability. Issues: global warming (increased greenhouse gases), ozone depletion, acid rain, water/air pollution, soil degradation, biodiversity loss. Sustainable development: meeting present needs without compromising future generations. Renewable energy: solar, wind, hydro, geothermal. Non-renewable: coal, oil, natural gas. Carbon footprint: total greenhouse gas emissions. 3R principle: Reduce, Reuse, Recycle.', age: '11-14' },
      { topic: '微生物与疾病', zh: '学习微生物和疾病的知识。微生物类型：细菌（单细胞，有益如乳酸菌，有害如结核杆菌）、病毒（非细胞结构，需寄生，如流感病毒、新冠病毒）、真菌（酵母菌、霉菌）、原生动物（疟原虫）。传播途径：空气飞沫、接触传播、食物和水、媒介生物。免疫：天然免疫（皮肤、黏膜）和获得性免疫（疫苗、抗体）。抗生素：杀灭细菌但对病毒无效。抗药性问题。卫生习惯：洗手、消毒、食品安全。', en: 'Learn about microorganisms and disease. Types: bacteria (single-celled, useful like Lactobacillus, harmful like TB), viruses (non-cellular, parasitic, e.g. flu, COVID), fungi (yeast, mold), protozoa (malaria parasite). Transmission: airborne droplets, contact, food/water, vectors. Immunity: innate (skin, mucous) and acquired (vaccines, antibodies). Antibiotics: kill bacteria but not viruses. Antibiotic resistance. Hygiene: handwashing, disinfection, food safety.', age: '11-14' },
      { topic: '材料与性质', zh: '学习材料和性质的知识。材料分类：金属（导电、导热、有光泽、延展性）、非金属、聚合物（塑料、橡胶）、陶瓷、复合材料。金属特性：大多数常温固态（汞除外），良导体，有延展性。合金：两种或以上金属的混合物，如钢（铁+碳）、青铜（铜+锡）。聚合物：由单体重复连接而成，如聚乙烯、PVC。材料选择：根据用途选择合适材料，考虑强度、密度、导热性、耐腐蚀性等。', en: 'Learn about materials and properties. Classification: metals (conductive, shiny, malleable), non-metals, polymers (plastics, rubber), ceramics, composites. Metal properties: mostly solid at room temperature (except mercury), good conductors, malleable. Alloys: mixtures like steel (iron+carbon), bronze (copper+tin). Polymers: repeating monomers, e.g. polyethylene, PVC. Material selection: based on strength, density, conductivity, corrosion resistance for intended use.', age: '11-13' },
      { topic: '植物生物学', zh: '学习植物生物学的知识。光合作用：6CO₂+6H₂O→C₆H₁₂O₆+6O₂（光能+叶绿体）。叶片结构：表皮、叶肉（栅栏组织和海绵组织）、叶脉。蒸腾作用：水分从叶片蒸发，拉动水分上升。根：吸收水分和矿物质，根毛增大吸收面积。茎：运输水分（木质部）和有机物（韧皮部）。花：雄蕊（花药+花丝）、雌蕊（柱头+花柱+子房）。繁殖：传粉（自花/异花）、受精、种子散布。', en: 'Learn about plant biology. Photosynthesis: 6CO₂+6H₂O→C₆H₁₂O₆+6O₂ (light+chloroplasts). Leaf structure: epidermis, mesophyll (palisade and spongy), veins. Transpiration: water evaporates from leaves, pulling water up. Roots: absorb water and minerals, root hairs increase surface area. Stem: transports water (xylem) and organic compounds (phloem). Flower: stamen (anther+filament), pistil (stigma+style+ovary). Reproduction: pollination (self/cross), fertilization, seed dispersal.', age: '11-13' },
      { topic: '化学键与化合物', zh: '学习化学键和化合物的知识。离子键：金属失去电子，非金属得到电子，形成离子，静电吸引。例如NaCl：Na⁺和Cl⁻。共价键：原子间共享电子对。例如H₂O、CO₂。金属键：金属阳离子与自由电子之间的作用。化合物性质：离子化合物通常熔点高、溶于水、熔融导电。共价化合物：分子间作用力弱，熔点低。混合物与纯净物的区别。分离方法：蒸馏、过滤、色谱。', en: 'Learn about chemical bonds and compounds. Ionic bonds: metals lose electrons, non-metals gain, electrostatic attraction. E.g. NaCl: Na⁺ and Cl⁻. Covalent bonds: atoms share electron pairs. E.g. H₂O, CO₂. Metallic bonds: metal cations and free electrons. Compound properties: ionic—high melting point, water-soluble, conduct when molten. Covalent—weak intermolecular forces, low melting point. Mixtures vs pure substances. Separation: distillation, filtration, chromatography.', age: '12-14' },
      { topic: '气候与天气系统', zh: '学习气候和天气系统的知识。天气：短时间内大气的状态（温度、湿度、气压、风、降水）。气候：长期天气的平均状况。气压系统：高压（晴朗干燥）、低压（多云降雨）。锋面：冷锋（冷空气推进，短时强降水）、暖锋（暖空气爬升，持续降水）。全球风带：信风带、西风带、极地东风带。洋流影响气候：北大西洋暖流使西欧温和。温室效应：自然温室效应维持地球温度，人为加剧导致全球变暖。', en: 'Learn about climate and weather systems. Weather: short-term atmospheric conditions (temperature, humidity, pressure, wind, precipitation). Climate: long-term weather averages. Pressure systems: high (clear, dry), low (cloudy, rainy). Fronts: cold front (strong brief rain), warm front (prolonged rain). Global wind belts: trade winds, westerlies, polar easterlies. Ocean currents affect climate: North Atlantic Drift warms Western Europe. Greenhouse effect: natural maintains temperature, human-enhanced causes global warming.', age: '11-14' },
      { topic: '科学方法与实验设计', zh: '学习科学方法和实验设计。科学方法步骤：观察→提出问题→形成假说→设计实验→收集数据→分析结果→得出结论→交流发表。变量：自变量（人为改变）、因变量（测量结果）、控制变量（保持不变）。公平测试：只改变一个变量。实验设计：对照组、重复实验、样本量。数据呈现：表格、柱状图、折线图、散点图。误差分析：系统误差和随机误差。结论的可靠性和有效性。同行评审。', en: 'Learn about scientific method and experimental design. Steps: observe→question→hypothesis→experiment→collect data→analyze→conclude→communicate. Variables: independent (changed), dependent (measured), control (kept constant). Fair test: change only one variable. Design: control group, replication, sample size. Data presentation: tables, bar charts, line graphs, scatter plots. Error analysis: systematic and random errors. Reliability and validity of conclusions. Peer review.', age: '11-14' }
    ],

    history: [
      { topic: '古希腊文明', zh: '学习古希腊文明。雅典民主：公民大会投票决策，但妇女、奴隶和外邦人无权参与。斯巴达军事化社会：男孩7岁开始军事训练。希腊哲学：苏格拉底（问答法）、柏拉图（理想国）、亚里士多德（逻辑学）。奥林匹克运动会：公元前776年首次举办。希腊神话：宙斯、雅典娜、阿波罗。希腊文化对欧洲文明的深远影响：民主制度、哲学思想、建筑艺术、戏剧文学。', en: 'Learn about Ancient Greek civilization. Athenian democracy: citizens assembly voted, but women, slaves, foreigners excluded. Spartan militarism: boys trained from age 7. Philosophy: Socrates (Socratic method), Plato (Republic), Aristotle (logic). Olympics: first held 776 BC. Greek mythology: Zeus, Athena, Apollo. Greek influence on European civilization: democracy, philosophy, architecture, drama.', age: '11-13' },
      { topic: '古罗马文明', zh: '学习古罗马文明。罗马共和国：元老院、执政官、公民大会。罗马帝国：从奥古斯都到帝国分裂。罗马法：十二铜表法到查士丁尼法典，奠定欧洲法律基础。罗马工程：道路、水渠、竞技场、浴场。拉丁语：欧洲多种语言的根源。基督教：从被迫害到成为国教。罗马遗产：法律制度、工程技术、语言文字、政治制度对欧洲的持久影响。', en: 'Learn about Ancient Roman civilization. Republic: Senate, consuls, assemblies. Empire: from Augustus to division. Roman law: Twelve Tables to Justinian Code, foundation of European law. Engineering: roads, aqueducts, Colosseum, baths. Latin: root of European languages. Christianity: from persecution to state religion. Roman legacy: legal systems, engineering, language, political institutions lasting influence on Europe.', age: '11-13' },
      { topic: '中世纪欧洲', zh: '学习中世纪欧洲。封建制度：国王→领主→骑士→农奴，层层分封。城堡和庄园：领主居住的城堡，自给自足的庄园经济。基督教会：教皇权力巨大，修道院保存知识。十字军东征：1096-1291年，宗教名义下的军事远征。黑死病：1347-1351年，杀死欧洲约三分之一人口。百年战争：英法之间的冲突。中世纪文化：哥特式大教堂、骑士文学、大学兴起。', en: 'Learn about Medieval Europe. Feudalism: king→lord→knight→serf, hierarchical land grants. Castles and manors: lord castles, self-sufficient manor economy. Christian Church: papal power, monasteries preserved knowledge. Crusades: 1096-1291, military expeditions under religious banner. Black Death: 1347-1351, killed ~1/3 of Europe. Hundred Years War: England vs France. Culture: Gothic cathedrals, chivalric literature, rise of universities.', age: '11-13' },
      { topic: '维京时代', zh: '学习维京时代。维京人：来自斯堪的纳维亚的北欧航海者，约公元793-1066年。长船：维京人卓越的造船技术，既可航海又可逆流而上。探险：到达冰岛、格陵兰、北美洲（文兰）。维京社会：自由人、奴隶，议事会（Thing）做决策。维京神话：奥丁、托尔、洛基。维京影响：建立诺曼底公国、基辅罗斯，影响英国和俄罗斯的形成。维京人的贸易网络从拜占庭延伸到美洲。', en: 'Learn about the Viking Age. Vikings: Scandinavian seafarers, ~793-1066 AD. Longships: superior shipbuilding, seaworthy and river-navigable. Exploration: reached Iceland, Greenland, North America (Vinland). Society: free men, slaves, Thing assembly for decisions. Mythology: Odin, Thor, Loki. Impact: founded Normandy, Kievan Rus, influenced formation of England and Russia. Trade networks from Byzantium to America.', age: '11-13' },
      { topic: '文艺复兴', zh: '学习文艺复兴。时间：14-17世纪，从意大利佛罗伦萨开始。核心思想：人文主义，重视人的价值和尊严，复兴古希腊罗马文化。艺术巨匠：达芬奇（《蒙娜丽莎》）、米开朗基罗（《大卫》）、拉斐尔（《雅典学院》）。科学革命：哥白尼日心说、伽利略望远镜观测、古腾堡印刷术。文学：但丁《神曲》、莎士比亚戏剧。文艺复兴影响：从宗教中心转向人本主义，推动科学、艺术和思想解放。', en: 'Learn about the Renaissance. Period: 14th-17th century, began in Florence, Italy. Core: humanism, valuing human worth and dignity, reviving classical culture. Masters: Da Vinci (Mona Lisa), Michelangelo (David), Raphael (School of Athens). Scientific revolution: Copernicus heliocentrism, Galileo telescope, Gutenberg printing press. Literature: Dante Divine Comedy, Shakespeare plays. Impact: shift from religion-centered to humanism, advancing science, art, and intellectual freedom.', age: '11-14' },
      { topic: '宗教改革', zh: '学习宗教改革。1517年马丁·路德发表《九十五条论纲》，反对天主教会的赎罪券。新教派别：路德宗（德国）、加尔文宗（瑞士）、英国国教。反宗教改革：天主教会内部改革，耶稣会成立。宗教战争：法国胡格诺战争、三十年战争（1618-1648）。影响：基督教分裂为天主教和新教，促进宗教自由思想，削弱教皇权力，推动民族国家发展。《威斯特伐利亚和约》确立国家主权原则。', en: 'Learn about the Reformation. 1517 Martin Luther posted 95 Theses against indulgences. Protestant denominations: Lutheran (Germany), Calvinist (Switzerland), Anglican (England). Counter-Reformation: Catholic internal reform, Jesuits founded. Religious wars: French Wars of Religion, Thirty Years War (1618-1648). Impact: Christianity split into Catholic and Protestant, promoted religious freedom, weakened papal power, advanced nation-states. Peace of Westphalia established state sovereignty.', age: '11-14' },
      { topic: '大航海时代', zh: '学习大航海时代。15-17世纪欧洲航海家的探索。葡萄牙：亨利王子支持航海，达伽马到达印度（1498）。西班牙：哥伦布发现美洲（1492），麦哲伦环球航行（1519-1522）。原因：寻找新贸易路线、传播宗教、获取财富。哥伦布大交换：动植物、疾病在旧大陆和新大陆之间传播。殖民主义开始：西班牙和葡萄牙瓜分世界。对原住民的影响：疾病、奴役、文化毁灭。三角贸易和奴隶制。', en: 'Learn about the Age of Exploration. 15th-17th century European voyages. Portugal: Prince Henry supported navigation, da Gama reached India (1498). Spain: Columbus discovered Americas (1492), Magellan circumnavigated (1519-1522). Reasons: new trade routes, spread religion, acquire wealth. Columbian Exchange: plants, animals, diseases between Old and New Worlds. Colonialism began: Spain and Portugal divided the world. Impact on indigenous peoples: disease, enslavement, cultural destruction. Triangular trade and slavery.', age: '11-14' },
      { topic: '启蒙运动', zh: '学习启蒙运动。17-18世纪欧洲思想解放运动。核心：理性、自由、进步。思想家：洛克（天赋人权、社会契约）、伏尔泰（言论自由、宗教宽容）、孟德斯鸠（三权分立）、卢梭（人民主权）。百科全书派：狄德罗主编，传播知识。启蒙影响：推动美国独立和法国大革命，奠定现代民主制度基础。开明专制：普鲁士腓特烈大帝、俄国叶卡捷琳娜大帝。理性主义对科学和教育的推动。', en: 'Learn about the Enlightenment. 17th-18th century intellectual movement. Core: reason, liberty, progress. Thinkers: Locke (natural rights, social contract), Voltaire (free speech, religious tolerance), Montesquieu (separation of powers), Rousseau (popular sovereignty). Encyclopédistes: Diderot edited, spreading knowledge. Impact: drove American and French Revolutions, foundation of modern democracy. Enlightened absolutism: Frederick the Great, Catherine the Great. Rationalism advanced science and education.', age: '11-14' },
      { topic: '法国大革命', zh: '学习法国大革命。1789年爆发，原因：社会不平等（三个等级）、财政危机、启蒙思想影响。关键事件：攻占巴士底狱（7月14日）、人权宣言（自由平等博爱）、路易十六上断头台。激进阶段：雅各宾派和恐怖统治，罗伯斯庇尔。拿破仑崛起：从将军到皇帝。影响：推翻封建制度，传播民主自由理念，激发全欧洲的革命浪潮。《拿破仑法典》对现代法律的影响。', en: 'Learn about the French Revolution. Broke out 1789. Causes: social inequality (three estates), financial crisis, Enlightenment ideas. Key events: Storming of Bastille (July 14), Declaration of Rights of Man (liberty, equality, fraternity), Louis XVI guillotined. Radical phase: Jacobins and Reign of Terror, Robespierre. Napoleon rose: general to emperor. Impact: abolished feudalism, spread democratic ideals, inspired revolutions across Europe. Napoleonic Code influenced modern law.', age: '11-14' },
      { topic: '工业革命', zh: '学习工业革命。18世纪中叶从英国开始。关键发明：瓦特蒸汽机（1769）、珍妮纺纱机、蒸汽机车。工厂制度：取代手工作坊，工人集中生产。城市化：人口从农村涌入城市，工人阶级形成。社会问题：童工、长工时、恶劣环境。改革运动：工会、工厂法、教育改革。工业革命扩散：从英国到欧洲大陆和北美。影响：改变生产方式、社会结构、生活方式，奠定现代工业社会基础。', en: 'Learn about the Industrial Revolution. Began mid-18th century in Britain. Key inventions: Watt steam engine (1769), spinning jenny, steam locomotive. Factory system: replaced artisan workshops, concentrated workers. Urbanization: rural-to-urban migration, working class formed. Social issues: child labor, long hours, poor conditions. Reform movements: trade unions, Factory Acts, education reform. Spread: from Britain to continental Europe and North America. Impact: transformed production, social structure, daily life, foundation of modern industrial society.', age: '11-14' },
      { topic: '拿破仑时代', zh: '学习拿破仑时代。拿破仑·波拿巴：从科西嘉岛到法国皇帝。军事天才：奥斯特里茨战役、征服欧洲大部分地区。拿破仑法典：法律面前人人平等、私有财产保护、政教分离，影响全球法律体系。大陆封锁：试图经济制裁英国。败退：1812年入侵俄国失败，莱比锡战役，滑铁卢战役（1815）。维也纳会议：重新划分欧洲版图，恢复君主制。拿破仑遗产：传播革命理念、法律改革、民族主义觉醒。', en: 'Learn about the Napoleonic Era. Napoleon Bonaparte: from Corsica to Emperor. Military genius: Austerlitz, conquered much of Europe. Napoleonic Code: equality before law, property rights, secular state, influenced legal systems worldwide. Continental System: economic blockade of Britain. Decline: 1812 Russian invasion failed, Leipzig, Waterloo (1815). Congress of Vienna: redrew European map, restored monarchies. Legacy: spread revolutionary ideals, legal reform, awakened nationalism.', age: '11-14' },
      { topic: '第一次世界大战', zh: '学习第一次世界大战。1914-1918年。原因：帝国主义竞争、军备竞赛、同盟体系（三国协约vs三国同盟）、民族主义。导火索：萨拉热窝事件（1914年6月28日）。战争特点：堑壕战、毒气、坦克、飞机。重大战役：索姆河战役、凡尔登战役。俄国革命（1917）和退出战争。美国参战（1917）。结束：《凡尔赛条约》（1919），德国承担战争责任和赔款。影响：四大帝国崩溃，国际联盟成立，为二战埋下伏笔。', en: 'Learn about World War I. 1914-1918. Causes: imperialist competition, arms race, alliance systems (Triple Entente vs Triple Alliance), nationalism. Trigger: Sarajevo assassination (June 28, 1914). Features: trench warfare, poison gas, tanks, aircraft. Major battles: Somme, Verdun. Russian Revolution (1917) and withdrawal. US entry (1917). End: Treaty of Versailles (1919), Germany held responsible and paid reparations. Impact: four empires collapsed, League of Nations formed, set stage for WWII.', age: '11-14' },
      { topic: '俄国革命', zh: '学习俄国革命。1917年两次革命。二月革命：推翻沙皇尼古拉二世，建立临时政府。十月革命：布尔什维克在列宁领导下夺取政权。苏维埃政权：土地归农民、工厂归工人、退出战争。内战：红军（布尔什维克）vs白军，1922年苏联成立。斯大林时期：五年计划、农业集体化、大清洗。冷战起源：意识形态对立。苏联影响：社会主义运动、太空竞赛、东欧卫星国。1991年苏联解体。', en: 'Learn about the Russian Revolution. Two revolutions in 1917. February Revolution: overthrew Tsar Nicholas II, established Provisional Government. October Revolution: Bolsheviks seized power under Lenin. Soviet regime: land to peasants, factories to workers, withdrew from war. Civil War: Red Army (Bolsheviks) vs White Army, USSR formed 1922. Stalin era: Five-Year Plans, collectivization, Great Purge. Cold War origins: ideological opposition. Soviet influence: socialist movements, space race, Eastern European satellite states. USSR dissolved 1991.', age: '11-14' },
      { topic: '第二次世界大战', zh: '学习第二次世界大战。1939-1945年。原因：凡尔赛条约的不公、经济大萧条、法西斯主义崛起。轴心国：德国、意大利、日本。同盟国：英国、苏联、美国、法国等。重大事件：闪电战、不列颠空战、巴巴罗萨行动、珍珠港事件、斯大林格勒战役、诺曼底登陆。大屠杀：纳粹杀害约600万犹太人。原子弹：广岛和长崎。结束：1945年5月德国投降，8月日本投降。影响：约7000万人死亡，联合国成立，冷战开始。', en: 'Learn about World War II. 1939-1945. Causes: unfair Versailles Treaty, Great Depression, rise of fascism. Axis: Germany, Italy, Japan. Allies: Britain, USSR, USA, France, etc. Major events: Blitzkrieg, Battle of Britain, Operation Barbarossa, Pearl Harbor, Stalingrad, D-Day. Holocaust: Nazis murdered ~6 million Jews. Atomic bombs: Hiroshima and Nagasaki. End: Germany surrendered May 1945, Japan August 1945. Impact: ~70 million deaths, UN founded, Cold War began.', age: '11-14' },
      { topic: '冷战', zh: '学习冷战。1947-1991年，美苏两大阵营对抗。铁幕：丘吉尔描述欧洲分裂。柏林墙（1961-1989）：东西德分裂的象征。北约vs华约：军事对峙。核军备竞赛：相互确保毁灭（MAD）。代理人战争：朝鲜战争、越南战争、阿富汗战争。太空竞赛：斯普特尼克到阿波罗登月。古巴导弹危机（1962）：最接近核战争的时刻。结束：1989年柏林墙倒塌，1991年苏联解体。冷战遗产：地缘政治格局、核武器扩散。', en: 'Learn about the Cold War. 1947-1991, US vs Soviet bloc confrontation. Iron Curtain: Churchill described divided Europe. Berlin Wall (1961-1989): symbol of divided Germany. NATO vs Warsaw Pact: military standoff. Nuclear arms race: Mutually Assured Destruction (MAD). Proxy wars: Korea, Vietnam, Afghanistan. Space Race: Sputnik to Apollo moon landing. Cuban Missile Crisis (1962): closest to nuclear war. End: Berlin Wall fell 1989, USSR dissolved 1991. Legacy: geopolitical landscape, nuclear proliferation.', age: '11-14' },
      { topic: '欧盟的形成', zh: '学习欧盟的形成。起源：1951年欧洲煤钢共同体，舒曼计划。发展：1957年罗马条约建立欧洲经济共同体。扩大：从6国到27国。里程碑：1986年单一欧洲法案、1992年马斯特里赫特条约（欧盟成立）、1999年欧元启动、2004年东扩。核心原则：自由流动（人员、货物、资本、服务）。英国脱欧（2020）。欧盟机构：欧洲议会、欧盟委员会、欧洲法院。挑战：主权让渡、民主赤字、难民危机、经济不平等。', en: 'Learn about the formation of the EU. Origins: 1951 European Coal and Steel Community, Schuman Plan. Development: 1957 Treaty of Rome established EEC. Expansion: from 6 to 27 members. Milestones: 1986 Single European Act, 1992 Maastricht Treaty (EU founded), 1999 Euro launched, 2004 Eastern enlargement. Core: free movement (people, goods, capital, services). Brexit (2020). Institutions: European Parliament, Commission, Court of Justice. Challenges: sovereignty, democratic deficit, refugee crisis, economic inequality.', age: '11-14' },
      { topic: '民权运动', zh: '学习民权运动。美国民权运动：1950s-1960s，反对种族隔离和歧视。马丁·路德·金：非暴力抗议、《我有一个梦想》演讲。罗莎·帕克斯：拒绝让座引发蒙哥马利公车抵制。1964年民权法案：禁止种族歧视。南非反种族隔离：曼德拉被监禁27年，1994年成为总统。女性权利：选举权运动、平等薪酬。LGBTQ+权利：石墙暴动（1969）、同性婚姻合法化。人权宣言（1948）：联合国通过。', en: 'Learn about civil rights movements. US Civil Rights: 1950s-1960s, against racial segregation and discrimination. Martin Luther King Jr: nonviolent protest, "I Have a Dream" speech. Rosa Parks: refused to give up seat, Montgomery Bus Boycott. 1964 Civil Rights Act: banned racial discrimination. South Africa anti-apartheid: Mandela imprisoned 27 years, president 1994. Women rights: suffrage movement, equal pay. LGBTQ+ rights: Stonewall riots (1969), marriage equality. Universal Declaration of Human Rights (1948).', age: '11-14' },
      { topic: '十字军东征', zh: '学习十字军东征。1096-1291年，欧洲基督教徒对近东的军事远征。第一次十字军：1099年攻占耶路撒冷，建立十字军国家。萨拉丁：穆斯林领袖，1187年夺回耶路撒冷。第四次十字军：1204年转而攻占君士坦丁堡。儿童十字军：1212年，悲惨结局。影响：促进东西方文化交流，引入阿拉伯数学和医学知识，削弱封建制度，推动商业发展，加深基督教和伊斯兰教之间的历史裂痕。', en: 'Learn about the Crusades. 1096-1291, European Christian military expeditions to the Near East. First Crusade: captured Jerusalem 1099, established Crusader states. Saladin: Muslim leader, recaptured Jerusalem 1187. Fourth Crusade: sacked Constantinople 1204 instead. Children Crusade: 1212, tragic outcome. Impact: promoted East-West cultural exchange, introduced Arabic mathematics and medicine, weakened feudalism, advanced commerce, deepened Christian-Muslim historical divide.', age: '11-13' },
      { topic: '全球化与现代世界', zh: '学习全球化和现代世界。全球化：经济、文化、政治的全球互联。跨国公司：在全球范围生产和销售。互联网：信息即时传播，改变沟通方式。全球挑战：气候变化、传染病、恐怖主义、贫富差距。国际组织：联合国、世界贸易组织、世界卫生组织。文化全球化：英语作为国际语言，流行文化全球传播。反全球化运动：保护本土文化和经济。数字革命：人工智能、社交媒体、电子商务改变世界。', en: 'Learn about globalization and the modern world. Globalization: economic, cultural, political interconnection. Multinational corporations: produce and sell globally. Internet: instant information, transformed communication. Global challenges: climate change, pandemics, terrorism, inequality. International organizations: UN, WTO, WHO. Cultural globalization: English as lingua franca, pop culture spreads worldwide. Anti-globalization: protecting local culture and economy. Digital revolution: AI, social media, e-commerce transforming the world.', age: '11-14' }
    ],

    geography: [
      { topic: '全球发展差异', zh: '学习全球发展差异。发达国家与发展中国家：GDP、人均收入、识字率、预期寿命等指标差异。HDI（人类发展指数）：综合衡量健康、教育和生活水平。发展不平衡的原因：历史殖民、地理条件、政治制度、教育水平。南北差距：北半球发达国家与南半球发展中国家的差异。案例研究：德国vs尼日尔，英国vs孟加拉国。公平贸易：帮助发展中国家获得合理贸易条件。国际援助：双边和多边援助。', en: 'Learn about global development gaps. Developed vs developing: differences in GDP, income, literacy, life expectancy. HDI: measures health, education, living standards. Causes of inequality: colonialism, geography, politics, education. North-South divide: differences between Northern and Southern hemispheres. Case studies: Germany vs Niger, UK vs Bangladesh. Fair trade: helping developing countries get fair trade terms. International aid: bilateral and multilateral assistance.', age: '11-14' },
      { topic: '生态系统与生物群系', zh: '学习生态系统和生物群系。生物群系：根据气候和植被划分的大区域。热带雨林：高温多雨，生物多样性最丰富，位于赤道附近。沙漠：降水稀少，动植物适应干旱。温带落叶林：四季分明，欧洲常见。苔原：寒冷，永久冻土，矮小植被。草原：分为热带稀树草原和温带草原。地中海气候：夏季干热，冬季温湿。每个生物群系的气候特征、典型动植物和人类影响。', en: 'Learn about ecosystems and biomes. Biomes: large areas classified by climate and vegetation. Tropical rainforest: hot, wet, most biodiverse, near equator. Desert: low rainfall, adapted organisms. Temperate deciduous forest: four seasons, common in Europe. Tundra: cold, permafrost, low vegetation. Grassland: tropical savanna and temperate steppe. Mediterranean: dry hot summers, mild wet winters. Climate, typical flora/fauna, and human impact for each biome.', age: '11-14' },
      { topic: '资源管理', zh: '学习资源管理。可再生资源：太阳能、风能、水能、生物质能，可持续利用。不可再生资源：煤炭、石油、天然气、矿产，有限且不可再生。水资源管理：淡水仅占地球水2.5%，分布不均。水资源冲突：中东、尼罗河流域。能源转型：从化石燃料到可再生能源。德国Energiewende能源转型政策。资源回收：减少浪费，循环利用。可持续消费：减少资源消耗，选择环保产品。资源公平分配的全球挑战。', en: 'Learn about resource management. Renewable: solar, wind, hydro, biomass, sustainable use. Non-renewable: coal, oil, natural gas, minerals, finite. Water management: freshwater only 2.5% of Earth water, unevenly distributed. Water conflicts: Middle East, Nile basin. Energy transition: from fossil fuels to renewables. Germany Energiewende policy. Resource recycling: reduce waste, reuse materials. Sustainable consumption: reduce resource use, choose eco-friendly products. Global challenge of fair resource distribution.', age: '11-14' },
      { topic: '城市化', zh: '学习城市化。城市化：人口从农村向城市转移。全球趋势：2007年城市人口首次超过农村。发达国家城市化：伦敦、巴黎、柏林的发展历程。发展中国家城市化：快速但缺乏规划，形成贫民窟。城市化问题：住房短缺、交通拥堵、空气污染、水资源压力、垃圾处理。城市可持续规划：绿色建筑、公共交通、城市绿化、废物管理。智慧城市：利用技术改善城市服务。逆城市化：部分人从城市迁回乡村。', en: 'Learn about urbanization. Urbanization: rural-to-urban population shift. Global trend: 2007 urban population first exceeded rural. Developed world: London, Paris, Berlin development. Developing world: rapid but unplanned, slums formed. Urban issues: housing shortage, traffic, air pollution, water stress, waste. Sustainable planning: green buildings, public transport, urban green spaces, waste management. Smart cities: using technology to improve services. Counter-urbanization: some moving back to rural areas.', age: '11-14' },
      { topic: '气候变化', zh: '学习气候变化。温室效应：CO₂、CH₄、N₂O等温室气体 trapping热量。全球变暖：工业革命以来温度上升约1.1°C。原因：化石燃料燃烧、森林砍伐、农业排放。影响：海平面上升、极端天气增加、冰川融化、生态系统破坏、粮食安全威胁。巴黎协定：限制升温1.5°C目标。减缓措施：减少排放、碳捕获、可再生能源。适应措施：防洪、耐旱作物、城市规划。碳足迹计算和减排行动。', en: 'Learn about climate change. Greenhouse effect: CO₂, CH₄, N₂O trap heat. Global warming: ~1.1°C rise since Industrial Revolution. Causes: fossil fuel burning, deforestation, agriculture. Impacts: sea level rise, extreme weather, glacier melting, ecosystem damage, food security threats. Paris Agreement: limit warming to 1.5°C. Mitigation: reduce emissions, carbon capture, renewable energy. Adaptation: flood defenses, drought-resistant crops, urban planning. Carbon footprint calculation and reduction actions.', age: '11-14' },
      { topic: '板块构造与地震火山', zh: '学习板块构造、地震和火山。板块构造理论：地球岩石圈由多个板块组成。板块边界类型：汇聚型（喜马拉雅山、安第斯山）、离散型（大西洋中脊）、转换型（圣安德烈斯断层）。地震：板块运动释放能量，里氏震级衡量。环太平洋火山带：全球75%火山和90%地震。欧洲地震带：意大利、希腊、土耳其。火山类型：盾状火山、层状火山、火山穹丘。地震和火山的监测与预警。防灾减灾措施。', en: 'Learn about plate tectonics, earthquakes, and volcanoes. Plate tectonics: lithosphere divided into plates. Boundary types: convergent (Himalayas, Andes), divergent (Mid-Atlantic Ridge), transform (San Andreas). Earthquakes: energy release, Richter scale. Pacific Ring of Fire: 75% volcanoes, 90% earthquakes. European seismic zone: Italy, Greece, Turkey. Volcano types: shield, stratovolcano, lava dome. Monitoring and early warning. Disaster prevention and mitigation measures.', age: '11-14' },
      { topic: '河流与流域', zh: '学习河流和流域。河流系统：上游（侵蚀为主，V型谷）、中游（搬运为主，曲流）、下游（沉积为主，三角洲）。流域：河流集水区域，分水岭分隔不同流域。欧洲主要河流：多瑙河（流经10国）、莱茵河（欧洲航运要道）、塞纳河、泰晤士河。河流侵蚀：水力作用、磨蚀作用、溶蚀作用。河流沉积：冲积扇、泛滥平原、三角洲。人类与河流：防洪、灌溉、水力发电、航运。河流污染和治理。', en: 'Learn about rivers and drainage basins. River system: upper (erosion, V-valleys), middle (transportation, meanders), lower (deposition, deltas). Drainage basin: catchment area, watershed divides basins. Major European rivers: Danube (10 countries), Rhine (key shipping route), Seine, Thames. Erosion: hydraulic action, abrasion, solution. Deposition: alluvial fans, floodplains, deltas. Humans and rivers: flood control, irrigation, hydroelectric, navigation. River pollution and restoration.', age: '11-14' },
      { topic: '人口地理', zh: '学习人口地理。世界人口：约80亿，分布极不均匀。人口密度：每平方公里人口数，受气候、地形、资源影响。人口增长：发展中国家快速增长，发达国家增长缓慢甚至负增长。人口结构：年龄金字塔反映人口特征。人口迁移：经济移民、难民、城市化迁移。欧洲人口问题：老龄化、低出生率、移民政策。人口政策：中国计划生育、法国鼓励生育。人口与资源的关系。人口承载力概念。', en: 'Learn about population geography. World population: ~8 billion, unevenly distributed. Population density: people per km², affected by climate, terrain, resources. Growth: rapid in developing countries, slow or negative in developed. Structure: age pyramids reflect demographics. Migration: economic migrants, refugees, urbanization. European issues: aging, low birth rates, immigration policy. Population policies: China family planning, France pro-natalist. Population-resource relationship. Carrying capacity concept.', age: '11-14' },
      { topic: '经济地理', zh: '学习经济地理。经济部门：第一产业（农业、矿业）、第二产业（制造业）、第三产业（服务业）、第四产业（信息技术）。全球化：跨国公司、国际分工、供应链。工业区位：原料、市场、劳动力、交通、政策。欧洲经济：欧盟单一市场、欧元区。经济不平等：核心-边缘模型，欧洲南北差距。自由贸易vs保护主义。新兴经济体：中国、印度、巴西。数字经济：电子商务、远程工作、数字鸿沟。', en: 'Learn about economic geography. Sectors: primary (agriculture, mining), secondary (manufacturing), tertiary (services), quaternary (IT). Globalization: multinationals, international division of labor, supply chains. Industrial location: raw materials, market, labor, transport, policy. European economy: EU single market, Eurozone. Inequality: core-periphery model, North-South European gap. Free trade vs protectionism. Emerging economies: China, India, Brazil. Digital economy: e-commerce, remote work, digital divide.', age: '11-14' },
      { topic: '海洋地理', zh: '学习海洋地理。海洋覆盖地球71%面积。大洋：太平洋、大西洋、印度洋、北冰洋、南大洋。洋流：表层洋流（风驱动）和深层洋流（密度驱动）。北大西洋暖流：使西欧气候温和。潮汐：月球和太阳引力引起。海洋资源：渔业、石油天然气、矿产、可再生能源。海洋污染：塑料垃圾、石油泄漏、化学污染。海洋酸化：CO₂溶于海水。海洋保护：海洋保护区、可持续渔业。欧洲海岸线：地中海、北海、波罗的海。', en: 'Learn about ocean geography. Oceans cover 71% of Earth. Oceans: Pacific, Atlantic, Indian, Arctic, Southern. Currents: surface (wind-driven) and deep (density-driven). North Atlantic Drift: warms Western Europe. Tides: caused by Moon and Sun gravity. Resources: fisheries, oil/gas, minerals, renewable energy. Pollution: plastic, oil spills, chemicals. Acidification: CO₂ dissolving in seawater. Conservation: marine protected areas, sustainable fishing. European coastlines: Mediterranean, North Sea, Baltic Sea.', age: '11-14' },
      { topic: '冰川与冰盖', zh: '学习冰川和冰盖。冰川：由积雪压实形成的大冰体，缓慢流动。冰川类型：山地冰川（阿尔卑斯山）、大陆冰盖（格陵兰、南极）。冰川侵蚀：U型谷、冰斗、峡湾（挪威）。冰川沉积：冰碛、鼓丘。冰河时代：最近一次约1万年前结束。现代冰川退缩：全球变暖导致冰川快速消融。海平面上升：冰川和冰盖融化是主要贡献者。冰川水资源：欧洲许多河流源于冰川融水。永久冻土融化问题。', en: 'Learn about glaciers and ice sheets. Glaciers: large ice bodies from compressed snow, flowing slowly. Types: mountain glaciers (Alps), continental ice sheets (Greenland, Antarctica). Erosion: U-valleys, cirques, fjords (Norway). Deposition: moraines, drumlins. Ice ages: last one ended ~10,000 years ago. Modern retreat: global warming causing rapid melting. Sea level rise: melting glaciers and ice sheets major contributors. Glacial water: many European rivers originate from glacial meltwater. Permafrost thawing issues.', age: '11-14' },
      { topic: '沙漠与干旱区', zh: '学习沙漠和干旱区。沙漠定义：年降水量少于250mm。热带沙漠：撒哈拉（最大）、阿拉伯，受副热带高压控制。温带沙漠：戈壁，深居内陆。沙漠特征：昼夜温差大、植被稀少、风力作用强。绿洲：沙漠中有水源的地方。荒漠化：土地退化为沙漠状，撒赫尔地区严重。原因：过度放牧、过度耕作、气候变化。防治措施：植树造林、节水灌溉、可持续放牧。太阳能利用：沙漠日照丰富。', en: 'Learn about deserts and arid regions. Definition: annual rainfall below 250mm. Tropical deserts: Sahara (largest), Arabian, under subtropical high pressure. Temperate deserts: Gobi, deep inland. Features: large temperature range, sparse vegetation, strong wind action. Oases: water sources in deserts. Desertification: land degrading to desert-like conditions, severe in Sahel. Causes: overgrazing, overcultivation, climate change. Prevention: afforestation, water-saving irrigation, sustainable grazing. Solar energy: abundant sunshine in deserts.', age: '11-14' },
      { topic: '热带雨林', zh: '学习热带雨林。分布：赤道附近，亚马逊、刚果、东南亚。气候：高温多雨，年降水量2000mm以上，无旱季。结构： emergent层（40m+）、树冠层（25-35m）、下层（5-20m）、灌木层、地面层。生物多样性：占地球50%以上物种。雨林价值：碳储存、氧气生产、药物来源、生物多样性。森林砍伐：每分钟损失约20个足球场面积。原因：伐木、牧场、种植园。保护措施：可持续林业、保护区、REDD+计划。', en: 'Learn about tropical rainforests. Distribution: near equator, Amazon, Congo, Southeast Asia. Climate: hot, wet, 2000mm+ annual rainfall, no dry season. Structure: emergent (40m+), canopy (25-35m), understory (5-20m), shrub, forest floor. Biodiversity: over 50% of Earth species. Value: carbon storage, oxygen, medicine, biodiversity. Deforestation: losing ~20 football pitches per minute. Causes: logging, ranching, plantations. Protection: sustainable forestry, reserves, REDD+ program.', age: '11-14' },
      { topic: '欧洲地理', zh: '学习欧洲地理。位置：亚欧大陆西部，北临北冰洋，西临大西洋，南临地中海。主要半岛：斯堪的纳维亚、伊比利亚、亚平宁、巴尔干。主要山脉：阿尔卑斯、比利牛斯、喀尔巴阡、斯堪的纳维亚山脉。主要平原：北欧平原、东欧平原。主要河流：伏尔加河、多瑙河、莱茵河。气候类型：海洋性（西欧）、大陆性（东欧）、地中海（南欧）、极地（北欧）。欧盟27国地理。欧洲地理多样性对历史和文化的影响。', en: 'Learn about European geography. Location: western Eurasia, Arctic Ocean to north, Atlantic to west, Mediterranean to south. Peninsulas: Scandinavian, Iberian, Italian, Balkan. Mountains: Alps, Pyrenees, Carpathians, Scandinavian range. Plains: North European, East European. Rivers: Volga, Danube, Rhine. Climates: maritime (Western), continental (Eastern), Mediterranean (Southern), polar (Northern). EU 27 countries geography. Geographic diversity influence on history and culture.', age: '11-14' },
      { topic: '全球化与贸易', zh: '学习全球化与贸易。国际贸易：国家间商品和服务交换。比较优势：各国生产自己最擅长的产品。贸易组织：WTO制定规则、EU促进内部贸易。供应链：原材料→生产→运输→销售，跨越多国。贸易不平衡：出口vs进口差额。贸易壁垒：关税、配额、非关税壁垒。公平贸易：确保发展中国家生产者获得合理价格。全球化争议：就业转移、文化同质化、环境问题。英国脱欧对贸易的影响。', en: 'Learn about globalization and trade. International trade: exchange of goods and services between countries. Comparative advantage: countries produce what they do best. Organizations: WTO sets rules, EU promotes internal trade. Supply chains: raw materials→production→transport→sales across countries. Trade imbalance: export vs import difference. Barriers: tariffs, quotas, non-tariff barriers. Fair trade: ensuring developing country producers get fair prices. Globalization debates: job displacement, cultural homogenization, environment. Brexit impact on trade.', age: '11-14' },
      { topic: '自然灾害', zh: '学习自然灾害。自然灾害类型：地质灾害（地震、火山、滑坡）、气象灾害（飓风、洪水、干旱）、生物灾害（蝗灾、疫病）。欧洲常见灾害：洪水（莱茵河、多瑙河）、热浪（2003年欧洲热浪）、地震（意大利、希腊）。灾害影响：人员伤亡、经济损失、基础设施破坏。防灾：预警系统、建筑规范、应急预案。灾后重建：恢复基础设施、心理援助、经济恢复。保险和风险管理。气候变化加剧极端天气事件。', en: 'Learn about natural hazards. Types: geological (earthquakes, volcanoes, landslides), meteorological (hurricanes, floods, droughts), biological (locusts, epidemics). European hazards: flooding (Rhine, Danube), heatwaves (2003 European heatwave), earthquakes (Italy, Greece). Impacts: casualties, economic losses, infrastructure damage. Prevention: early warning, building codes, emergency plans. Recovery: infrastructure restoration, psychological support, economic recovery. Insurance and risk management. Climate change intensifying extreme weather events.', age: '11-14' },
      { topic: '可持续发展', zh: '学习可持续发展。定义：满足当代需求而不损害后代满足需求的能力。三大支柱：经济可持续、社会可持续、环境可持续。联合国可持续发展目标（SDGs）：17个目标，包括消除贫困、清洁能源、气候行动等。可持续城市：绿色交通、节能建筑、废物管理。可持续农业：有机农业、精准农业、减少化肥农药。循环经济：减少、再利用、回收、再制造。个人行动：节能、减少浪费、绿色消费。欧洲绿色协议。', en: 'Learn about sustainable development. Definition: meeting present needs without compromising future generations. Three pillars: economic, social, environmental sustainability. UN SDGs: 17 goals including no poverty, clean energy, climate action. Sustainable cities: green transport, energy-efficient buildings, waste management. Sustainable agriculture: organic, precision farming, reduced chemicals. Circular economy: reduce, reuse, recycle, remanufacture. Individual actions: energy saving, waste reduction, green consumption. European Green Deal.', age: '11-14' },
      { topic: '农业地理', zh: '学习农业地理。农业类型：自给农业（小规模、多样种植）vs商业农业（大规模、专业化）。欧洲农业：法国小麦和葡萄、荷兰花卉和乳业、西班牙蔬果、意大利橄榄和葡萄酒。农业革命：从传统到机械化到精准农业。绿色革命：高产品种、化肥、灌溉。有机农业：不用化学农药和化肥。农业问题：土壤退化、水资源消耗、生物多样性减少、农药污染。欧盟共同农业政策（CAP）。城市农业和垂直农场。', en: 'Learn about agricultural geography. Types: subsistence (small-scale, diverse) vs commercial (large-scale, specialized). European agriculture: French wheat and grapes, Dutch flowers and dairy, Spanish fruits and vegetables, Italian olives and wine. Revolution: traditional→mechanized→precision farming. Green Revolution: high-yield varieties, fertilizers, irrigation. Organic farming: no synthetic pesticides or fertilizers. Issues: soil degradation, water consumption, biodiversity loss, pesticide pollution. EU Common Agricultural Policy (CAP). Urban farming and vertical farms.', age: '11-14' },
      { topic: '能源与资源', zh: '学习能源和资源。能源类型：化石能源（煤、石油、天然气）、核能、可再生能源。欧洲能源结构：法国以核能为主、德国转型可再生能源、挪威水电丰富、丹麦风能领先。能源安全：减少对进口依赖。能源转型：从化石燃料到可再生能源的挑战。关键矿产：锂、钴、稀土，用于电池和电子产品。资源冲突：水资源、矿产资源的国际争端。能源效率：减少浪费，提高利用率。欧盟能源政策。', en: 'Learn about energy and resources. Types: fossil (coal, oil, gas), nuclear, renewable. European energy: France nuclear-dominated, Germany renewable transition, Norway hydro, Denmark wind leader. Energy security: reducing import dependence. Transition: challenges moving from fossil to renewable. Critical minerals: lithium, cobalt, rare earths for batteries and electronics. Resource conflicts: water and mineral disputes. Energy efficiency: reducing waste, improving utilization. EU energy policy.', age: '11-14' },
      { topic: '地图技能与GIS', zh: '学习地图技能和GIS。地图要素：比例尺、图例、方向标、坐标。比例尺类型：数字式、线段式、文字式。等高线：表示地形起伏，等高线间距反映坡度。地形图判读：识别山峰、山谷、山脊、鞍部。坐标系统：经纬度，GPS定位。GIS（地理信息系统）：用计算机存储、分析和展示地理数据。遥感：卫星和航空影像。专题地图：人口图、气候图、经济图。地图投影：墨卡托、等面积投影。数字地图和导航应用。', en: 'Learn about map skills and GIS. Map elements: scale, legend, compass, coordinates. Scale types: ratio, bar, statement. Contour lines: showing relief, spacing indicates slope. Topographic reading: peaks, valleys, ridges, saddles. Coordinate systems: latitude/longitude, GPS. GIS (Geographic Information Systems): computer storage, analysis, display of geographic data. Remote sensing: satellite and aerial imagery. Thematic maps: population, climate, economic. Map projections: Mercator, equal-area. Digital maps and navigation apps.', age: '11-14' }
    ],

    foreignLanguage: [
      { topic: '法语：日常对话进阶', zh: '学习法语日常对话进阶。问候：Comment allez-vous?（您好吗？）、Je vais bien, merci（我很好，谢谢）。自我介绍：Je m\'appelle...（我叫...）、J\'ai ... ans（我...岁）、J\'habite à...（我住在...）。表达喜好：J\'aime/J\'adore（我喜欢/热爱）、Je n\'aime pas（我不喜欢）、Je déteste（我讨厌）。询问方向：Où est...?（...在哪里？）、Comment aller à...?（怎么去...？）。购物：Combien ça coûte?（多少钱？）、Je voudrais...（我想要...）。法语发音规则：联诵、鼻化元音。', en: 'Learn advanced French daily conversation. Greetings: Comment allez-vous? Je vais bien, merci. Self-introduction: Je m\'appelle..., J\'ai ... ans, J\'habite à.... Preferences: J\'aime/J\'adore, Je n\'aime pas, Je déteste. Directions: Où est...? Comment aller à...? Shopping: Combien ça coûte? Je voudrais.... French pronunciation: liaison, nasal vowels.', age: '11-14' },
      { topic: '法语：时态与动词变位', zh: '学习法语时态和动词变位。现在时：je parle（我说）、tu parles、il/elle parle、nous parlons、vous parlez、ils/elles parlent。复合过去时（passé composé）：j\'ai parlé（我说过），由avoir/être+过去分词构成。最近将来时：je vais parler（我将要说）。不规则动词：être（是）、avoir（有）、aller（去）、faire（做）、pouvoir（能）、vouloir（想）。动词变位规律：-er/-ir/-re结尾动词的变位模式。代词式动词：se lever（起床）、se coucher（睡觉）。', en: 'Learn French tenses and verb conjugation. Present: je parle, tu parles, il/elle parle, nous parlons, vous parlez, ils/elles parlent. Passé composé: j\'ai parlé, formed with avoir/être + past participle. Futur proche: je vais parler. Irregular verbs: être, avoir, aller, faire, pouvoir, vouloir. Conjugation patterns: -er/-ir/-re ending verbs. Reflexive verbs: se lever, se coucher.', age: '11-14' },
      { topic: '法语：学校与教育', zh: '学习法语中关于学校和教育的词汇和表达。学校科目：les mathématiques（数学）、le français（法语）、l\'histoire（历史）、les sciences（科学）、l\'anglais（英语）。学校生活：la classe（课堂）、les devoirs（作业）、l\'examen（考试）、la récréation（课间休息）。描述课程：Mon cours préféré est...（我最喜欢的课是...）、J\'ai cours de... à... heures（我...点有...课）。法国教育体系：école maternelle→école élémentaire→collège→lycée。法国学制与英国学制的比较。', en: 'Learn French vocabulary about school and education. Subjects: les mathématiques, le français, l\'histoire, les sciences, l\'anglais. School life: la classe, les devoirs, l\'examen, la récréation. Describing classes: Mon cours préféré est..., J\'ai cours de... à... heures. French education system: école maternelle→école élémentaire→collège→lycée. Comparing French and British school systems.', age: '11-14' },
      { topic: '法语：饮食文化', zh: '学习法语饮食文化。法国饮食：le petit déjeuner（早餐：croissant, pain, café）、le déjeuner（午餐：entrée+plat+dessert）、le dîner（晚餐）。餐厅用语：Je voudrais réserver une table（我想预订一桌）、L\'addition, s\'il vous plaît（请结账）、C\'est délicieux!（真好吃！）。法国特色：le fromage（奶酪，超过300种）、le vin（葡萄酒）、la baguette（法棍面包）、les crêpes（可丽饼）。法国饮食礼仪：面包放桌上、用餐时间长。法国各地区的特色美食。', en: 'Learn French food culture. Meals: le petit déjeuner (croissant, pain, café), le déjeuner (entrée+plat+dessert), le dîner. Restaurant: Je voudrais réserver une table, L\'addition s\'il vous plaît, C\'est délicieux! French specialties: le fromage (300+ varieties), le vin, la baguette, les crêpes. Dining etiquette: bread on table, long meals. Regional specialties across France.', age: '11-14' },
      { topic: '德语：日常对话进阶', zh: '学习德语日常对话进阶。问候：Wie geht es Ihnen?（您好吗？）、Mir geht es gut, danke（我很好，谢谢）。自我介绍：Ich heiße...（我叫...）、Ich komme aus...（我来自...）、Ich wohne in...（我住在...）。表达意见：Ich denke, dass...（我认为...）、Meiner Meinung nach...（依我看...）。请求：Könnten Sie bitte...?（您能...吗？）、Ich möchte...（我想要...）。德语发音：ch的两种发音、ü和ö的发音、词尾e的轻读。德语语序：动词第二位原则。', en: 'Learn advanced German daily conversation. Greetings: Wie geht es Ihnen? Mir geht es gut, danke. Introduction: Ich heiße..., Ich komme aus..., Ich wohne in.... Opinions: Ich denke, dass..., Meiner Meinung nach.... Requests: Könnten Sie bitte...? Ich möchte.... Pronunciation: two ch sounds, ü and ö, final e. Word order: verb-second rule.', age: '11-14' },
      { topic: '德语：语法与格', zh: '学习德语语法和格。德语四格：主格（Nominativ：主语）、宾格（Akkusativ：直接宾语）、与格（Dativ：间接宾语）、属格（Genitiv：所属关系）。冠词变格：der/den/dem/des（阳性）、die/die/der/der（阴性）、das/das/dem/des（中性）。介词支配格：für+Akk（为了）、mit+Dat（和...一起）、von+Dat（从...）。动词变位：ich gehe, du gehst, er/sie geht, wir gehen, ihr geht, sie/Sie gehen。可分动词：aufstehen（起床）→Ich stehe um 7 Uhr auf。', en: 'Learn German grammar and cases. Four cases: Nominativ (subject), Akkusativ (direct object), Dativ (indirect object), Genitiv (possession). Article declension: der/den/dem/des (masc), die/die/der/der (fem), das/das/dem/des (neut). Prepositions: für+Akk, mit+Dat, von+Dat. Conjugation: ich gehe, du gehst, er/sie geht, wir gehen, ihr geht, sie/Sie gehen. Separable verbs: aufstehen→Ich stehe um 7 Uhr auf.', age: '11-14' },
      { topic: '德语：学校与日常生活', zh: '学习德语中关于学校和日常生活的词汇。学校：die Schule（学校）、der Unterricht（课程）、die Hausaufgabe（作业）、die Prüfung（考试）。科目：Mathematik（数学）、Deutsch（德语）、Englisch（英语）、Geschichte（历史）、Naturwissenschaften（自然科学）。日常作息：Ich stehe um... auf（我...点起床）、Ich gehe zur Schule（我去上学）、Nach der Schule...（放学后...）。德国教育体系：Grundschule→Gymnasium/Realschule/Hauptschule。德国学生的典型一天。', en: 'Learn German vocabulary about school and daily life. School: die Schule, der Unterricht, die Hausaufgabe, die Prüfung. Subjects: Mathematik, Deutsch, Englisch, Geschichte, Naturwissenschaften. Daily routine: Ich stehe um... auf, Ich gehe zur Schule, Nach der Schule.... German education: Grundschule→Gymnasium/Realschule/Hauptschule. A typical German student day.', age: '11-14' },
      { topic: '德语：文化与旅行', zh: '学习德语文化和旅行词汇。德国城市：Berlin（柏林：Brandenburger Tor, Mauer）、München（慕尼黑：Oktoberfest）、Hamburg（汉堡：Hafen）。旅行用语：Wo ist der Bahnhof?（火车站在哪？）、Ich möchte eine Fahrkarte nach...（我想买一张去...的票）、Gibt es hier ein Hotel?（这里有酒店吗？）。德国文化：das Oktoberfest（啤酒节）、der Weihnachtsmarkt（圣诞市场）、die Klassische Musik（古典音乐：Bach, Beethoven, Mozart）。奥地利和瑞士的德语差异。', en: 'Learn German culture and travel vocabulary. Cities: Berlin (Brandenburger Tor, Mauer), München (Oktoberfest), Hamburg (Hafen). Travel: Wo ist der Bahnhof? Ich möchte eine Fahrkarte nach..., Gibt es hier ein Hotel? Culture: das Oktoberfest, der Weihnachtsmarkt, die Klassische Musik (Bach, Beethoven, Mozart). Austrian and Swiss German differences.', age: '11-14' },
      { topic: '西班牙语：基础对话', zh: '学习西班牙语基础对话。问候：¿Hola, qué tal?（你好，怎么样？）、Estoy bien, gracias（我很好，谢谢）。自我介绍：Me llamo...（我叫...）、Soy de...（我来自...）、Tengo... años（我...岁）。日常用语：Por favor（请）、Gracias（谢谢）、De nada（不客气）、Lo siento（对不起）、Perdón（抱歉）。数字1-100。星期和月份。天气：Hace sol（晴天）、Hace frío（很冷）、Está lloviendo（在下雨）。西班牙语发音：rr的颤音、ñ的发音、重音规则。', en: 'Learn basic Spanish conversation. Greetings: ¿Hola, qué tal? Estoy bien, gracias. Introduction: Me llamo..., Soy de..., Tengo... años. Daily expressions: Por favor, Gracias, De nada, Lo siento, Perdón. Numbers 1-100. Days and months. Weather: Hace sol, Hace frío, Está lloviendo. Pronunciation: rolled rr, ñ, accent rules.', age: '11-14' },
      { topic: '西班牙语：动词变位与过去时', zh: '学习西班牙语动词变位和过去时。现在时变位：-ar动词（hablar: hablo, hablas, habla, hablamos, habláis, hablan）、-er动词（comer）、-ir动词（vivir）。不规则动词：ser（是）、estar（在/状态）、tener（有）、ir（去）、hacer（做）。简单过去时（pretérito indefinido）：hablé, hablaste, habló, hablamos, hablasteis, hablaron。现在完成时（pretérito perfecto）：he hablado（我说过）。将来时：hablaré（我将说）。', en: 'Learn Spanish verb conjugation and past tenses. Present: -ar verbs (hablar: hablo, hablas, habla, hablamos, habláis, hablan), -er (comer), -ir (vivir). Irregular: ser, estar, tener, ir, hacer. Simple past (pretérito indefinido): hablé, hablaste, habló, hablamos, hablasteis, hablaron. Present perfect (pretérito perfecto): he hablado. Future: hablaré.', age: '11-14' },
      { topic: '法语：旅行与交通', zh: '学习法语旅行和交通词汇。交通方式：le train（火车）、le bus（公交车）、le métro（地铁）、l\'avion（飞机）、le bateau（船）。购票：Un billet pour..., s\'il vous plaît（请买一张去...的票）、Aller-retour（往返票）。问路：Tournez à gauche/droite（左转/右转）、Continuez tout droit（直走）、C\'est à environ... minutes（大约...分钟）。住宿：J\'ai une réservation（我有预订）、Une chambre pour... personnes（...人房间）。法国交通系统：TGV高铁、巴黎地铁。', en: 'Learn French travel and transport vocabulary. Transport: le train, le bus, le métro, l\'avion, le bateau. Tickets: Un billet pour..., s\'il vous plaît, Aller-retour. Directions: Tournez à gauche/droite, Continuez tout droit, C\'est à environ... minutes. Accommodation: J\'ai une réservation, Une chambre pour... personnes. French transport: TGV, Paris Métro.', age: '11-14' },
      { topic: '法语：媒体与文化', zh: '学习法语媒体和文化词汇。媒体：le journal（报纸）、la télévision（电视）、le film（电影）、la musique（音乐）、Internet（互联网）。表达观点：À mon avis...（在我看来...）、Je pense que...（我认为...）、Je suis d\'accord（我同意）、Je ne suis pas d\'accord（我不同意）。法国文化：le cinéma français（法国电影）、la bande dessinée（漫画）、la chanson française（法语歌曲）。著名法国人：Victor Hugo、Marie Curie、Zidane。法语世界的多样性：魁北克、西非。', en: 'Learn French media and culture vocabulary. Media: le journal, la télévision, le film, la musique, Internet. Expressing opinions: À mon avis..., Je pense que..., Je suis d\'accord, Je ne suis pas d\'accord. French culture: le cinéma français, la bande dessinée, la chanson française. Famous French people: Victor Hugo, Marie Curie, Zidane. Francophone diversity: Quebec, West Africa.', age: '11-14' },
      { topic: '德语：购物与饮食', zh: '学习德语购物和饮食词汇。购物：Ich möchte... kaufen（我想买...）、Was kostet das?（多少钱？）、Haben Sie...?（您有...吗？）、Zu teuer!（太贵了！）。食品：das Brot（面包）、die Wurst（香肠）、der Käse（奶酪）、der Apfel（苹果）、das Wasser（水）、der Kaffee（咖啡）。餐厅：Ich hätte gern...（我想要...）、Die Rechnung, bitte（请结账）、Es schmeckt gut（很好吃）。德国特色：der Kuchen（蛋糕）、die Brezel（椒盐卷饼）、der Apfelstrudel（苹果卷）。度量衡：ein Pfund（500克）、ein Kilo。', en: 'Learn German shopping and food vocabulary. Shopping: Ich möchte... kaufen, Was kostet das?, Haben Sie...?, Zu teuer! Food: das Brot, die Wurst, der Käse, der Apfel, das Wasser, der Kaffee. Restaurant: Ich hätte gern..., Die Rechnung bitte, Es schmeckt gut. German specialties: der Kuchen, die Brezel, der Apfelstrudel. Measurements: ein Pfund (500g), ein Kilo.', age: '11-14' },
      { topic: '德语：健康与身体', zh: '学习德语健康和身体词汇。身体部位：der Kopf（头）、die Schulter（肩）、der Arm（手臂）、das Bein（腿）、der Fuß（脚）、der Rücken（背）。健康问题：Ich habe Kopfschmerzen（我头痛）、Ich bin krank（我生病了）、Mir ist heiß/kalt（我觉得热/冷）。就医：Ich möchte einen Termin（我想预约）、Der Arzt（医生）、die Apotheke（药房）。健康建议：Du sollst...（你应该...）、Gesund essen（健康饮食）、Sport treiben（做运动）。德国医疗体系简介。', en: 'Learn German health and body vocabulary. Body: der Kopf, die Schulter, der Arm, das Bein, der Fuß, der Rücken. Health issues: Ich habe Kopfschmerzen, Ich bin krank, Mir ist heiß/kalt. Medical: Ich möchte einen Termin, Der Arzt, die Apotheke. Health advice: Du sollst..., Gesund essen, Sport treiben. Introduction to German healthcare system.', age: '11-14' },
      { topic: '西班牙语：学校与爱好', zh: '学习西班牙语学校和爱好词汇。学校：la escuela（学校）、la clase（课堂）、el profesor/la profesora（老师）、el examen（考试）、la tarea（作业）。爱好：me gusta jugar al fútbol（我喜欢踢足球）、me encanta leer（我热爱阅读）、tocar la guitarra（弹吉他）、bailar（跳舞）、nadar（游泳）、dibujar（画画）。描述活动：¿Qué te gusta hacer?（你喜欢做什么？）、Mi pasatiempo favorito es...（我最喜欢的爱好是...）。西班牙语国家的学校生活。', en: 'Learn Spanish school and hobby vocabulary. School: la escuela, la clase, el profesor/la profesora, el examen, la tarea. Hobbies: me gusta jugar al fútbol, me encanta leer, tocar la guitarra, bailar, nadar, dibujar. Describing activities: ¿Qué te gusta hacer? Mi pasatiempo favorito es.... School life in Spanish-speaking countries.', age: '11-14' },
      { topic: '西班牙语：家庭与描述人物', zh: '学习西班牙语家庭和人物描述。家庭：la madre（母亲）、el padre（父亲）、el hermano/la hermana（兄弟/姐妹）、los abuelos（祖父母）、el tío/la tía（叔/姨）。描述人物：Es alto/bajo（他/她高/矮）、Es rubio/moreno（金发/棕发）、Tiene los ojos azules/marrones（蓝/棕色眼睛）、Es simpático/antipático（友善/不友善）。性格：Es trabajador（勤奋）、Es perezoso（懒惰）、Es divertido（有趣）、Es serio（严肃）。物主形容词：mi, tu, su, nuestro, vuestro。', en: 'Learn Spanish family and describing people. Family: la madre, el padre, el hermano/la hermana, los abuelos, el tío/la tía. Descriptions: Es alto/bajo, Es rubio/moreno, Tiene los ojos azules/marrones, Es simpático/antipático. Personality: Es trabajador, Es perezoso, Es divertido, Es serio. Possessive adjectives: mi, tu, su, nuestro, vuestro.', age: '11-14' },
      { topic: '法语：过去时与未来时', zh: '学习法语过去时和未来时。复合过去时：j\'ai mangé（我吃了）、je suis allé(e)（我去了）。用être的动词：aller, venir, arriver, partir, monter, descendre, naître, mourir, entrer, sortir, passer, retourner, tomber, rester, devenir。未完成过去时（imparfait）：je mangeais（我当时在吃），描述过去的状态和习惯。简单将来时：je mangerai（我将吃）。条件式：je mangerais（我会吃）。时态选择：passé composé vs imparfait的区别——完成动作vs持续状态。', en: 'Learn French past and future tenses. Passé composé: j\'ai mangé, je suis allé(e). Être verbs: aller, venir, arriver, partir, monter, descendre, naître, mourir, entrer, sortir, passer, retourner, tomber, rester, devenir. Imparfait: je mangeais, describing past states and habits. Futur simple: je mangerai. Conditionnel: je mangerais. Tense choice: passé composé vs imparfait—completed action vs ongoing state.', age: '12-14' },
      { topic: '法语：环境与社会', zh: '学习法语环境和社会词汇。环境：l\'environnement（环境）、la pollution（污染）、le changement climatique（气候变化）、les énergies renouvelables（可再生能源）、recycler（回收）。社会问题：la pauvreté（贫困）、l\'égalité（平等）、les droits de l\'homme（人权）。表达观点：Il faut...（必须...）、On devrait...（我们应该...）、C\'est important de...（...很重要）。法国环保政策：la transition énergétique（能源转型）。法语辩论：如何用法语进行简单辩论和论证。', en: 'Learn French environment and society vocabulary. Environment: l\'environnement, la pollution, le changement climatique, les énergies renouvelables, recycler. Social issues: la pauvreté, l\'égalité, les droits de l\'homme. Opinions: Il faut..., On devrait..., C\'est important de.... French environmental policy: la transition énergétique. French debate: how to conduct simple debates and arguments in French.', age: '12-14' },
      { topic: '德语：过去时与完成时', zh: '学习德语过去时和完成时。完成时（Perfekt）：Ich habe gegessen（我吃了）、Ich bin gegangen（我走了）。构成：haben/sein + 过去分词。过去分词构成：ge- + 词干 + -t/-en。用sein的动词：表示移动或状态变化的动词（gehen, kommen, fahren, fliegen, aufwachen）。简单过去时（Präteritum）：ich ging, du gingst, er ging（主要用于书面语）。情态动词的过去时：ich konnte（我能）、ich musste（我必须）、ich wollte（我想）。时态选择：口语用Perfekt，书面用Präteritum。', en: 'Learn German past and perfect tenses. Perfekt: Ich habe gegessen, Ich bin gegangen. Formation: haben/sein + past participle. Participle: ge- + stem + -t/-en. Sein verbs: movement/state change (gehen, kommen, fahren, fliegen, aufwachen). Präteritum: ich ging, du gingst, er ging (mainly written). Modal past: ich konnte, ich musste, ich wollte. Tense choice: spoken Perfekt, written Präteritum.', age: '12-14' },
      { topic: '德语：环境与未来', zh: '学习德语环境和未来话题。环境：die Umwelt（环境）、der Umweltschutz（环境保护）、die Luftverschmutzung（空气污染）、der Klimawandel（气候变化）、die erneuerbaren Energien（可再生能源）。未来计划：Ich möchte... werden（我想成为...）、In der Zukunft werde ich...（将来我会...）、Mein Traum ist...（我的梦想是...）。职业：der Arzt/die Ärztin（医生）、der Ingenieur（工程师）、der Lehrer/die Lehrerin（老师）。德国环保：die Energiewende（能源转型）、das Recycling-System（回收系统）。', en: 'Learn German environment and future topics. Environment: die Umwelt, der Umweltschutz, die Luftverschmutzung, der Klimawandel, die erneuerbaren Energien. Future plans: Ich möchte... werden, In der Zukunft werde ich..., Mein Traum ist.... Professions: der Arzt/die Ärztin, der Ingenieur, der Lehrer/die Lehrerin. German environmentalism: die Energiewende, das Recycling-System.', age: '12-14' },
      { topic: '西班牙语：城市与方向', zh: '学习西班牙语城市和方向词汇。城市：la ciudad（城市）、la calle（街道）、la plaza（广场）、el parque（公园）、la iglesia（教堂）、el museo（博物馆）、el mercado（市场）。方向：a la derecha（右边）、a la izquierda（左边）、todo recto（直走）、cerca（近）、lejos（远）、entre（之间）、delante de（前面）、detrás de（后面）。描述城市：Mi ciudad es grande/pequeña（我的城市大/小）、Es muy animada（很热闹）、Hay muchos...（有很多...）。马德里和巴塞罗那介绍。', en: 'Learn Spanish city and direction vocabulary. City: la ciudad, la calle, la plaza, el parque, la iglesia, el museo, el mercado. Directions: a la derecha, a la izquierda, todo recto, cerca, lejos, entre, delante de, detrás de. Describing cities: Mi ciudad es grande/pequeña, Es muy animada, Hay muchos.... Introduction to Madrid and Barcelona.', age: '11-14' }
    ]
  }
};

window.curriculumData = curriculumData;